@Test
public void clusterRestartAfterUpdateDataNodeTest() throws InterruptedException, ClientManagerException, IOException, TException {
    // Create default Database
    try (SyncConfigNodeIServiceClient client = (SyncConfigNodeIServiceClient) EnvFactory.getEnv().getLeaderConfigNodeConnection()) {
        TSStatus status = client.setDatabase(new TDatabaseSchema("root.database"));
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), status.getCode());
    }
    // Create some DataPartitions to extend 2 DataRegionGroups
    Map<String, Map<TSeriesPartitionSlot, TTimeSlotList>> partitionSlotsMap = ConfigNodeTestUtils.constructPartitionSlotsMap("root.database", 0, 10, 0, 10, testTimePartitionInterval);
    TDataPartitionReq dataPartitionReq = new TDataPartitionReq(partitionSlotsMap);
    TDataPartitionTableResp dataPartitionTableResp = null;
    for (int retry = 0; retry < 5; retry++) {
        // Build new Client since it's unstable in Win8 environment
        try (SyncConfigNodeIServiceClient configNodeClient = (SyncConfigNodeIServiceClient) EnvFactory.getEnv().getLeaderConfigNodeConnection()) {
            dataPartitionTableResp = configNodeClient.getOrCreateDataPartitionTable(dataPartitionReq);
            if (dataPartitionTableResp != null) {
                break;
            }
        } catch (Exception e) {
            // Retry sometimes in order to avoid request timeout
            logger.error(e.getMessage());
            TimeUnit.SECONDS.sleep(1);
        }
    }
    Assert.assertNotNull(dataPartitionTableResp);
    Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), dataPartitionTableResp.getStatus().getCode());
    Assert.assertNotNull(dataPartitionTableResp.getDataPartitionTable());
    ConfigNodeTestUtils.checkDataPartitionTable("root.database", 0, 10, 0, 10, testTimePartitionInterval, dataPartitionTableResp.getDataPartitionTable());
    // Shutdown all DataNodes
    EnvFactory.getEnv().shutdownAllDataNodes();
    TimeUnit.SECONDS.sleep(1);
    List<DataNodeWrapper> dataNodeWrapperList = EnvFactory.getEnv().getDataNodeWrapperList();
    for (int i = 0; i < testDataNodeNum; i++) {
        // Modify DataNode clientRpcEndPoint
        int[] portList = EnvUtils.searchAvailablePorts();
        dataNodeWrapperList.get(i).setPort(portList[0]);
        // Update DataNode files' names
        dataNodeWrapperList.get(i).renameFile();
    }
    // Restart DataNodes
    for (int i = 0; i < testDataNodeNum; i++) {
        dataNodeWrapperList.get(i).changeConfig((MppBaseConfig) EnvFactory.getEnv().getConfig().getDataNodeConfig(), (MppCommonConfig) EnvFactory.getEnv().getConfig().getDataNodeCommonConfig(), (MppJVMConfig) EnvFactory.getEnv().getConfig().getDataNodeJVMConfig());
        EnvFactory.getEnv().startDataNode(i);
    }
    // Check DataNode status
    EnvFactory.getEnv().ensureNodeStatus(Arrays.asList(EnvFactory.getEnv().getDataNodeWrapper(0), EnvFactory.getEnv().getDataNodeWrapper(1)), Arrays.asList(NodeStatus.Running, NodeStatus.Running));
    // Check DataNode EndPoint
    try (SyncConfigNodeIServiceClient client = (SyncConfigNodeIServiceClient) EnvFactory.getEnv().getLeaderConfigNodeConnection()) {
        // Check update in NodeInfo
        TShowClusterResp showClusterResp = client.showCluster();
        ConfigNodeTestUtils.checkNodeConfig(showClusterResp.getConfigNodeList(), showClusterResp.getDataNodeList(), EnvFactory.getEnv().getConfigNodeWrapperList(), dataNodeWrapperList);
        // Check update in PartitionInfo
        TShowRegionResp showRegionResp = client.showRegion(new TShowRegionReq());
        showRegionResp.getRegionInfoList().forEach(regionInfo -> {
            AtomicBoolean matched = new AtomicBoolean(false);
            dataNodeWrapperList.forEach(dataNodeWrapper -> {
                if (regionInfo.getClientRpcPort() == dataNodeWrapper.getPort()) {
                    matched.set(true);
                }
            });
            Assert.assertTrue(matched.get());
        });
    }
}

