@Test
public void clusterIdTest() throws ClientManagerException, IOException, InterruptedException, SQLException {
    final long maxTestTime = TimeUnit.SECONDS.toMillis(30);
    final long testInterval = TimeUnit.SECONDS.toMillis(1);
    try (SyncConfigNodeIServiceClient client = (SyncConfigNodeIServiceClient) EnvFactory.getEnv().getLeaderConfigNodeConnection();
        Connection connection = EnvFactory.getEnv().getConnection();
        Statement statement = connection.createStatement()) {
        long startTime = System.currentTimeMillis();
        boolean testPass = false;
        String clusterIdFromConfigNode = null;
        while (System.currentTimeMillis() - startTime < maxTestTime) {
            try {
                TGetClusterIdResp resp = client.getClusterId();
                if (TSStatusCode.SUCCESS_STATUS.getStatusCode() == resp.getStatus().getCode()) {
                    Assert.assertNotNull(resp.getClusterId());
                    Assert.assertNotEquals("", resp.getClusterId());
                    clusterIdFromConfigNode = resp.getClusterId();
                    testPass = true;
                    break;
                }
            } catch (TException e) {
                logger.error("TException:", e);
            }
            Thread.sleep(testInterval);
        }
        if (!testPass) {
            String errorMessage = String.format("Cluster ID failed to generate in %d ms.", maxTestTime);
            Assert.fail(errorMessage);
        }
        ResultSet resultSet = statement.executeQuery("show clusterid");
        resultSet.next();
        Assert.assertEquals(clusterIdFromConfigNode, resultSet.getString(1));
    }
}

@Test
public void testDefaultRegionGroupNumControl() throws SQLException, ClientManagerException, IOException, InterruptedException, TException {
    try (final Connection connection = EnvFactory.getEnv().getConnection();
        final Statement statement = connection.createStatement();
        final SyncConfigNodeIServiceClient configNodeClient = (SyncConfigNodeIServiceClient) EnvFactory.getEnv().getLeaderConfigNodeConnection()) {
        // Initialize test data
        final String database = "root.paradise0";
        String createDatabaseSQL = String.format("CREATE DATABASE %s;", database);
        statement.execute(createDatabaseSQL);
        insertBatchData(statement, database, 0);
        // Check RegionGroupNum, which should be equal to the default value
        TShowRegionResp resp = configNodeClient.showRegion(new TShowRegionReq().setDatabases(Collections.singletonList(database)));
        AtomicInteger schemaRegionGroupNum = new AtomicInteger(0);
        AtomicInteger dataRegionGroupNum = new AtomicInteger(0);
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), resp.getStatus().getCode());
        resp.getRegionInfoList().forEach(regionInfo -> {
            switch(regionInfo.getConsensusGroupId().getType()) {
                case SchemaRegion:
                    schemaRegionGroupNum.getAndIncrement();
                    break;
                case DataRegion:
                default:
                    dataRegionGroupNum.getAndIncrement();
                    break;
            }
        });
