@Test
public void testMultiDatabaseLeaderDistribution() throws ClientManagerException, IOException, InterruptedException, TException {
    try (SyncConfigNodeIServiceClient client = (SyncConfigNodeIServiceClient) EnvFactory.getEnv().getLeaderConfigNodeConnection()) {
        for (int i = 0; i < TEST_DATABASE_NUM; i++) {
            String curDb = DATABASE + i;
            TSStatus status = client.setDatabase(new TDatabaseSchema(curDb).setMinDataRegionGroupNum(TEST_MIN_DATA_REGION_GROUP_NUM));
            Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), status.getCode());
            // Insert DataPartitions to create DataRegionGroups
            Map<String, Map<TSeriesPartitionSlot, TTimeSlotList>> partitionSlotsMap = ConfigNodeTestUtils.constructPartitionSlotsMap(curDb, 0, 10, 0, 10, TEST_TIME_PARTITION_INTERVAL);
            TDataPartitionTableResp dataPartitionTableResp = client.getOrCreateDataPartitionTable(new TDataPartitionReq(partitionSlotsMap));
            Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), dataPartitionTableResp.getStatus().getCode());
        }
        final int retryNum = 50;
        for (int retry = 0; retry < retryNum; retry++) {
            // Check the number of RegionGroup-leader in each DataNode.
            Map<Integer, Integer> dataNodeLeaderCounter = new TreeMap<>();
            Map<String, Map<Integer, Integer>> databaseLeaderCounter = new TreeMap<>();
            TShowRegionResp showRegionResp = client.showRegion(new TShowRegionReq());
            showRegionResp.getRegionInfoList().forEach(regionInfo -> {
                if (RegionRoleType.Leader.getRoleType().equals(regionInfo.getRoleType())) {
                    dataNodeLeaderCounter.merge(regionInfo.getDataNodeId(), 1, Integer::sum);
                    databaseLeaderCounter.computeIfAbsent(regionInfo.getDatabase(), k -> new TreeMap<>()).merge(regionInfo.getDataNodeId(), 1, Integer::sum);
                }
            });
            AtomicBoolean pass = new AtomicBoolean(true);
            // The number of Region-leader in each DataNode should be equal
            if (dataNodeLeaderCounter.size() != TEST_DATA_NODE_NUM) {
                pass.set(false);
            }
            if (dataNodeLeaderCounter.values().stream().max(Integer::compareTo).orElse(0) - dataNodeLeaderCounter.values().stream().min(Integer::compareTo).orElse(0) > 1) {
                pass.set(false);
            }
            // The number of Region-leader in each DataNode within the same Database should be equal
            if (TEST_DATABASE_NUM != databaseLeaderCounter.size()) {
                pass.set(false);
            }
            databaseLeaderCounter.forEach((database, leaderCounter) -> {
                if (leaderCounter.values().stream().max(Integer::compareTo).orElse(0) - leaderCounter.values().stream().min(Integer::compareTo).orElse(0) > 1) {
                    pass.set(false);
                }
            });
            if (pass.get()) {
                return;
            }
            TimeUnit.SECONDS.sleep(1);
        }
        Assert.fail("The leader distribution is not balanced after " + retryNum + " retries.");
    }
}

