@Test
public void testDataPartitionInheritPolicy() throws Exception {
    final long baseStartTime = 1000;
    Map<TSeriesPartitionSlot, TConsensusGroupId> dataAllotTable1 = new ConcurrentHashMap<>();
    // Test1: divide and inherit DataPartitions from scratch
    for (long timePartitionSlot = baseStartTime; timePartitionSlot < baseStartTime + testTimePartitionSlotsNum; timePartitionSlot++) {
        for (int seriesPartitionSlot = 0; seriesPartitionSlot < testSeriesSlotNum; seriesPartitionSlot += seriesPartitionSlotBatchSize) {
            ConfigNodeTestUtils.getOrCreateDataPartitionWithRetry(database, seriesPartitionSlot, seriesPartitionSlot + seriesPartitionSlotBatchSize, timePartitionSlot, timePartitionSlot + 1, testTimePartitionInterval);
        }
    }
    int mu = (int) (testSeriesSlotNum / testDataRegionPerDataNode);
    TDataPartitionTableResp dataPartitionTableResp = ConfigNodeTestUtils.getDataPartitionWithRetry(database, 0, testSeriesSlotNum, baseStartTime, baseStartTime + testTimePartitionSlotsNum, testTimePartitionInterval);
    Assert.assertNotNull(dataPartitionTableResp);
    // All DataRegionGroups divide all SeriesSlots evenly
    final int expectedPartitionNum1 = mu * testTimePartitionSlotsNum;
    Map<TConsensusGroupId, Integer> counter = ConfigNodeTestUtils.countDataPartition(dataPartitionTableResp.getDataPartitionTable().get(database));
    counter.forEach((groupId, num) -> Assert.assertEquals(expectedPartitionNum1, num.intValue()));
    // Test DataPartition inherit policy
    dataPartitionTableResp.getDataPartitionTable().get(database).forEach(((seriesPartitionSlot, timePartitionSlotMap) -> {
        // All Timeslots belonging to the same SeriesSlot are allocated to the same
        // DataRegionGroup
        TConsensusGroupId groupId = timePartitionSlotMap.get(new TTimePartitionSlot(baseStartTime * testTimePartitionInterval)).get(0);
        timePartitionSlotMap.forEach((timePartitionSlot, groupIdList) -> Assert.assertEquals(groupId, groupIdList.get(0)));
        dataAllotTable1.put(seriesPartitionSlot, groupId);
    }));
    // Register a new DataNode to extend DataRegionGroups
    EnvFactory.getEnv().registerNewDataNode(true);
    // Test2: divide and inherit DataPartitions after extension
    mu = (int) (testSeriesSlotNum / (testDataRegionPerDataNode * 2));
    dataPartitionTableResp = ConfigNodeTestUtils.getOrCreateDataPartitionWithRetry(database, 0, testSeriesSlotNum, baseStartTime + testTimePartitionSlotsNum, baseStartTime + testTimePartitionSlotsNum + timePartitionBatchSize, testTimePartitionInterval);
    Assert.assertNotNull(dataPartitionTableResp);
    // All DataRegionGroups divide all SeriesSlots evenly
    counter = ConfigNodeTestUtils.countDataPartition(dataPartitionTableResp.getDataPartitionTable().get(database));
    final int expectedPartitionNum2 = mu * timePartitionBatchSize;
    counter.forEach((groupId, num) -> Assert.assertEquals(expectedPartitionNum2, num.intValue()));
    // Test DataPartition inherit policy
    AtomicInteger inheritedSeriesSlotNum = new AtomicInteger(0);
    Map<TSeriesPartitionSlot, TConsensusGroupId> dataAllotTable2 = new ConcurrentHashMap<>();
    dataPartitionTableResp.getDataPartitionTable().get(database).forEach(((seriesPartitionSlot, timePartitionSlotMap) -> {
        // All Timeslots belonging to the same SeriesSlot are allocated to the same
        // DataRegionGroup
        TConsensusGroupId groupId = timePartitionSlotMap.get(new TTimePartitionSlot((baseStartTime + testTimePartitionSlotsNum) * testTimePartitionInterval)).get(0);
        timePartitionSlotMap.forEach((timePartitionSlot, groupIdList) -> Assert.assertEquals(groupId, groupIdList.get(0)));
        if (dataAllotTable1.containsValue(groupId)) {
            // The DataRegionGroup has been inherited
            Assert.assertTrue(dataAllotTable1.containsKey(seriesPartitionSlot));
            Assert.assertEquals(dataAllotTable1.get(seriesPartitionSlot), groupId);
            inheritedSeriesSlotNum.incrementAndGet();
        }
        dataAllotTable2.put(seriesPartitionSlot, groupId);
    }));
    // Exactly half of the SeriesSlots are inherited
    Assert.assertEquals(testSeriesSlotNum / 2, inheritedSeriesSlotNum.get());
    // Test3: historical DataPartitions will inherit successor
    Random random = new Random();
    Set<Integer> allocatedSlots = new HashSet<>();
    for (int i = 0; i < 10; i++) {
        int slot = random.nextInt(testSeriesSlotNum);
        while (allocatedSlots.contains(slot)) {
            slot = random.nextInt(testSeriesSlotNum);
        }
        allocatedSlots.add(slot);
        dataPartitionTableResp = ConfigNodeTestUtils.getOrCreateDataPartitionWithRetry(database, slot, slot + 1, baseStartTime - 1, baseStartTime, testTimePartitionInterval);
        Assert.assertNotNull(dataPartitionTableResp);
        TSeriesPartitionSlot seriesPartitionSlot = new TSeriesPartitionSlot(slot);
        TTimePartitionSlot timePartitionSlot = new TTimePartitionSlot((baseStartTime - 1) * testTimePartitionInterval);
        Assert.assertEquals(dataAllotTable1.get(seriesPartitionSlot), dataPartitionTableResp.getDataPartitionTable().get(database).get(seriesPartitionSlot).get(timePartitionSlot).get(0));
    }
    // Test4: future DataPartitions will inherit predecessor
    allocatedSlots.clear();
    for (int i = 0; i < 10; i++) {
        int slot = random.nextInt(testSeriesSlotNum);
        while (allocatedSlots.contains(slot)) {
            slot = random.nextInt(testSeriesSlotNum);
        }
        allocatedSlots.add(slot);
        dataPartitionTableResp = ConfigNodeTestUtils.getOrCreateDataPartitionWithRetry(database, slot, slot + 1, baseStartTime + 999, baseStartTime + 1000, testTimePartitionInterval);
        Assert.assertNotNull(dataPartitionTableResp);
        TSeriesPartitionSlot seriesPartitionSlot = new TSeriesPartitionSlot(slot);
        TTimePartitionSlot timePartitionSlot = new TTimePartitionSlot((baseStartTime + 999) * testTimePartitionInterval);
        Assert.assertEquals(dataAllotTable2.get(seriesPartitionSlot), dataPartitionTableResp.getDataPartitionTable().get(database).get(seriesPartitionSlot).get(timePartitionSlot).get(0));
    }
}

