    expectedHeader = new String[] { "Count_if(root.db.d1.s1 = 0 & root.db.d1.s2 = 0, keep >= 3, \"ignoreNull\"=\"true\")", "Count_if(root.db.d1.s1 = 1 & root.db.d1.s2 = 0, keep >= 3)" };
