    retArray = new String[] { "0,0," };
    resultSetEqualTest("select Count_if(s1=0 & s2=0, keep<3, 'ignoreNull'='true'), Count_if(s1=1 & s2=0, keep<3) from root.db.d1", expectedHeader, retArray);
}

