@Test
public void testTimeDurationSingleColumnOnOneDataRegion() {
    // normal
    String[] expectedHeader = new String[] { "time_duration(root.db.d1.s1)" };
    String[] retArray = new String[] { "8," };
    resultSetEqualTest("select time_duration(s1) from root.db.d1 where time < 10", expectedHeader, retArray);
    // order by time desc
    resultSetEqualTest("select time_duration(s1) from root.db.d1  where time < 10 order by time desc", expectedHeader, retArray);
    // order by time asc
    resultSetEqualTest("select time_duration(s1) from root.db.d1  where time < 10 order by time asc", expectedHeader, retArray);
    // limit
    resultSetEqualTest("select time_duration(s1) from root.db.d1  where time < 10 limit 3", expectedHeader, retArray);
    // align by device
    expectedHeader = new String[] { "Device", "time_duration(s1)" };
    retArray = new String[] { "root.db.d1,8," };
    resultSetEqualTest("select time_duration(s1) from root.db.d1  where time < 10 align by device", expectedHeader, retArray);
    // align by time
    expectedHeader = new String[] { "time_duration(root.db.d1.s1)" };
    retArray = new String[] { "8," };
    resultSetEqualTest("select time_duration(s1) from root.db.d1  where time < 10 align by time", expectedHeader, retArray);
    // group by level=1(database)
    expectedHeader = new String[] { "time_duration(root.db1.*.s1),time_duration(root.db.*.s1)" };
    retArray = new String[] { "8,8," };
    resultSetEqualTest("select time_duration(s1) from root.** where time < 10 group by level=1", expectedHeader, retArray);
    // group by level=2(device)
    expectedHeader = new String[] { "time_duration(root.*.d1.s1)", "time_duration(root.*.d2.s1)" };
    retArray = new String[] { "8,8," };
    resultSetEqualTest("select time_duration(s1) from root.** where time < 10 group by level=2", expectedHeader, retArray);
    // group by session
    expectedHeader = new String[] { "Time", "time_duration(root.db1.d1.s1)" };
    retArray = new String[] { "3,6," };
    // ignore = true
    resultSetEqualTest("select time_duration(s1) from root.db1.d1 where time<10 group by session(100ms)", expectedHeader, retArray);
    // group by variation
    expectedHeader = new String[] { "Time", "time_duration(root.db1.d2.s1)" };
    retArray = new String[] { "1,0,", "3,null,", "4,0,", "6,0,", "7,0,", "8,0,", "9,null," };
    resultSetEqualTest("select time_duration(s1) from root.db1.d2 where time<10 group by variation(root.db.d1.s1)", expectedHeader, retArray);
    // group by condition
    expectedHeader = new String[] { "Time", "time_duration(root.db1.d2.s1)" };
    retArray = new String[] { "1,9," };
    resultSetEqualTest("select time_duration(s1) from root.db1.d2 group by condition(root.db.d2.s1 > 10,KEEP>=1,ignoreNull=true)", expectedHeader, retArray);
    // group by tags
    expectedHeader = new String[] { "city", "time_duration(s1)" };
    retArray = new String[] { "Nanjing,1677570938," };
    resultSetEqualTest("select time_duration(s1) from root.db1.d2 group by tags(city)", expectedHeader, retArray);
    // group by time
    expectedHeader = new String[] { "Time", "time_duration(root.db1.d2.s1)" };
    retArray = new String[] { "1,3,", "6,2," };
    resultSetEqualTest("select time_duration(s1) from root.db1.d2 group by time([1,10),5ms)", expectedHeader, retArray);
}

