    resultSetEqualTest("SELECT max_time(s1), last_value(s1), last_value(s2) FROM root.sg1.** where s3+1=1316 or s2=false having avg(s1)>2 align by device;", expectedHeader, retArray);
    retArray = new String[] { "root.sg2.d2,1314000000001,13.15,false,", "root.sg2.d3,1314000000002,13.16,false,", "root.sg2.d4,5,5555.5,false," };
