    retArray = new String[] { "root.sg2.d2,1314000000001,13.15,4,11,", "root.sg2.d3,1314000000002,13.16,2,4,", "root.sg2.d4,5,5555.5,1,5555," };
    resultSetEqualTest("SELECT max_time(s1), last_value(s1), count(s2), first_value(s3) FROM root.sg2.** where s3+1=1316 or s2=false having avg(s1)>2 align by device;", expectedHeader, retArray);
    // duplicate select expressions
    expectedHeader = new String[] { "Device,max_time(s1),last_value(s1),count(s2),first_value(s3),last_value(s1)" };
    retArray = new String[] { "root.sg1.d2,1314000000001,13.15,4,11,13.15,", "root.sg1.d3,1314000000002,13.16,2,4,13.16,", "root.sg1.d4,5,5555.5,1,5555,5555.5," };
    resultSetEqualTest("SELECT max_time(s1), last_value(s1), count(s2), first_value(s3), last_value(s1) FROM root.sg1.** where s3+1=1316 or s2=false having avg(s1)>2 align by device;", expectedHeader, retArray);
    retArray = new String[] { "root.sg2.d2,1314000000001,13.15,4,11,13.15,", "root.sg2.d3,1314000000002,13.16,2,4,13.16,", "root.sg2.d4,5,5555.5,1,5555,5555.5," };
    resultSetEqualTest("SELECT max_time(s1), last_value(s1), count(s2), first_value(s3), last_value(s1) FROM root.sg2.** where s3+1=1316 or s2=false having avg(s1)>2 align by device;", expectedHeader, retArray);
    // alias
    expectedHeader = new String[] { "Device,c1,first_value(s3),c2" };
    retArray = new String[] { "root.sg1.d2,4,11,4,", "root.sg1.d3,2,4,2,", "root.sg1.d4,1,5555,1," };
    resultSetEqualTest("SELECT count(s1) as c1, first_value(s3), count(s1) as c2 FROM root.sg1.** where s3+1=1316 or s2=false having avg(s1)>2 align by device;", expectedHeader, retArray);
    retArray = new String[] { "root.sg2.d2,4,11,4,", "root.sg2.d3,2,4,2,", "root.sg2.d4,1,5555,1," };
    resultSetEqualTest("SELECT count(s1) as c1, first_value(s3), count(s1) as c2 FROM root.sg2.** where s3+1=1316 or s2=false having avg(s1)>2 align by device;", expectedHeader, retArray);
    // arithmetic expression
    expectedHeader = new String[] { "Device,max_time(s1),count(s1),last_value(s2),count(s1) + last_value(s3)" };
    retArray = new String[] { "root.sg1.d2,1314000000001,4,false,1319.0,", "root.sg1.d3,1314000000002,2,false,1318.0,", "root.sg1.d4,5,1,false,5556.0," };
    resultSetEqualTest("SELECT max_time(s1), count(s1), last_value(s2), count(s1)+last_value(s3) FROM root.sg1.** where s3+1=1316 or s2=false having avg(s1)+sum(s3)>5 align by device;", expectedHeader, retArray);
    retArray = new String[] { "root.sg2.d2,1314000000001,4,false,1319.0,", "root.sg2.d3,1314000000002,2,false,1318.0,", "root.sg2.d4,5,1,false,5556.0," };
    resultSetEqualTest("SELECT max_time(s1), count(s1), last_value(s2), count(s1)+last_value(s3) FROM root.sg2.** where s3+1=1316 or s2=false having avg(s1)+sum(s3)>5 align by device;", expectedHeader, retArray);
    expectedHeader = new String[] { "Device,max_time(s1),last_value(s1),count(s2),first_value(s3)" };
    retArray = new String[] { "root.sg1.d1,1314000000000,13.14,3,2,", "root.sg1.d2,1314000000001,13.15,4,11,", "root.sg1.d3,1314000000002,13.16,3,44,", "root.sg1.d4,1314000000003,13.14,4,1111," };
    resultSetEqualTest("SELECT max_time(s1), last_value(s1), count(s2), first_value(s3) FROM root.sg1.** where s3>1 align by device;", expectedHeader, retArray);
    retArray = new String[] { "root.sg2.d1,1314000000000,13.14,3,2,", "root.sg2.d2,1314000000001,13.15,4,11,", "root.sg2.d3,1314000000002,13.16,3,44,", "root.sg2.d4,1314000000003,13.14,4,1111," };
    resultSetEqualTest("SELECT max_time(s1), last_value(s1), count(s2), first_value(s3) FROM root.sg2.** where s3>1 align by device;", expectedHeader, retArray);
}

