@Test
public void orderByTest() {
    String[] expectedHeader = new String[] { "Time,Device,sum(s3)" };
    String[] retArray = new String[] { "4,root.sg1.d1,5.0,", "4,root.sg1.d2,5.0,", "4,root.sg1.d3,44.0,", "4,root.sg1.d4,5555.0,", "2,root.sg1.d1,2.0," };
    resultSetEqualTest("select sum(s3) from root.sg1.** where s1>1 GROUP BY([0, 10), 2ms) order by time desc offset 8 limit 5 align by device;", expectedHeader, retArray);
    expectedHeader = new String[] { "Time,Device,sum(s3)" };
    retArray = new String[] { "4,root.sg2.d1,5.0,", "4,root.sg2.d2,5.0,", "4,root.sg2.d3,44.0,", "4,root.sg2.d4,5555.0,", "2,root.sg2.d1,2.0," };
    resultSetEqualTest("select sum(s3) from root.sg2.** where s1>1 GROUP BY([0, 10), 2ms) order by time desc offset 8 limit 5 align by device;", expectedHeader, retArray);
    expectedHeader = new String[] { "Time,Device,sum(s3)" };
    retArray = new String[] { "0,root.sg1.d1,1.0,", "2,root.sg1.d1,2.0,", "4,root.sg1.d1,5.0,", "0,root.sg1.d2,11.0,", "2,root.sg1.d2,22.0," };
    resultSetEqualTest("select sum(s3) from root.sg1.** where s1>1 GROUP BY([0, 10), 2ms) order by count(s2) desc limit 5 align by device;", expectedHeader, retArray);
    expectedHeader = new String[] { "Time,Device,sum(s3)" };
    retArray = new String[] { "0,root.sg2.d1,1.0,", "2,root.sg2.d1,2.0,", "4,root.sg2.d1,5.0,", "0,root.sg2.d2,11.0,", "2,root.sg2.d2,22.0," };
    resultSetEqualTest("select sum(s3) from root.sg2.** where s1>1 GROUP BY([0, 10), 2ms) order by count(s2) desc limit 5 align by device;", expectedHeader, retArray);
    // order by non-existent measurement
    assertTestFail("select sum(s3) from root.sg1.** where s1>1 order by count(s_null) desc limit 5 align by device;", "count(s_null) in order by clause doesn't exist.");
    assertTestFail("select sum(s3) from root.sg2.** where s1>1 order by count(s_null) desc limit 5 align by device;", "count(s_null) in order by clause doesn't exist.");
}

