    retArray = new String[] { "root.sg1.d1,1314000000000,1314,13.14,true,3,", "root.sg1.d2,1314000000001,1315,13.15,false,4,", "root.sg1.d3,1314000000002,1316,13.16,false,3,", "root.sg1.d4,1314000000003,1314,13.14,true,4," };
    resultSetEqualTest("SELECT max_time(s1), last_value(*), count(s2) FROM root.sg1.** where s3>1 align by device;", expectedHeader, retArray);
    retArray = new String[] { "root.sg2.d1,1314000000000,1314,13.14,true,3,", "root.sg2.d2,1314000000001,1315,13.15,false,4,", "root.sg2.d3,1314000000002,1316,13.16,false,3,", "root.sg2.d4,1314000000003,1314,13.14,true,4," };
