    // sliding window
    expectedHeader = new String[] { "Time,Device,last_value(s1),last_value(s2)" };
    retArray = new String[] { "1,root.sg1.d1,2.2,false,", "1,root.sg1.d2,22.2,false,", "3,root.sg1.d2,50.0,false,", "5,root.sg1.d2,50.0,false,", "7,root.sg1.d3,8.8,false,", "3,root.sg1.d4,5555.5,false,", "5,root.sg1.d4,5555.5,false," };
