    retArray = new String[] { "1,root.sg2.d1,2.2,false,", "1,root.sg2.d2,22.2,false,", "3,root.sg2.d2,50.0,false,", "5,root.sg2.d2,50.0,false,", "7,root.sg2.d3,8.8,false,", "3,root.sg2.d4,5555.5,false,", "5,root.sg2.d4,5555.5,false," };
    resultSetEqualTest("SELECT last_value(*) FROM root.sg2.** where s3+1=1316 or s2=false group by ([1,10),3ms,2ms) having avg(s1)>0 soffset 1 slimit 2 align by device;", expectedHeader, retArray);
    // having
    expectedHeader = new String[] { "Device,last_value(s3),last_value(s1),last_value(s2),first_value(s3),first_value(s1),first_value(s2)" };
    retArray = new String[] { "root.sg1.d2,1315,13.15,false,11,11.1,false," };
    resultSetEqualTest("SELECT last_value(*), first_value(*) FROM root.sg1.** where s2=false having count(s3+s1) > 2 align by device;", expectedHeader, retArray);
    retArray = new String[] { "root.sg2.d2,1315,13.15,false,11,11.1,false," };
    resultSetEqualTest("SELECT last_value(*), first_value(*) FROM root.sg2.** where s2=false having count(s3+s1) > 2 align by device;", expectedHeader, retArray);
    // not supported expression: agg1(*)+agg2(*), agg(*)/2
    expectedHeader = new String[] { "Device,count(s3) + 1,count(s1) + 1,count(s2) + 1" };
    retArray = new String[] { "root.sg1.d2,5.0,5.0,5.0," };
    resultSetEqualTest("SELECT count(*)+1 FROM root.sg1.** where s2=false having count(s3+s1) > 2 align by device;", expectedHeader, retArray);
    retArray = new String[] { "root.sg2.d2,5.0,5.0,5.0," };
    resultSetEqualTest("SELECT count(*)+1 FROM root.sg2.** where s2=false having count(s3+s1) > 2 align by device;", expectedHeader, retArray);
}

