                if (cnt % numOfPointsInDevice == 0) {
                    index++;
                    cnt = 0;
                }
            }
            assertEquals(10, index);
        }
    } catch (Exception e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
}

