        authorizerReq = new TAuthorizerReq(AuthorType.GRANT_ROLE.ordinal(), "", "temprole0", "", "", Collections.singleton(PrivilegeType.MANAGE_DATABASE.ordinal()), false, AuthUtils.serializePartialPathList(new ArrayList<>()));
        status = client.operatePermission(authorizerReq);
        assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), status.getCode());
        // in confignode: tempuser0: MANAGE_USER
        // check user privileges
        checkUserPrivilegesReq = new TCheckUserPrivilegesReq("tempuser0", AuthUtils.serializePartialPathList(new ArrayList<>()), PrivilegeType.MANAGE_DATABASE.ordinal());
        status = client.checkUserPrivileges(checkUserPrivilegesReq).getStatus();
        assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), status.getCode());
        // revoke role from user
        authorizerReq = new TAuthorizerReq(AuthorType.REVOKE_USER_ROLE.ordinal(), "tempuser0", "temprole0", "", "", new HashSet<>(), false, AuthUtils.serializePartialPathList(new ArrayList<>()));
