        status = authorizerResp.getStatus();
        assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), status.getCode());
        assertEquals(new ArrayList<>(), authorizerResp.getMemberInfo());
    } catch (Exception e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
