    grantUserSeriesPrivilege("test", PrivilegeType.WRITE_SCHEMA, "root.sg1.d1.**");
    executeNonQuery("create timeseries using device template on root.sg1.d1", "test", "test123");
    // insert
    assertNonQueryTestFail("insert into root.sg1.d1(time, s1) values(1,1)", "803: No permissions for this operation, please add privilege WRITE_DATA on [root.sg1.d1.s1]", "test", "test123");
