    // Wrong input type
    assertTestFail("select SUBSTRING(s4,1,1) from root.**", TSStatusCode.SEMANTIC_ERROR.getStatusCode() + ": Unsupported data type FLOAT for function SUBSTRING.");
    // Wrong input type
    assertTestFail("select SUBSTRING(s5,1,1) from root.**", TSStatusCode.SEMANTIC_ERROR.getStatusCode() + ": Unsupported data type DOUBLE for function SUBSTRING.");
    // Wrong input type
    assertTestFail("select SUBSTRING(s6,1,1) from root.**", TSStatusCode.SEMANTIC_ERROR.getStatusCode() + ": Unsupported data type BOOLEAN for function SUBSTRING.");
    // Wrong input type
    assertTestFail("select SUBSTRING(s7,1,1) from root.**", TSStatusCode.SEMANTIC_ERROR.getStatusCode() + ": Unsupported data type DATE for function SUBSTRING.");
    // Wrong input type
    assertTestFail("select SUBSTRING(s8,1,1) from root.**", TSStatusCode.SEMANTIC_ERROR.getStatusCode() + ": Unsupported data type TIMESTAMP for function SUBSTRING.");
    // Wrong input type
    assertTestFail("select SUBSTRING(s10,1,1) from root.**", TSStatusCode.SEMANTIC_ERROR.getStatusCode() + ": Unsupported data type BLOB for function SUBSTRING.");
    // Using substring with float start position
    assertTestFail("select SUBSTRING(s1,1.0,1) from root.**", TSStatusCode.SEMANTIC_ERROR.getStatusCode() + ": Argument exception,the scalar function [SUBSTRING] needs at least one argument,it must be a signed integer");
    // Using substring with float start and length
    assertTestFail("select SUBSTRING(s1,1.0,1.1) from root.**", TSStatusCode.SEMANTIC_ERROR.getStatusCode() + ": Argument exception,the scalar function [SUBSTRING] needs at least one argument,it must be a signed integer");
    // Negative characters length
    assertTestFail("select SUBSTRING(s1,1,-10) from root.**", TSStatusCode.EXECUTE_STATEMENT_ERROR.getStatusCode() + ": Argument exception,the scalar function [SUBSTRING] beginPosition and length must be greater than 0");
    // Negative characters begin
    assertTestFail("select SUBSTRING(s1,-1,10) from root.**", TSStatusCode.EXECUTE_STATEMENT_ERROR.getStatusCode() + ": Argument exception,the scalar function [SUBSTRING] beginPosition and length must be greater than 0");
    // Negative characters begin
    assertTestFail("select SUBSTRING(s1 from -1 for 10) from root.**", TSStatusCode.EXECUTE_STATEMENT_ERROR.getStatusCode() + ": Argument exception,the scalar function [SUBSTRING] beginPosition and length must be greater than 0");
    // Negative characters begin
    assertTestFail("select SUBSTRING(s1,'start'='1','to'='2') from root.**", TSStatusCode.SEMANTIC_ERROR.getStatusCode() + ": Syntax error,please check that the parameters of the function are correct");
}

@Test
public void testCQExecution1() {
    String insertTemplate = "INSERT INTO root.sg.d1(time, s1) VALUES (%d, %d), (%d, %d), (%d, %d), (%d, %d), (%d, %d), (%d, %d), (%d, %d), (%d, %d), (%d, %d), (%d, %d)";
    try (Connection connection = EnvFactory.getEnv().getConnection();
        Statement statement = connection.createStatement()) {
        long now = System.currentTimeMillis() * 1_000_000L;
        long firstExecutionTime = now + 10_000_000_000L;
        long startTime = firstExecutionTime - 3_000_000_000L;
        statement.execute("create timeseries root.sg.d1.s1 WITH DATATYPE=INT64");
        statement.execute("create timeseries root.sg.d1.s1_max WITH DATATYPE=INT64");
        // firstly write one row to init data region, just for accelerating the following insert
        // statement.
        statement.execute("INSERT INTO root.sg.d1(time, s1) VALUES (0,0)");
        statement.execute(String.format(insertTemplate, startTime, 1, startTime + 500_000_000L, 2, startTime + 1_000_000_000L, 3, startTime + 1_500_000_000L, 4, startTime + 2_000_000_000L, 5, startTime + 2_500_000_000L, 6, startTime + 3_000_000_000L, 7, startTime + 3_500_000_000L, 8, startTime + 4_000_000_000L, 9, startTime + 4_500_000_000L, 10));
        statement.execute("CREATE CONTINUOUS QUERY cq1\n" + "RESAMPLE EVERY 2s\n" + String.format("BOUNDARY %d\n", firstExecutionTime) + "BEGIN \n" + "  SELECT max_value(s1) \n" + "  INTO root.sg.d1(s1_max)\n" + "  FROM root.sg.d1\n" + "  GROUP BY(1s) \n" + "END");
        // if the insert cost too much time
        if (System.currentTimeMillis() > firstExecutionTime / 1_000_000L) {
            statement.execute("DROP CQ cq1");
            return;
        }
        long targetTime = firstExecutionTime / 1_000_000L + 10_000;
        while (System.currentTimeMillis() - targetTime < 0) {
            TimeUnit.SECONDS.sleep(1);
        }
        long[] expectedTime = { startTime + 1_000_000_000L, startTime + 2_000_000_000L, startTime + 3_000_000_000L, startTime + 4_000_000_000L };
        long[] expectedValue = { 4, 6, 8, 10 };
        try (ResultSet resultSet = statement.executeQuery("select s1_max from root.sg.d1")) {
            int cnt = 0;
            while (resultSet.next()) {
                assertEquals(expectedTime[cnt], resultSet.getLong(TIMESTAMP_STR));
                assertEquals(expectedValue[cnt], resultSet.getLong("root.sg.d1.s1_max"));
                cnt++;
            }
            assertEquals(expectedTime.length, cnt);
        } finally {
            statement.execute("DROP CQ cq1");
        }
    } catch (Exception e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
}

