@Test
public void testCreateWrongCQ() {
    try (Connection connection = EnvFactory.getEnv().getConnection();
        Statement statement = connection.createStatement()) {
        // 1. specify first parameter of group by time
        try {
            String sql = "CREATE CQ s1_count_cq \n" + "BEGIN \n" + "  SELECT count(s1)  \n" + "    INTO root.sg_count.d(count_s1)\n" + "    FROM root.sg.d\n" + "    GROUP BY([0, 10), 30m)\n" + "END";
            statement.execute(sql);
            fail();
        } catch (Exception e) {
            assertEquals(TSStatusCode.INTERNAL_SERVER_ERROR.getStatusCode() + ": CQ: Specifying time range in GROUP BY TIME clause is prohibited.", e.getMessage());
        }
        // 2. specify time filter in where clause
        try {
            String sql = "CREATE CQ s1_count_cq \n" + "BEGIN \n" + "  SELECT count(s1)  \n" + "    INTO root.sg_count.d(count_s1)\n" + "    FROM root.sg.d\n" + "    WHERE time >= 0 and time <= 10\n" + "    GROUP BY(30m)\n" + "END";
            statement.execute(sql);
            fail();
        } catch (Exception e) {
            assertEquals(TSStatusCode.INTERNAL_SERVER_ERROR.getStatusCode() + ": CQ: Specifying time filters in the query body is prohibited.", e.getMessage());
        }
        // 3. no every clause meanwhile no group by time
        try {
            String sql = "CREATE CQ s1_count_cq \n" + "BEGIN \n" + "  SELECT count(s1)  \n" + "    INTO root.sg_count.d(count_s1)\n" + "    FROM root.sg.d\n" + "END";
            statement.execute(sql);
            fail();
        } catch (Exception e) {
            assertEquals(TSStatusCode.SEMANTIC_ERROR.getStatusCode() + ": CQ: At least one of the parameters `every_interval` and `group_by_interval` needs to be specified.", e.getMessage());
        }
        // 4. no INTO clause
        try {
            String sql = "CREATE CQ s1_count_cq_2\n" + "BEGIN \n" + "  SELECT count(s1)  \n" + "    FROM root.sg.d\n" + "    GROUP BY(30m)\n" + "END";
            statement.execute(sql);
            fail();
        } catch (Exception e) {
            assertEquals(TSStatusCode.INTERNAL_SERVER_ERROR.getStatusCode() + ": CQ: The query body misses an INTO clause.", e.getMessage());
        }
        // 5. EVERY interval is less than continuous_query_min_every_interval_in_ms in
        // iotdb-confignode.properties
        try {
            String sql = "CREATE CQ s1_count_cq_2\n" + "RESAMPLE EVERY 50ms\n" + "BEGIN \n" + "  SELECT count(s1)  \n" + "    INTO root.sg_count.d(count_s1)\n" + "    FROM root.sg.d\n" + "    GROUP BY(30m)\n" + "END";
            statement.execute(sql);
            fail();
        } catch (Exception e) {
            assertEquals(TSStatusCode.INTERNAL_SERVER_ERROR.getStatusCode() + ": CQ: Every interval [50] should not be lower than the `continuous_query_minimum_every_interval` [1000] configured.", e.getMessage());
        }
        // 6. start_time_offset < 0
        try {
            String sql = "CREATE CQ s1_count_cq_2\n" + "RESAMPLE RANGE -1m\n" + "BEGIN \n" + "  SELECT count(s1)  \n" + "    INTO root.sg_count.d(count_s1)\n" + "    FROM root.sg.d\n" + "    GROUP BY(30m)\n" + "END";
            statement.execute(sql);
            fail();
        } catch (Exception e) {
            assertEquals(TSStatusCode.SQL_PARSE_ERROR.getStatusCode() + ": Error occurred while parsing SQL to physical plan: line 2:15 extraneous input '-' expecting DURATION_LITERAL", e.getMessage());
        }
        // 7. start_time_offset == 0
        try {
            String sql = "CREATE CQ s1_count_cq_2\n" + "RESAMPLE RANGE 0m\n" + "BEGIN \n" + "  SELECT count(s1)\n" + "    INTO root.sg_count.d(count_s1)\n" + "    FROM root.sg.d\n" + "    GROUP BY(30m)\n" + "END";
            statement.execute(sql);
            fail();
        } catch (Exception e) {
            assertEquals(TSStatusCode.INTERNAL_SERVER_ERROR.getStatusCode() + ": CQ: The start time offset should be greater than 0.", e.getMessage());
        }
        // 8. end_time_offset < 0
        try {
            String sql = "CREATE CQ s1_count_cq_2\n" + "RESAMPLE RANGE 30m, -1m\n" + "BEGIN \n" + "  SELECT count(s1)  \n" + "    INTO root.sg_count.d(count_s1)\n" + "    FROM root.sg.d\n" + "    GROUP BY(30m)\n" + "END";
            statement.execute(sql);
            fail();
        } catch (Exception e) {
            assertEquals(TSStatusCode.SQL_PARSE_ERROR.getStatusCode() + ": Error occurred while parsing SQL to physical plan: line 2:20 extraneous input '-' expecting DURATION_LITERAL", e.getMessage());
        }
        // 9. end_time_offset == start_time_offset
        try {
            String sql = "CREATE CQ s1_count_cq_2\n" + "RESAMPLE RANGE 30m, 30m\n" + "BEGIN \n" + "  SELECT count(s1)  \n" + "    INTO root.sg_count.d(count_s1)\n" + "    FROM root.sg.d\n" + "    GROUP BY(30m)\n" + "END";
            statement.execute(sql);
            fail();
        } catch (Exception e) {
            assertEquals(TSStatusCode.INTERNAL_SERVER_ERROR.getStatusCode() + ": CQ: The start time offset should be greater than end time offset.", e.getMessage());
        }
        // 10. end_time_offset > start_time_offset
        try {
            String sql = "CREATE CQ s1_count_cq_2\n" + "RESAMPLE RANGE 30m, 31m\n" + "BEGIN \n" + "  SELECT count(s1)  \n" + "    INTO root.sg_count.d(count_s1)\n" + "    FROM root.sg.d\n" + "    GROUP BY(30m)\n" + "END";
            statement.execute(sql);
            fail();
        } catch (Exception e) {
            assertEquals(TSStatusCode.INTERNAL_SERVER_ERROR.getStatusCode() + ": CQ: The start time offset should be greater than end time offset.", e.getMessage());
        }
        // 11. group_by_interval > start_time_offset
        try {
            String sql = "CREATE CQ s1_count_cq_2\n" + "RESAMPLE RANGE 30m\n" + "BEGIN \n" + "  SELECT count(s1) \n" + "    INTO root.sg_count.d(count_s1)\n" + "    FROM root.sg.d\n" + "    GROUP BY(1h)\n" + "END";
            statement.execute(sql);
            fail();
        } catch (Exception e) {
            assertEquals(TSStatusCode.INTERNAL_SERVER_ERROR.getStatusCode() + ": CQ: The start time offset should be greater than or equal to every interval.", e.getMessage());
        }
        // 12. TIMEOUT POLICY is not BLOCKED or DISCARD
        try {
            String sql = "CREATE CQ s1_count_cq_2\n" + "RESAMPLE RANGE 30m\n" + "TIMEOUT POLICY UNKNOWN\n" + "BEGIN \n" + "  SELECT count(s1)  \n" + "    INTO root.sg_count.d(count_s1)\n" + "    FROM root.sg.d\n" + "    GROUP BY(1h)\n" + "END";
            statement.execute(sql);
            fail();
        } catch (Exception e) {
            assertEquals(TSStatusCode.SQL_PARSE_ERROR.getStatusCode() + ": Error occurred while parsing SQL to physical plan: line 3:15 mismatched input 'UNKNOWN' expecting {BLOCKED, DISCARD}", e.getMessage());
        }
        // 13. create duplicated cq
        try {
            String sql = "CREATE CQ s1_count_cq \n" + "BEGIN \n" + "  SELECT count(s1)  \n" + "    INTO root.sg_count.d(count_s1)\n" + "    FROM root.sg.d\n" + "    GROUP BY(30m)\n" + "END";
            statement.execute(sql);
            statement.execute(sql);
            fail();
        } catch (Exception e) {
            assertEquals(TSStatusCode.CQ_ALREADY_EXIST.getStatusCode() + ": CQ s1_count_cq has already been created.", e.getMessage());
        } finally {
            statement.execute("DROP CQ s1_count_cq;");
        }
    } catch (Exception e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
}

