@Test
public void testDropCQ() {
    try (Connection connection = EnvFactory.getEnv().getConnection();
        Statement statement = connection.createStatement()) {
        String[] cqIds = { "drop_cq_1", "drop_cq_2", "drop_cq_3", "drop_cq_4" };
        String[] cqSQLs = { "CREATE CQ drop_cq_1 \n" + "RESAMPLE \n" + "  EVERY 30m\n" + "  BOUNDARY 0\n" + "  RANGE 30m, 10m\n" + "TIMEOUT POLICY BLOCKED\n" + "BEGIN \n" + "  SELECT count(s1)  \n" + "    INTO root.sg_count.d(count_s1)\n" + "    FROM root.sg.d\n" + "    GROUP BY(30m)\n" + "END", "CREATE CQ drop_cq_2\n" + "BEGIN \n" + "  SELECT count(s1)  \n" + "    INTO root.sg_count.d(count_s1)\n" + "    FROM root.sg.d\n" + "    GROUP BY(30m)\n" + "END", "CREATE CQ drop_cq_3\n" + "RESAMPLE RANGE 30m, 0m\n" + "TIMEOUT POLICY DISCARD\n" + "BEGIN \n" + "  SELECT count(s1)  \n" + "    INTO root.sg_count.d(count_s1)\n" + "    FROM root.sg.d\n" + "    GROUP BY(10m)\n" + "END", "CREATE CQ drop_cq_4\n" + "RESAMPLE EVERY 30m \n" + "TIMEOUT POLICY DISCARD\n" + "BEGIN \n" + "  SELECT count(s1)  \n" + "    INTO root.sg_count.d(count_s1)\n" + "    FROM root.sg.d\n" + "    GROUP BY(10m)\n" + "END" };
        for (String sql : cqSQLs) {
            statement.execute(sql);
        }
        try (ResultSet resultSet = statement.executeQuery("show CQS")) {
            int cnt = 0;
            while (resultSet.next()) {
                // No need to add time column for aggregation query
                assertEquals(cqIds[cnt], resultSet.getString(1));
                assertEquals(cqSQLs[cnt], resultSet.getString(2));
                assertEquals("ACTIVE", resultSet.getString(3));
                cnt++;
            }
            assertEquals(cqIds.length, cnt);
        }
        statement.execute("DROP CQ drop_cq_2");
        statement.execute("DROP CQ drop_cq_3");
        int[] resultIndex = { 0, 3 };
        try (ResultSet resultSet = statement.executeQuery("show CQS")) {
            int cnt = 0;
            while (resultSet.next()) {
                // No need to add time column for aggregation query
                assertEquals(cqIds[resultIndex[cnt]], resultSet.getString(1));
                assertEquals(cqSQLs[resultIndex[cnt]], resultSet.getString(2));
                assertEquals("ACTIVE", resultSet.getString(3));
                cnt++;
            }
            assertEquals(resultIndex.length, cnt);
        }
        statement.execute("DROP CQ drop_cq_1");
        statement.execute("DROP CQ drop_cq_4");
        try (ResultSet resultSet = statement.executeQuery("show CQS")) {
            assertFalse(resultSet.next());
        }
    } catch (Exception e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
}

