    for (int window : windows) {
        String sqlStr = String.format("select time_window_counter(sin(d1.s1), '%s'='%s', '%s'='%s'), time_window_counter(sin(d1.s1), cos(d2.s2) / sin(d1.s1), d1.s2, '%s'='%s', '%s'='%s'), size_window_counter(cos(d2.s2), '%s'='%s', '%s'='%s'), size_window_counter(cos(d2.s2), cos(d2.s2), '%s'='%s', '%s'='%s') from root.vehicle", UDFTestConstant.ACCESS_STRATEGY_KEY, UDFTestConstant.ACCESS_STRATEGY_SLIDING_TIME, UDFTestConstant.TIME_INTERVAL_KEY, window, UDFTestConstant.ACCESS_STRATEGY_KEY, UDFTestConstant.ACCESS_STRATEGY_SLIDING_TIME, UDFTestConstant.TIME_INTERVAL_KEY, window, UDFTestConstant.ACCESS_STRATEGY_KEY, UDFTestConstant.ACCESS_STRATEGY_SLIDING_SIZE, UDFTestConstant.WINDOW_SIZE_KEY, window, UDFTestConstant.ACCESS_STRATEGY_KEY, UDFTestConstant.ACCESS_STRATEGY_SLIDING_SIZE, UDFTestConstant.WINDOW_SIZE_KEY, window);
