@Test
public void queryWithUnsetAuthorization() {
    CloseableHttpResponse response = null;
    try {
        CloseableHttpClient httpClient = HttpClientBuilder.create().build();
        HttpPost httpPost = new HttpPost("http://127.0.0.1:" + port + "/rest/v1/query");
        httpPost.addHeader("Content-type", "application/json; charset=utf-8");
        httpPost.setHeader("Accept", "application/json");
        String sql = "{\"sql\":\"select *,s4+1,s4+1 from root.sg25\"}";
        httpPost.setEntity(new StringEntity(sql, Charset.defaultCharset()));
        for (int i = 0; i < 30; i++) {
            try {
                response = httpClient.execute(httpPost);
                break;
            } catch (Exception e) {
                if (i == 29) {
                    throw e;
                }
                try {
                    Thread.sleep(1000);
                } catch (InterruptedException ex) {
                    throw new RuntimeException(ex);
                }
            }
        }
        Assert.assertEquals(401, response.getStatusLine().getStatusCode());
        String message = EntityUtils.toString(response.getEntity(), "utf-8");
        JsonObject result = JsonParser.parseString(message).getAsJsonObject();
        assertEquals(800, Integer.parseInt(result.get("code").toString()));
    } catch (IOException e) {
        e.printStackTrace();
        fail(e.getMessage());
    } finally {
        try {
            if (response != null) {
                response.close();
            }
        } catch (IOException e) {
            e.printStackTrace();
            fail(e.getMessage());
        }
    }
}

