@Test
public void testExpression() {
    try (Connection connection = EnvFactory.getEnv().getConnection();
        Statement statement = connection.createStatement()) {
        statement.execute("CREATE TIMESERIES root.sg1.d1.`1` INT32");
        statement.execute("CREATE TIMESERIES root.sg1.d1.`a.b` INT32");
        statement.execute("CREATE TIMESERIES root.sg1.d1.`a.``b` INT32");
        statement.execute("CREATE TIMESERIES root.sg1.d1.text TEXT");
        int pointCnt = 3;
        for (int i = 0; i < pointCnt; i++) {
            statement.execute(String.format("insert into root.sg1.d1(time,%s,%s,%s) values(%d,%d,%d,%d)", "`1`", "`a.b`", "`a.``b`", i, i, i, i));
        }
        int cnt = 0;
        try (ResultSet resultSet = statement.executeQuery("SELECT `1` + 1 FROM root.sg1.d1")) {
            while (resultSet.next()) {
                cnt++;
            }
            Assert.assertEquals(pointCnt, cnt);
        }
        cnt = 0;
        try (ResultSet resultSet = statement.executeQuery("SELECT (`1`*`1`)+1-`a.b` FROM root.sg1.d1 where `1` > 1")) {
            while (resultSet.next()) {
                cnt++;
            }
            Assert.assertEquals(1, cnt);
        }
        cnt = 0;
        try (ResultSet resultSet = statement.executeQuery("SELECT (`1`*`1`)+1-`a.b` FROM root.sg1.d1")) {
            while (resultSet.next()) {
                cnt++;
            }
            Assert.assertEquals(pointCnt, cnt);
        }
        cnt = 0;
        try (ResultSet resultSet = statement.executeQuery("SELECT (`1`*`1`)+1-`a.b` FROM root.sg1.d1 where `1`>0")) {
            while (resultSet.next()) {
                cnt++;
            }
            Assert.assertEquals(2, cnt);
        }
        cnt = 0;
        try (ResultSet resultSet = statement.executeQuery("SELECT avg(`1`)+1 FROM root.sg1.d1")) {
            while (resultSet.next()) {
                cnt++;
            }
            Assert.assertEquals(1, cnt);
        }
        cnt = 0;
        try (ResultSet resultSet = statement.executeQuery("SELECT count(`1`)+1 FROM root.sg1.d1 where `1`>1")) {
            while (resultSet.next()) {
                Assert.assertEquals(2.0, resultSet.getDouble(1), 1e-7);
                cnt++;
            }
            Assert.assertEquals(1, cnt);
        }
        cnt = 0;
        try (ResultSet resultSet = statement.executeQuery("SELECT sin(`1`) + 1 FROM root.sg1.d1")) {
            while (resultSet.next()) {
                cnt++;
            }
            Assert.assertEquals(pointCnt, cnt);
        }
        cnt = 0;
        try (ResultSet resultSet = statement.executeQuery("SELECT sin(`1`) + 1 FROM root.sg1.d1 where `1`>1")) {
            while (resultSet.next()) {
                cnt++;
            }
            Assert.assertEquals(1, cnt);
        }
        cnt = 0;
        try (ResultSet resultSet = statement.executeQuery("SELECT text FROM root.sg1.d1 where text = '\'")) {
            while (resultSet.next()) {
                cnt++;
            }
            Assert.assertEquals(0, cnt);
        }
        cnt = 0;
        try (ResultSet resultSet = statement.executeQuery("SELECT text FROM root.sg1.d1 where text = '\' or text = 'asdf'")) {
            while (resultSet.next()) {
                cnt++;
            }
            Assert.assertEquals(0, cnt);
        }
        cnt = 0;
        try (ResultSet resultSet = statement.executeQuery("SELECT text FROM root.sg1.d1 where text = '\\'")) {
            while (resultSet.next()) {
                cnt++;
            }
            Assert.assertEquals(0, cnt);
        }
        cnt = 0;
        try (ResultSet resultSet = statement.executeQuery("SELECT text FROM root.sg1.d1 where text = '\\' and text = 'asdf'")) {
            while (resultSet.next()) {
                cnt++;
            }
            Assert.assertEquals(0, cnt);
        }
    } catch (SQLException e) {
        e.printStackTrace();
        fail();
    }
}

