@Test
public void testKind1UsedInOtherOperation() {
    String sql;
    String[] expectedHeader;
    String[] retArray;
    // use in scalar operation
    // multiply
    sql = "select 2 * case when s1=0 then 99 when s1=22.0 then 999 else 9999 end from root.sg.d1";
    expectedHeader = new String[] { TIMESTAMP_STR, "2 * CASE WHEN root.sg.d1.s1 = 0 THEN 99 WHEN root.sg.d1.s1 = 22.0 THEN 999 ELSE 9999 END" };
    retArray = new String[] { "0,198.0,", "1000000,19998.0,", "20000000,1998.0,", "210000000,19998.0," };
    resultSetEqualTest(sql, expectedHeader, retArray);
    // add
    sql = "select " + "case when s1=0 then 99 when s1=22.0 then 999 else 9999 end " + "+" + "case when s1=11 then 99 else 9999 end " + "from root.sg.d1, root.sg.d2";
    expectedHeader = new String[] { TIMESTAMP_STR, "CASE WHEN root.sg.d1.s1 = 0 THEN 99 WHEN root.sg.d1.s1 = 22.0 THEN 999 ELSE 9999 END + CASE WHEN root.sg.d1.s1 = 11 THEN 99 ELSE 9999 END" };
    retArray = new String[] { "0,10098.0,", "1000000,10098.0,", "20000000,10998.0,", "210000000,19998.0," };
    resultSetEqualTest(sql, expectedHeader, retArray);
    // function
    sql = "select diff(case when s1=0 then 99 when s1>22 then 999 else 9999 end) as `result` from root.sg.d1";
    expectedHeader = new String[] { TIMESTAMP_STR, "result" };
    retArray = new String[] { "0,null,", "1000000,9900.0,", "20000000,0.0,", "210000000,-9000.0," };
    resultSetEqualTest(sql, expectedHeader, retArray);
    // use in aggregation operation
    // avg
    sql = "select avg(case when s1=0 then 99 when s1>22 then 999 else 9999 end) as `result` from root.sg.d1";
    expectedHeader = new String[] { "result" };
    retArray = new String[] { "5274.0," };
    resultSetEqualTest(sql, expectedHeader, retArray);
    // max_value
    sql = "select max_value(case when s1=0 then 99 when s1>22 then 999 else 9999 end) as `result` from root.sg.d1";
    expectedHeader = new String[] { "result" };
    retArray = new String[] { "9999.0," };
    resultSetEqualTest(sql, expectedHeader, retArray);
    // avg × max_value
    resultSetEqualTest("select avg(case when s1=0 then 99 when s1>22 then 999 else 9999 end) * max_value(case when s1=0 then 99 when s1>22 then 999 else 9999 end) from root.sg.d1", new String[] { "avg(CASE WHEN root.sg.d1.s1 = 0 THEN 99 WHEN root.sg.d1.s1 > 22 THEN 999 ELSE 9999 END) * max_value(CASE WHEN root.sg.d1.s1 = 0 THEN 99 WHEN root.sg.d1.s1 > 22 THEN 999 ELSE 9999 END)" }, new String[] { "5.2734726E7," });
    // UDF is not allowed
    sql = "select change_points(case when s1=0 then 99 end) from root.sg.d1";
    String msg = "301: CASE expression cannot be used with non-mappable UDF";
    assertTestFail(sql, msg);
    sql = "select change_points(s1) + case when s1=0 then 99 end from root.sg.d1";
    msg = "301: CASE expression cannot be used with non-mappable UDF";
    assertTestFail(sql, msg);
}

