    String[] expectedHeader = new String[] { TIMESTAMP_STR, "root.test.sg1.s1", "root.test.sg1.s3", "root.test.sg1.s4" };
    String[] retArray = new String[] { "1,1,true,false,", "2,2,true,null,", "3,3,null,false," };
