    // series in where not exist
    retArray = new String[] {};
    resultSetEqualTest("select s1, s3, s4 from root.** where notExist>0", expectedHeader, retArray);
    resultSetEqualTest("select s1, s3, s4 from root.** where notExist=0", expectedHeader, retArray);
    resultSetEqualTest("select s1, s3, s4 from root.** where notExist!=0", expectedHeader, retArray);
    resultSetEqualTest("select s1, s3, s4 from root.** where diff(notExist)>0", expectedHeader, retArray);
    retArray = new String[] { "1,1,true,false,", "2,2,true,null,", "3,3,null,false," };
    resultSetEqualTest("select s1, s3, s4 from root.** where diff(notExist) is null", expectedHeader, retArray);
    // series in having not exist
    expectedHeader = new String[] { TIMESTAMP_STR, "count(root.test.sg1.s1)", "count(root.test.sg1.s2)" };
    retArray = new String[] {};
    resultSetEqualTest("select count(s1), count(s2) from root.** group by ([1,4),1ms) having count(notExist)>0", expectedHeader, retArray);
}

