    String[] ret2 = { "root.turbine.d1.s1,temperature,root.turbine,FLOAT,RLE,SNAPPY,{\"tag1\":\"v1\",\"tag2\":\"" + "newV2\",\"tag3\":\"v3\"},{\"attr2\":\"v2\",\"attr1\":\"v1\"}" };
    String[] ret3 = { "root.turbine.d1.s1,temperature,root.turbine,FLOAT,RLE,SNAPPY,{\"tag1\":\"newV1\",\"tag2\":\"" + "newV2\",\"tag3\":\"newV3\"},{\"attr2\":\"v2\",\"attr1\":\"newA1\",\"attr3\":\"v3\"}" };
    String sql = "create timeseries root.turbine.d1.s1(temperature) with datatype=FLOAT, encoding=RLE, compression=SNAPPY " + "tags('tag1'='v1', 'tag2'='v2') attributes('attr1'='v1', 'attr2'='v2')";
    try (Connection connection = EnvFactory.getEnv().getConnection();
        Statement statement = connection.createStatement()) {
        statement.execute(sql);
        ResultSet resultSet = statement.executeQuery("show timeseries");
        int count = 0;
        try {
            while (resultSet.next()) {
                String ans = resultSet.getString(ColumnHeaderConstant.TIMESERIES) + "," + resultSet.getString(ColumnHeaderConstant.ALIAS) + "," + resultSet.getString(ColumnHeaderConstant.DATABASE) + "," + resultSet.getString(ColumnHeaderConstant.DATATYPE) + "," + resultSet.getString(ColumnHeaderConstant.ENCODING) + "," + resultSet.getString(ColumnHeaderConstant.COMPRESSION) + "," + resultSet.getString(ColumnHeaderConstant.TAGS) + "," + resultSet.getString(ColumnHeaderConstant.ATTRIBUTES);
                assertEquals(ret[count], ans);
                count++;
            }
        } finally {
            resultSet.close();
        }
        assertEquals(ret.length, count);
        statement.execute("ALTER timeseries root.turbine.d1.s1 UPSERT TAGS('tag3'='v3', 'tag2'='newV2')");
        resultSet = statement.executeQuery("show timeseries where TAGS(tag3)='v3'");
        count = 0;
        try {
            while (resultSet.next()) {
                String ans = resultSet.getString(ColumnHeaderConstant.TIMESERIES) + "," + resultSet.getString(ColumnHeaderConstant.ALIAS) + "," + resultSet.getString(ColumnHeaderConstant.DATABASE) + "," + resultSet.getString(ColumnHeaderConstant.DATATYPE) + "," + resultSet.getString(ColumnHeaderConstant.ENCODING) + "," + resultSet.getString(ColumnHeaderConstant.COMPRESSION) + "," + resultSet.getString(ColumnHeaderConstant.TAGS) + "," + resultSet.getString(ColumnHeaderConstant.ATTRIBUTES);
                assertEquals(ret2[count], ans);
                count++;
            }
        } finally {
            resultSet.close();
        }
        assertEquals(ret2.length, count);
        statement.execute("ALTER timeseries root.turbine.d1.s1 UPSERT TAGS('tag1'='newV1', 'tag3'='newV3') " + "ATTRIBUTES('attr1'='newA1', 'attr3'='v3')");
