    List<String> ret5 = Collections.singletonList("root.turbine.d1.s1,temperature,root.turbine,FLOAT,RLE,SNAPPY," + "{\"tag4\":\"v4\",\"tag1\":\"v1\",\"tag5\":\"v5\"},{\"att2\":\"a2\",\"att1\":\"a1\"}");
    rets.add(ret5);
    List<String> sqls = new java.util.ArrayList<>();
    String sql1 = "create timeseries root.turbine.d1.s1(temperature) with datatype=FLOAT, encoding=RLE, compression=SNAPPY " + "tags('oldTag1'='oldV1', 'tag2'='v2') " + "attributes('att1'='a1', 'att2'='a2')";
    sqls.add(sql1);
    String sql2 = "ALTER timeseries root.turbine.d1.s1 RENAME oldTag1 TO tag1";
    sqls.add(sql2);
    String sql3 = "ALTER timeseries root.turbine.d1.s1 SET tag1=v1";
    sqls.add(sql3);
    String sql4 = "ALTER timeseries root.turbine.d1.s1 ADD TAGS tag3=v3, tag4=v4, tag5=v5";
    sqls.add(sql4);
    String sql5 = "ALTER timeseries root.turbine.d1.s1 DROP tag2, tag3";
    sqls.add(sql5);
    try (Connection connection = EnvFactory.getEnv().getConnection();
        Statement statement = connection.createStatement()) {
        for (int i = 0; i < sqls.size(); i++) {
            statement.execute(sqls.get(i));
            ResultSet resultSet = statement.executeQuery("show timeseries");
            int count = 0;
            try {
                while (resultSet.next()) {
                    String ans = resultSet.getString(ColumnHeaderConstant.TIMESERIES) + "," + resultSet.getString(ColumnHeaderConstant.ALIAS) + "," + resultSet.getString(ColumnHeaderConstant.DATABASE) + "," + resultSet.getString(ColumnHeaderConstant.DATATYPE) + "," + resultSet.getString(ColumnHeaderConstant.ENCODING) + "," + resultSet.getString(ColumnHeaderConstant.COMPRESSION) + "," + resultSet.getString(ColumnHeaderConstant.TAGS) + "," + resultSet.getString(ColumnHeaderConstant.ATTRIBUTES);
                    assertTrue(rets.get(i).contains(ans));
                    count++;
                }
            } finally {
                resultSet.close();
            }
            assertEquals(rets.get(i).size(), count);
        }
    } catch (Exception e) {
        e.printStackTrace();
        fail();
    }
    clearSchema();
}

