        statement.execute("INSERT INTO root.ln.wf01.wt01(timestamp, temperature, status, hardware) " + "VALUES(now(), 35.5, false, 650)");
        try (ResultSet resultSet = statement.executeQuery("SELECT count_udaf(temperature), sum_udaf(temperature), avg_udaf(temperature) " + "FROM root.ln.wf01.wt01 " + "GROUP BY ([now() - 1h, now() + 1h), 2h)")) {
