@Test
public void unsatisfiedRuleQueryTest() {
    assertTestFail("SELECT count_udaf(s1) FROM root.** GROUP BY ([1,3),1ms), LEVEL=1 HAVING sum_udaf(d1.s1) > 1", TSStatusCode.SEMANTIC_ERROR.getStatusCode() + ": When Having used with GroupByLevel: the suffix paths can only be measurement or one-level wildcard");
    assertTestFail("SELECT count_udaf(d1.s1) FROM root.** GROUP BY ([1,3),1ms), LEVEL=1 HAVING sum_udaf(s1) > 1", TSStatusCode.SEMANTIC_ERROR.getStatusCode() + ": When Having used with GroupByLevel: the suffix paths can only be measurement or one-level wildcard");
    assertTestFail("SELECT count_udaf(d1.s1) FROM root.** GROUP BY ([1,3),1ms), LEVEL=1 HAVING sum_udaf(s1) + s1 > 1", TSStatusCode.SEMANTIC_ERROR.getStatusCode() + ": Raw data and aggregation result hybrid calculation is not supported");
    assertTestFail("SELECT count_udaf(d1.s1) FROM root.** GROUP BY ([1,3),1ms), LEVEL=1 HAVING s1 + 1 > 1", TSStatusCode.SEMANTIC_ERROR.getStatusCode() + ": Expression of HAVING clause must to be an Aggregation");
}

