@Test
public void singleUDAFTest() {
    String[] retArray = new String[] { "0,2001,2001,2001,2001", "0,7500,7500,7500,7500" };
    try (Connection connection = EnvFactory.getEnv().getConnection();
        Statement statement = connection.createStatement()) {
        int cnt;
        try (ResultSet resultSet = statement.executeQuery("SELECT count_udaf(s0),count_udaf(s1),count_udaf(s2),count_udaf(s3) " + "FROM root.vehicle.d0 WHERE time >= 6000 AND time <= 9000")) {
            cnt = 0;
            while (resultSet.next()) {
                String ans = resultSet.getString(TIMESTAMP_STR) + "," + resultSet.getString(countUDAF(d0s0)) + "," + resultSet.getString(countUDAF(d0s1)) + "," + resultSet.getString(countUDAF(d0s2)) + "," + resultSet.getString(countUDAF(d0s3));
                Assert.assertEquals(retArray[cnt], ans);
                cnt++;
            }
            Assert.assertEquals(1, cnt);
        }
        try (ResultSet resultSet = statement.executeQuery("SELECT count_udaf(s0),count_udaf(s1),count_udaf(s2),count_udaf(s3) " + "FROM root.vehicle.d0")) {
            while (resultSet.next()) {
                String ans = resultSet.getString(TIMESTAMP_STR) + "," + resultSet.getString(countUDAF(d0s0)) + "," + resultSet.getString(countUDAF(d0s1)) + "," + resultSet.getString(countUDAF(d0s2)) + "," + resultSet.getString(countUDAF(d0s3));
                Assert.assertEquals(retArray[cnt], ans);
                cnt++;
            }
            Assert.assertEquals(2, cnt);
        }
        // keep the correctness of `order by time desc`
        try (ResultSet resultSet = statement.executeQuery("SELECT count_udaf(s0),count_udaf(s1),count_udaf(s2),count_udaf(s3) " + "FROM root.vehicle.d0 WHERE time >= 6000 AND time <= 9000 order by time desc")) {
            cnt = 0;
            while (resultSet.next()) {
                String ans = resultSet.getString(TIMESTAMP_STR) + "," + resultSet.getString(countUDAF(d0s0)) + "," + resultSet.getString(countUDAF(d0s1)) + "," + resultSet.getString(countUDAF(d0s2)) + "," + resultSet.getString(countUDAF(d0s3));
                Assert.assertEquals(retArray[cnt], ans);
                cnt++;
            }
            Assert.assertEquals(1, cnt);
        }
        try (ResultSet resultSet = statement.executeQuery("SELECT count_udaf(s0),count_udaf(s1),count_udaf(s2),count_udaf(s3) " + "FROM root.vehicle.d0 order by time desc")) {
            while (resultSet.next()) {
                String ans = resultSet.getString(TIMESTAMP_STR) + "," + resultSet.getString(countUDAF(d0s0)) + "," + resultSet.getString(countUDAF(d0s1)) + "," + resultSet.getString(countUDAF(d0s2)) + "," + resultSet.getString(countUDAF(d0s3));
                Assert.assertEquals(retArray[cnt], ans);
                cnt++;
            }
            Assert.assertEquals(2, cnt);
        }
    } catch (Exception e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
}

