@Test
public void testConstantTimeSeriesGeneratingFunctions() {
    String[] expected = { "0, 0.0, 0.0, 1024, 3.141592653589793, 2.718281828459045, ", "2, 1.0, null, 1024, 3.141592653589793, 2.718281828459045, ", "4, 2.0, null, 1024, 3.141592653589793, 2.718281828459045, ", "6, null, 3.0, null, null, 2.718281828459045, ", "8, null, 4.0, null, null, 2.718281828459045, ", "10000000000, null, 5.0, null, null, 2.718281828459045, " };
    try (Connection connection = EnvFactory.getEnv().getConnection()) {
        try (Statement statement = connection.createStatement();
            ResultSet resultSet = statement.executeQuery("select s7, s8, const(s7, 'value'='1024', 'type'='INT64'), pi(s7, s7), e(s7, s8, s7, s8) from root.sg.d1")) {
            assertEquals(1 + 5, resultSet.getMetaData().getColumnCount());
            for (int i = 0; i < INSERTION_SQLS.length; ++i) {
                resultSet.next();
                StringBuilder actual = new StringBuilder();
                for (int j = 0; j < 1 + 5; ++j) {
                    actual.append(resultSet.getString(1 + j)).append(", ");
                }
                assertEquals(expected[i], actual.toString());
            }
            assertFalse(resultSet.next());
        }
        try (Statement statement = connection.createStatement();
            ResultSet resultSet = statement.executeQuery("select s7, s8, const(s7, 'value'='1024', 'type'='INT64'), pi(s7, s7), e(s7, s8, s7, s8) from root.sg.d1 align by device")) {
            assertEquals(2 + 5, resultSet.getMetaData().getColumnCount());
            for (int i = 0; i < INSERTION_SQLS.length; ++i) {
                resultSet.next();
                StringBuilder actual = new StringBuilder();
                actual.append(resultSet.getString(1)).append(", ");
                for (int j = 1; j < 1 + 5; ++j) {
                    actual.append(resultSet.getString(2 + j)).append(", ");
                }
                assertEquals(expected[i], actual.toString());
            }
            assertFalse(resultSet.next());
        }
        try (Statement statement = connection.createStatement();
            ResultSet ignored = statement.executeQuery("select const(s7, 'value'='1024') from root.sg.d1")) {
            fail();
        } catch (SQLException e) {
            assertTrue(e.getMessage().contains("attribute \"type\" is required but was not provided"));
        }
        try (Statement statement = connection.createStatement();
            ResultSet ignored = statement.executeQuery("select const(s8, 'type'='INT64') from root.sg.d1")) {
            fail();
        } catch (SQLException e) {
            assertTrue(e.getMessage().contains("attribute \"value\" is required but was not provided"));
        }
        try (Statement statement = connection.createStatement();
            ResultSet ignored = statement.executeQuery("select const(s8, 'value'='1024', 'type'='long') from root.sg.d1")) {
            fail();
        } catch (SQLException e) {
            assertTrue(e.getMessage().contains("the given value type is not supported"));
        }
        try (Statement statement = connection.createStatement();
            ResultSet ignored = statement.executeQuery("select const(s8, 'value'='1024e', 'type'='INT64') from root.sg.d1")) {
            fail();
        } catch (SQLException e) {
            assertTrue(e.getMessage().contains("java.lang.NumberFormatException"));
        }
    } catch (SQLException throwable) {
        fail(throwable.getMessage());
    }
}

