    if (!TestUtils.tryExecuteNonQueriesWithRetry(senderEnv, Arrays.asList("insert into root.db.d1 (time, at1) values (1000, 1), (1500, 2), (2000, 3), (2500, 4), (3000, 5)", "flush"))) {
        fail();
    }
    // Check data on receiver
    final Set<String> expectedResSet = new HashSet<>();
    expectedResSet.add("1000,1.0,");
    expectedResSet.add("2000,3.0,");
    expectedResSet.add("3000,5.0,");
    TestUtils.assertDataEventuallyOnEnv(receiverEnv, "select * from root.db.**", "Time,root.db.d1.at1,", expectedResSet);
    // Alter pipe (modify 'source.path' and 'processor.tumbling-time.interval-seconds')
    try (final Connection connection = senderEnv.getConnection();
        final Statement statement = connection.createStatement()) {
        statement.execute("alter pipe a2b modify source('source' = 'iotdb-source','source.path'='root.db.d2.**') modify processor ('processor.tumbling-time.interval-seconds'='2')");
    } catch (SQLException e) {
        fail(e.getMessage());
    }
    // Insert data on sender
    if (!TestUtils.tryExecuteNonQueriesWithRetry(senderEnv, Arrays.asList("insert into root.db.d2 (time, at1) values (11000, 1), (11500, 2), (12000, 3), (12500, 4), (13000, 5)", "flush"))) {
        fail();
    }
    // Insert data on sender
    if (!TestUtils.tryExecuteNonQueriesWithRetry(senderEnv, Arrays.asList("insert into root.db.d1 (time, at1) values (11000, 1), (11500, 2), (12000, 3), (12500, 4), (13000, 5)", "flush"))) {
        fail();
    }
    // Check data on receiver
    expectedResSet.clear();
    expectedResSet.add("11000,null,1.0,");
    expectedResSet.add("13000,null,5.0,");
    TestUtils.assertDataEventuallyOnEnv(receiverEnv, "select * from root.db.** where time > 10000", "Time,root.db.d1.at1,root.db.d2.at1,", expectedResSet);
}

@Test
public void testDoubleLivingAutoConflict() throws Exception {
    // Double living is two clusters each with a pipe connecting to the other.
    final DataNodeWrapper senderDataNode = senderEnv.getDataNodeWrapper(0);
    final DataNodeWrapper receiverDataNode = receiverEnv.getDataNodeWrapper(0);
    final String senderIp = senderDataNode.getIp();
    final int senderPort = senderDataNode.getPort();
    final String receiverIp = receiverDataNode.getIp();
    final int receiverPort = receiverDataNode.getPort();
    for (int i = 0; i < 100; ++i) {
        if (!TestUtils.tryExecuteNonQueryWithRetry(senderEnv, String.format("insert into root.db.d1(time, s1) values (%s, 1)", i))) {
            return;
        }
    }
