@Test
public void testPipeAfterDataRegionLeaderStop() throws Exception {
    final DataNodeWrapper receiverDataNode = receiverEnv.getDataNodeWrapper(0);
    final String receiverIp = receiverDataNode.getIp();
    final int receiverPort = receiverDataNode.getPort();
    try (final SyncConfigNodeIServiceClient client = (SyncConfigNodeIServiceClient) senderEnv.getLeaderConfigNodeConnection()) {
        final Map<String, String> extractorAttributes = new HashMap<>();
        final Map<String, String> processorAttributes = new HashMap<>();
        final Map<String, String> connectorAttributes = new HashMap<>();
        extractorAttributes.put("extractor.pattern", "root.db.d1");
        connectorAttributes.put("connector", "iotdb-thrift-connector");
        connectorAttributes.put("connector.batch.enable", "false");
        connectorAttributes.put("connector.ip", receiverIp);
        connectorAttributes.put("connector.port", Integer.toString(receiverPort));
        final TSStatus status = client.createPipe(new TCreatePipeReq("p1", connectorAttributes).setExtractorAttributes(extractorAttributes).setProcessorAttributes(processorAttributes));
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), status.getCode());
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), client.startPipe("p1").getCode());
        if (!TestUtils.tryExecuteNonQueriesWithRetry(senderEnv, Arrays.asList("insert into root.db.d1(time, s1) values (1, 1)", "flush"))) {
            return;
        }
        final AtomicInteger leaderPort = new AtomicInteger(-1);
        final TShowRegionResp showRegionResp = client.showRegion(new TShowRegionReq());
        showRegionResp.getRegionInfoList().forEach(regionInfo -> {
            if (RegionRoleType.Leader.getRoleType().equals(regionInfo.getRoleType())) {
                leaderPort.set(regionInfo.getClientRpcPort());
            }
        });
        int leaderIndex = -1;
        for (int i = 0; i < 3; ++i) {
            if (senderEnv.getDataNodeWrapper(i).getPort() == leaderPort.get()) {
                leaderIndex = i;
                try {
                    senderEnv.shutdownDataNode(i);
                } catch (final Throwable e) {
                    e.printStackTrace();
                    return;
                }
                try {
                    TimeUnit.SECONDS.sleep(1);
                } catch (final InterruptedException ignored) {
                }
                try {
                    senderEnv.startDataNode(i);
                    ((AbstractEnv) senderEnv).checkClusterStatusWithoutUnknown();
                } catch (final Throwable e) {
                    e.printStackTrace();
                    return;
                }
            }
        }
        if (leaderIndex == -1) {
            // ensure the leader is stopped
            fail();
        }
        if (!TestUtils.tryExecuteNonQueriesOnSpecifiedDataNodeWithRetry(senderEnv, senderEnv.getDataNodeWrapper(leaderIndex), Arrays.asList("insert into root.db.d1(time, s1) values (2, 2)", "flush"))) {
            return;
        }
        TestUtils.assertDataEventuallyOnEnv(receiverEnv, "select count(*) from root.db.d1", "count(root.db.d1.s1),", Collections.singleton("2,"));
    }
    try {
        TestUtils.restartCluster(senderEnv);
        TestUtils.restartCluster(receiverEnv);
    } catch (final Throwable e) {
        e.printStackTrace();
        return;
    }
    try (final SyncConfigNodeIServiceClient client = (SyncConfigNodeIServiceClient) senderEnv.getLeaderConfigNodeConnection()) {
        // Create a new pipe and write new data
        final Map<String, String> extractorAttributes = new HashMap<>();
        final Map<String, String> processorAttributes = new HashMap<>();
        final Map<String, String> connectorAttributes = new HashMap<>();
        extractorAttributes.put("extractor.pattern", "root.db.d2");
        connectorAttributes.put("connector", "iotdb-thrift-connector");
        connectorAttributes.put("connector.batch.enable", "false");
        connectorAttributes.put("connector.ip", receiverIp);
        connectorAttributes.put("connector.port", Integer.toString(receiverPort));
        final TSStatus status = client.createPipe(new TCreatePipeReq("p2", connectorAttributes).setExtractorAttributes(extractorAttributes).setProcessorAttributes(processorAttributes));
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), status.getCode());
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), client.startPipe("p2").getCode());
        if (!TestUtils.tryExecuteNonQueriesWithRetry(senderEnv, Arrays.asList("insert into root.db.d2(time, s1) values (1, 1)", "flush"))) {
            return;
        }
        TestUtils.assertDataEventuallyOnEnv(receiverEnv, "select count(*) from root.db.d2", "count(root.db.d2.s1),", Collections.singleton("1,"));
    }
}

