@Test
public void testConcurrentlyCreatePipeOfSameName() throws Exception {
    final DataNodeWrapper receiverDataNode = receiverEnv.getDataNodeWrapper(0);
    final String receiverIp = receiverDataNode.getIp();
    final int receiverPort = receiverDataNode.getPort();
    final Map<String, String> extractorAttributes = new HashMap<>();
    final Map<String, String> processorAttributes = new HashMap<>();
    final Map<String, String> connectorAttributes = new HashMap<>();
    connectorAttributes.put("connector", "iotdb-thrift-connector");
    connectorAttributes.put("connector.batch.enable", "false");
    connectorAttributes.put("connector.ip", receiverIp);
    connectorAttributes.put("connector.port", Integer.toString(receiverPort));
    final AtomicInteger successCount = new AtomicInteger(0);
    final List<Thread> threads = new ArrayList<>();
    for (int i = 0; i < 10; ++i) {
        final Thread t = new Thread(() -> {
            try (final SyncConfigNodeIServiceClient client = (SyncConfigNodeIServiceClient) senderEnv.getLeaderConfigNodeConnection()) {
                final TSStatus status = client.createPipe(new TCreatePipeReq("p1", connectorAttributes).setExtractorAttributes(extractorAttributes).setProcessorAttributes(processorAttributes));
                if (status.getCode() == TSStatusCode.SUCCESS_STATUS.getStatusCode()) {
                    successCount.incrementAndGet();
                }
            } catch (final InterruptedException e) {
                Thread.currentThread().interrupt();
            } catch (final TException | ClientManagerException | IOException e) {
                e.printStackTrace();
            } catch (final Exception e) {
                // Fail iff pipe exception occurs
                e.printStackTrace();
                fail(e.getMessage());
            }
        });
        t.start();
        threads.add(t);
    }
    for (Thread t : threads) {
        t.join();
    }
    Assert.assertEquals(1, successCount.get());
    successCount.set(0);
    for (int i = 0; i < 10; ++i) {
        final Thread t = new Thread(() -> {
            try (final SyncConfigNodeIServiceClient client = (SyncConfigNodeIServiceClient) senderEnv.getLeaderConfigNodeConnection()) {
                final TSStatus status = client.dropPipe("p1");
                if (status.getCode() == TSStatusCode.SUCCESS_STATUS.getStatusCode()) {
                    successCount.incrementAndGet();
                }
            } catch (final InterruptedException e) {
                Thread.currentThread().interrupt();
            } catch (final TException | ClientManagerException | IOException e) {
                e.printStackTrace();
            } catch (final Exception e) {
                // Fail iff pipe exception occurs
                e.printStackTrace();
                fail(e.getMessage());
            }
        });
        t.start();
        threads.add(t);
    }
    for (final Thread t : threads) {
        t.join();
    }
    // Assert at least 1 drop operation succeeds
    Assert.assertTrue(successCount.get() >= 1);
    try (final SyncConfigNodeIServiceClient client = (SyncConfigNodeIServiceClient) senderEnv.getLeaderConfigNodeConnection()) {
        final List<TShowPipeInfo> showPipeResult = client.showPipe(new TShowPipeReq()).pipeInfoList;
        Assert.assertEquals(0, showPipeResult.size());
    }
}

