@Test
public void testExtractorPatternMatch() throws Exception {
    final DataNodeWrapper receiverDataNode = receiverEnv.getDataNodeWrapper(0);
    final String receiverIp = receiverDataNode.getIp();
    final int receiverPort = receiverDataNode.getPort();
    try (final SyncConfigNodeIServiceClient client = (SyncConfigNodeIServiceClient) senderEnv.getLeaderConfigNodeConnection()) {
        if (!TestUtils.tryExecuteNonQueriesWithRetry(senderEnv, Arrays.asList("insert into root.nonAligned.1TS (time, s_float) values (now(), 0.5)", "insert into root.nonAligned.100TS (time, s_float) values (now(), 0.5)", "insert into root.nonAligned.1000TS (time, s_float) values (now(), 0.5)", "insert into root.nonAligned.`1(TS)` (time, s_float) values (now(), 0.5)", "insert into root.nonAligned.6TS.`6` (" + "time, `s_float(1)`, `s_int(1)`, `s_double(1)`, `s_long(1)`, `s_text(1)`, `s_bool(1)`) " + "values (now(), 0.5, 1, 1.5, 2, \"text1\", true)", "insert into root.aligned.1TS (time, s_float) aligned values (now(), 0.5)", "insert into root.aligned.100TS (time, s_float) aligned values (now(), 0.5)", "insert into root.aligned.1000TS (time, s_float) aligned values (now(), 0.5)", "insert into root.aligned.`1(TS)` (time, s_float) aligned values (now(), 0.5)", "insert into root.aligned.6TS.`6` (" + "time, `s_float(1)`, `s_int(1)`, `s_double(1)`, `s_long(1)`, `s_text(1)`, `s_bool(1)`) " + "aligned values (now(), 0.5, 1, 1.5, 2, \"text1\", true)"))) {
            return;
        }
        final Map<String, String> extractorAttributes = new HashMap<>();
        final Map<String, String> processorAttributes = new HashMap<>();
        final Map<String, String> connectorAttributes = new HashMap<>();
        extractorAttributes.put("extractor.pattern", null);
        extractorAttributes.put("extractor.inclusion", "data.insert");
        connectorAttributes.put("connector", "iotdb-thrift-connector");
        connectorAttributes.put("connector.batch.enable", "false");
        connectorAttributes.put("connector.ip", receiverIp);
        connectorAttributes.put("connector.port", Integer.toString(receiverPort));
        final List<String> patterns = Arrays.asList(// match nothing
        "root.db.nonExistPath", "root.nonAligned.1TS.s_float", "root.nonAligned.6TS.`6`.`s_text(1)`", "root.aligned.1TS", "root.aligned.6TS.`6`.`s_int(1)`", "root.aligned.`1(TS)`", "root.nonAligned.`1(TS)`", // match device root.aligned.6TS.`6`
        "root.aligned.6TS.`6`", // match device root.nonAligned.6TS.`6`
        "root.nonAligned.6TS.`6`", // match nothing
        "root.nonAligned.`1`", // match device root.nonAligned.1TS, 100TS and 100TS
        "root.nonAligned.1", // match device root.aligned.1TS, 100TS and 100TS
        "root.aligned.1");
        final List<Integer> expectedTimeseriesCount = Arrays.asList(0, 1, 2, 3, 4, 5, 6, 11, 16, 16, 18, 20);
        for (int i = 0; i < patterns.size(); ++i) {
            extractorAttributes.replace("extractor.pattern", patterns.get(i));
            final TSStatus status = client.createPipe(new TCreatePipeReq("p" + i, connectorAttributes).setExtractorAttributes(extractorAttributes).setProcessorAttributes(processorAttributes));
            Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), status.getCode());
            Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), client.startPipe("p" + i).getCode());
            // We add flush here because the pipe may be created on the new IoT leader
            // and the old leader's data may come as an unclosed historical tsfile
            // and is skipped flush when the pipe starts. In this case, the "waitForTsFileClose()"
            // may not return until a flush is executed, namely the data transfer relies
            // on a flush operation.
            if (!TestUtils.tryExecuteNonQueryWithRetry(senderEnv, "flush")) {
                return;
            }
            assertTimeseriesCountOnReceiver(receiverEnv, expectedTimeseriesCount.get(i));
        }
        TestUtils.assertDataEventuallyOnEnv(receiverEnv, "show devices", "Device,IsAligned,Template,TTL(ms),", new HashSet<>(Arrays.asList("root.nonAligned.1TS,false,null,INF,", "root.nonAligned.100TS,false,null,INF,", "root.nonAligned.1000TS,false,null,INF,", "root.nonAligned.`1(TS)`,false,null,INF,", "root.nonAligned.6TS.`6`,false,null,INF,", "root.aligned.1TS,true,null,INF,", "root.aligned.100TS,true,null,INF,", "root.aligned.1000TS,true,null,INF,", "root.aligned.`1(TS)`,true,null,INF,", "root.aligned.6TS.`6`,true,null,INF,")));
    }
}

@Test
public void testMatchingMultipleDatabases() throws Exception {
    final DataNodeWrapper receiverDataNode = receiverEnv.getDataNodeWrapper(0);
    final String receiverIp = receiverDataNode.getIp();
    final int receiverPort = receiverDataNode.getPort();
    try (final SyncConfigNodeIServiceClient client = (SyncConfigNodeIServiceClient) senderEnv.getLeaderConfigNodeConnection()) {
        final Map<String, String> extractorAttributes = new HashMap<>();
        final Map<String, String> processorAttributes = new HashMap<>();
        final Map<String, String> connectorAttributes = new HashMap<>();
        extractorAttributes.put("extractor.pattern", "root.db1");
        extractorAttributes.put("extractor.inclusion", "data.insert");
        connectorAttributes.put("connector", "iotdb-thrift-connector");
        connectorAttributes.put("connector.batch.enable", "false");
        connectorAttributes.put("connector.ip", receiverIp);
        connectorAttributes.put("connector.port", Integer.toString(receiverPort));
        TSStatus status = client.createPipe(new TCreatePipeReq("p1", connectorAttributes).setExtractorAttributes(extractorAttributes).setProcessorAttributes(processorAttributes));
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), status.getCode());
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), client.startPipe("p1").getCode());
        assertTimeseriesCountOnReceiver(receiverEnv, 0);
        if (!TestUtils.tryExecuteNonQueriesWithRetry(senderEnv, Arrays.asList("insert into root.db1.d1 (time, at1) values (1, 10)", "insert into root.db2.d1 (time, at1) values (1, 20)", "flush"))) {
            return;
        }
        extractorAttributes.replace("extractor.pattern", "root.db2");
        status = client.createPipe(new TCreatePipeReq("p2", connectorAttributes).setExtractorAttributes(extractorAttributes).setProcessorAttributes(processorAttributes));
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), status.getCode());
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), client.startPipe("p2").getCode());
        assertTimeseriesCountOnReceiver(receiverEnv, 2);
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), client.dropPipe("p1").getCode());
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), client.dropPipe("p2").getCode());
        if (!TestUtils.tryExecuteNonQueriesWithRetry(senderEnv, Arrays.asList("insert into root.db1.d1 (time, at1) values (2, 11)", "insert into root.db2.d1 (time, at1) values (2, 21)", "flush"))) {
            return;
        }
        // no pattern, will match all databases
        extractorAttributes.remove("extractor.pattern");
        status = client.createPipe(new TCreatePipeReq("p3", connectorAttributes).setExtractorAttributes(extractorAttributes).setProcessorAttributes(processorAttributes));
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), status.getCode());
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), client.startPipe("p3").getCode());
        TestUtils.assertDataEventuallyOnEnv(receiverEnv, "select count(*) from root.**", "count(root.db1.d1.at1),count(root.db2.d1.at1),", Collections.singleton("2,2,"));
    }
}

