@Test
public void testLifeCycleWithHistoryEnabled() throws Exception {
    final DataNodeWrapper receiverDataNode = receiverEnv.getDataNodeWrapper(0);
    final String receiverIp = receiverDataNode.getIp();
    final int receiverPort = receiverDataNode.getPort();
    try (final SyncConfigNodeIServiceClient client = (SyncConfigNodeIServiceClient) senderEnv.getLeaderConfigNodeConnection()) {
        if (!TestUtils.tryExecuteNonQueryWithRetry(senderEnv, "insert into root.db.d1(time, s1) values (1, 1)")) {
            return;
        }
        final Map<String, String> extractorAttributes = new HashMap<>();
        final Map<String, String> processorAttributes = new HashMap<>();
        final Map<String, String> connectorAttributes = new HashMap<>();
        connectorAttributes.put("connector", "iotdb-thrift-connector");
        connectorAttributes.put("connector.batch.enable", "false");
        connectorAttributes.put("connector.ip", receiverIp);
        connectorAttributes.put("connector.port", Integer.toString(receiverPort));
        final TSStatus status = client.createPipe(new TCreatePipeReq("p1", connectorAttributes).setExtractorAttributes(extractorAttributes).setProcessorAttributes(processorAttributes));
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), status.getCode());
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), client.startPipe("p1").getCode());
        final Set<String> expectedResSet = new HashSet<>();
        expectedResSet.add("1,1.0,");
        TestUtils.assertDataEventuallyOnEnv(receiverEnv, "select * from root.**", "Time,root.db.d1.s1,", expectedResSet);
        if (!TestUtils.tryExecuteNonQueriesWithRetry(senderEnv, Arrays.asList("insert into root.db.d1(time, s1) values (2, 2)", "flush"))) {
            return;
        }
        expectedResSet.add("2,2.0,");
        TestUtils.assertDataEventuallyOnEnv(receiverEnv, "select * from root.**", "Time,root.db.d1.s1,", expectedResSet);
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), client.stopPipe("p1").getCode());
        if (!TestUtils.tryExecuteNonQueriesWithRetry(senderEnv, Arrays.asList("insert into root.db.d1(time, s1) values (3, 3)", "flush"))) {
            return;
        }
        TestUtils.assertDataAlwaysOnEnv(receiverEnv, "select * from root.**", "Time,root.db.d1.s1,", expectedResSet);
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), client.startPipe("p1").getCode());
        expectedResSet.add("3,3.0,");
        TestUtils.assertDataEventuallyOnEnv(receiverEnv, "select * from root.**", "Time,root.db.d1.s1,", expectedResSet);
    }
}

