        if (!TestUtils.tryExecuteNonQueriesWithRetry(senderEnv, Arrays.asList("create database root.ln", "create timeseries root.db.d1.s2 with datatype=BOOLEAN,encoding=PLAIN", "insert into root.db.d1(time, s1) values (2, 2)", "flush"))) {
            return;
        }
        TestUtils.assertDataEventuallyOnEnv(receiverEnv, "select s1 from root.db.d1", "Time,root.db.d1.s1,", Collections.singleton("2,2.0,"));
