        if (!TestUtils.tryExecuteNonQueriesWithRetry(senderEnv, Arrays.asList("create database root.ln0", "create timeseries root.db.d1.s3 with datatype=BOOLEAN,encoding=PLAIN", "insert into root.db.d1(time, s1) values (3, 3)", "flush"))) {
            return;
        }
        TestUtils.assertDataAlwaysOnEnv(receiverEnv, "select s1 from root.db.d1", "Time,root.db.d1.s1,", Collections.singleton("2,2.0,"));
        TestUtils.assertDataAlwaysOnEnv(receiverEnv, "count timeseries", "count(timeseries),", Collections.singleton("2,"));
        TestUtils.assertDataAlwaysOnEnv(receiverEnv, "count databases", "count,", Collections.singleton("2,"));
