        if (!TestUtils.tryExecuteNonQueryWithRetry(senderEnv, "flush")) {
            return;
        }
        TestUtils.assertDataEventuallyOnEnv(receiverEnv, "select count(*) from root.**", "count(root.db.d1.s1),", Collections.singleton(succeedNum.get() + ","));
