@Test
public void testDoubleLiving() throws Exception {
    // Double living is two clusters with pipes connecting each other.
    final DataNodeWrapper senderDataNode = senderEnv.getDataNodeWrapper(0);
    final DataNodeWrapper receiverDataNode = receiverEnv.getDataNodeWrapper(0);
    final String senderIp = senderDataNode.getIp();
    final int senderPort = senderDataNode.getPort();
    final String receiverIp = receiverDataNode.getIp();
    final int receiverPort = receiverDataNode.getPort();
    for (int i = 0; i < 100; ++i) {
        if (!TestUtils.tryExecuteNonQueryWithRetry(senderEnv, String.format("insert into root.db.d1(time, s1) values (%s, 1)", i))) {
            return;
        }
    }
    if (!TestUtils.tryExecuteNonQueryWithRetry(senderEnv, "flush")) {
        return;
    }
    try (final SyncConfigNodeIServiceClient client = (SyncConfigNodeIServiceClient) senderEnv.getLeaderConfigNodeConnection()) {
        final Map<String, String> extractorAttributes = new HashMap<>();
        final Map<String, String> processorAttributes = new HashMap<>();
        final Map<String, String> connectorAttributes = new HashMap<>();
        // Add this property to avoid to make self cycle.
        connectorAttributes.put("source.forwarding-pipe-requests", "false");
        connectorAttributes.put("connector", "iotdb-thrift-connector");
        connectorAttributes.put("connector.batch.enable", "false");
        connectorAttributes.put("connector.ip", receiverIp);
        connectorAttributes.put("connector.port", Integer.toString(receiverPort));
        final TSStatus status = client.createPipe(new TCreatePipeReq("p1", connectorAttributes).setExtractorAttributes(extractorAttributes).setProcessorAttributes(processorAttributes));
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), status.getCode());
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), client.startPipe("p1").getCode());
    }
    for (int i = 100; i < 200; ++i) {
        if (!TestUtils.tryExecuteNonQueryWithRetry(senderEnv, String.format("insert into root.db.d1(time, s1) values (%s, 1)", i))) {
            return;
        }
    }
    if (!TestUtils.tryExecuteNonQueryWithRetry(senderEnv, "flush")) {
        return;
    }
    for (int i = 200; i < 300; ++i) {
        if (!TestUtils.tryExecuteNonQueryWithRetry(receiverEnv, String.format("insert into root.db.d1(time, s1) values (%s, 1)", i))) {
            return;
        }
    }
    if (!TestUtils.tryExecuteNonQueryWithRetry(receiverEnv, "flush")) {
        return;
    }
    try (final SyncConfigNodeIServiceClient client = (SyncConfigNodeIServiceClient) receiverEnv.getLeaderConfigNodeConnection()) {
        final Map<String, String> extractorAttributes = new HashMap<>();
        final Map<String, String> processorAttributes = new HashMap<>();
        final Map<String, String> connectorAttributes = new HashMap<>();
        // Add this property to avoid to make self cycle.
        connectorAttributes.put("source.forwarding-pipe-requests", "false");
        connectorAttributes.put("connector", "iotdb-thrift-connector");
        connectorAttributes.put("connector.batch.enable", "false");
        connectorAttributes.put("connector.ip", senderIp);
        connectorAttributes.put("connector.port", Integer.toString(senderPort));
        final TSStatus status = client.createPipe(new TCreatePipeReq("p1", connectorAttributes).setExtractorAttributes(extractorAttributes).setProcessorAttributes(processorAttributes));
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), status.getCode());
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), client.startPipe("p1").getCode());
    }
    for (int i = 300; i < 400; ++i) {
        if (!TestUtils.tryExecuteNonQueryWithRetry(receiverEnv, String.format("insert into root.db.d1(time, s1) values (%s, 1)", i))) {
            return;
        }
    }
    if (!TestUtils.tryExecuteNonQueryWithRetry(receiverEnv, "flush")) {
        return;
    }
    final Set<String> expectedResSet = new HashSet<>();
    for (int i = 0; i < 400; ++i) {
        expectedResSet.add(i + ",1.0,");
    }
    TestUtils.assertDataEventuallyOnEnv(senderEnv, "select * from root.**", "Time,root.db.d1.s1,", expectedResSet);
    TestUtils.assertDataEventuallyOnEnv(receiverEnv, "select * from root.**", "Time,root.db.d1.s1,", expectedResSet);
    try {
