@Test
public void testPermission() {
    createUser(senderEnv, "test", "test123");
    assertNonQueryTestFail(senderEnv, "create pipe testPipe\n" + "with connector (\n" + "  'connector'='iotdb-thrift-connector',\n" + "  'connector.ip'='127.0.0.1',\n" + "  'connector.port'='6668'\n" + ")", "803: No permissions for this operation, please add privilege USE_PIPE", "test", "test123");
    assertNonQueryTestFail(senderEnv, "drop pipe testPipe", "803: No permissions for this operation, please add privilege USE_PIPE", "test", "test123");
    assertTestFail(senderEnv, "show pipes", "803: No permissions for this operation, please add privilege USE_PIPE", "test", "test123");
    assertNonQueryTestFail(senderEnv, "start pipe testPipe", "803: No permissions for this operation, please add privilege USE_PIPE", "test", "test123");
    assertNonQueryTestFail(senderEnv, "stop pipe testPipe", "803: No permissions for this operation, please add privilege USE_PIPE", "test", "test123");
    assertNonQueryTestFail(senderEnv, "create pipePlugin TestProcessor as 'org.apache.iotdb.db.pipe.example.TestProcessor' USING URI 'xxx'", "803: No permissions for this operation, please add privilege USE_PIPE", "test", "test123");
    assertNonQueryTestFail(senderEnv, "drop pipePlugin TestProcessor", "803: No permissions for this operation, please add privilege USE_PIPE", "test", "test123");
    assertTestFail(senderEnv, "show pipe plugins", "803: No permissions for this operation, please add privilege USE_PIPE", "test", "test123");
    grantUserSystemPrivileges(senderEnv, "test", PrivilegeType.USE_PIPE);
    tryExecuteNonQueryWithRetry(senderEnv, "create pipe testPipe\n" + "with connector (\n" + "  'connector'='iotdb-thrift-connector',\n" + "  'connector.ip'='127.0.0.1',\n" + "  'connector.port'='6668'\n" + ")", "test", "test123");
    executeQueryWithRetry(senderEnv, "show pipes", "test", "test123");
    tryExecuteNonQueriesWithRetry(senderEnv, Arrays.asList("start pipe testPipe", "stop pipe testPipe", "drop pipe testPipe"), "test", "test123");
    assertNonQueryTestFail(senderEnv, "create pipePlugin TestProcessor as 'org.apache.iotdb.db.pipe.example.TestProcessor' USING URI 'xxx'", "1603: The scheme of URI is not set, please specify the scheme of URI.", "test", "test123");
    tryExecuteNonQueryWithRetry(senderEnv, "drop pipePlugin TestProcessor", "test", "test123");
    executeQueryWithRetry(senderEnv, "show pipe plugins", "test", "test123");
}

