@Test
public void testPipeOnBothSenderAndReceiver() throws Exception {
    senderEnv.getConfig().getCommonConfig().setAutoCreateSchemaEnabled(true).setConfigNodeConsensusProtocolClass(ConsensusFactory.RATIS_CONSENSUS).setSchemaRegionConsensusProtocolClass(ConsensusFactory.RATIS_CONSENSUS).setDataRegionConsensusProtocolClass(ConsensusFactory.IOT_CONSENSUS).setSchemaReplicationFactor(3).setDataReplicationFactor(2);
    receiverEnv.getConfig().getCommonConfig().setAutoCreateSchemaEnabled(true).setConfigNodeConsensusProtocolClass(ConsensusFactory.RATIS_CONSENSUS).setSchemaRegionConsensusProtocolClass(ConsensusFactory.RATIS_CONSENSUS).setDataRegionConsensusProtocolClass(ConsensusFactory.IOT_CONSENSUS).setSchemaReplicationFactor(1).setDataReplicationFactor(1);
    // 10 min, assert that the operations will not time out
    senderEnv.getConfig().getCommonConfig().setCnConnectionTimeoutMs(600000);
    receiverEnv.getConfig().getCommonConfig().setCnConnectionTimeoutMs(600000);
    senderEnv.initClusterEnvironment(3, 3);
    receiverEnv.initClusterEnvironment(1, 1);
    final DataNodeWrapper receiverDataNode = receiverEnv.getDataNodeWrapper(0);
    final String receiverIp = receiverDataNode.getIp();
    final int receiverPort = receiverDataNode.getPort();
    try (final SyncConfigNodeIServiceClient client = (SyncConfigNodeIServiceClient) senderEnv.getLeaderConfigNodeConnection()) {
        if (!TestUtils.tryExecuteNonQueryWithRetry(senderEnv, "insert into root.db.d1(time, s1) values (1, 1)")) {
            return;
        }
        final Map<String, String> extractorAttributes = new HashMap<>();
        final Map<String, String> processorAttributes = new HashMap<>();
        final Map<String, String> connectorAttributes = new HashMap<>();
        connectorAttributes.put("connector", "iotdb-thrift-connector");
        connectorAttributes.put("connector.batch.enable", "false");
        connectorAttributes.put("connector.ip", receiverIp);
        connectorAttributes.put("connector.port", Integer.toString(receiverPort));
        final TSStatus status = client.createPipe(new TCreatePipeReq("p1", connectorAttributes).setExtractorAttributes(extractorAttributes).setProcessorAttributes(processorAttributes));
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), status.getCode());
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), client.startPipe("p1").getCode());
        TestUtils.assertDataEventuallyOnEnv(receiverEnv, "select count(*) from root.**", "count(root.db.d1.s1),", Collections.singleton("1,"));
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), client.stopPipe("p1").getCode());
    }
    final DataNodeWrapper senderDataNode = senderEnv.getDataNodeWrapper(0);
    final String senderIp = senderDataNode.getIp();
    final int senderPort = senderDataNode.getPort();
    try (final SyncConfigNodeIServiceClient client = (SyncConfigNodeIServiceClient) receiverEnv.getLeaderConfigNodeConnection()) {
        if (!TestUtils.tryExecuteNonQueryWithRetry(receiverEnv, "insert into root.db.d1(time, s1) values (2, 2)")) {
            return;
        }
        final Map<String, String> extractorAttributes = new HashMap<>();
        final Map<String, String> processorAttributes = new HashMap<>();
        final Map<String, String> connectorAttributes = new HashMap<>();
        connectorAttributes.put("connector", "iotdb-thrift-connector");
        connectorAttributes.put("connector.batch.enable", "false");
        connectorAttributes.put("connector.ip", senderIp);
        connectorAttributes.put("connector.port", Integer.toString(senderPort));
        final TSStatus status = client.createPipe(new TCreatePipeReq("p1", connectorAttributes).setExtractorAttributes(extractorAttributes).setProcessorAttributes(processorAttributes));
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), status.getCode());
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), client.startPipe("p1").getCode());
        TestUtils.assertDataEventuallyOnEnv(senderEnv, "select count(*) from root.**", "count(root.db.d1.s1),", Collections.singleton("2,"));
    }
}

