@Test
public void testPipeSwitchStatus() throws Exception {
    final DataNodeWrapper receiverDataNode = receiverEnv.getDataNodeWrapper(0);
    final String receiverIp = receiverDataNode.getIp();
    final int receiverPort = receiverDataNode.getPort();
    try (final SyncConfigNodeIServiceClient client = (SyncConfigNodeIServiceClient) senderEnv.getLeaderConfigNodeConnection()) {
        final Map<String, String> extractorAttributes = new HashMap<>();
        final Map<String, String> processorAttributes = new HashMap<>();
        final Map<String, String> connectorAttributes = new HashMap<>();
        connectorAttributes.put("connector", "iotdb-thrift-connector");
        connectorAttributes.put("connector.batch.enable", "false");
        connectorAttributes.put("connector.ip", receiverIp);
        connectorAttributes.put("connector.port", Integer.toString(receiverPort));
        TSStatus status = client.createPipe(new TCreatePipeReq("p1", connectorAttributes).setExtractorAttributes(extractorAttributes).setProcessorAttributes(processorAttributes));
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), status.getCode());
        status = client.createPipe(new TCreatePipeReq("p2", connectorAttributes).setExtractorAttributes(extractorAttributes).setProcessorAttributes(processorAttributes));
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), status.getCode());
        status = client.createPipe(new TCreatePipeReq("p3", connectorAttributes).setExtractorAttributes(extractorAttributes).setProcessorAttributes(processorAttributes));
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), status.getCode());
        List<TShowPipeInfo> showPipeResult = client.showPipe(new TShowPipeReq()).pipeInfoList;
        Assert.assertTrue(showPipeResult.stream().anyMatch((o) -> o.id.equals("p1") && o.state.equals("RUNNING")));
        Assert.assertTrue(showPipeResult.stream().anyMatch((o) -> o.id.equals("p2") && o.state.equals("RUNNING")));
        Assert.assertTrue(showPipeResult.stream().anyMatch((o) -> o.id.equals("p3") && o.state.equals("RUNNING")));
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), client.startPipe("p1").getCode());
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), client.startPipe("p2").getCode());
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), client.dropPipe("p3").getCode());
        showPipeResult = client.showPipe(new TShowPipeReq()).pipeInfoList;
        Assert.assertTrue(showPipeResult.stream().anyMatch((o) -> o.id.equals("p1") && o.state.equals("RUNNING")));
        Assert.assertTrue(showPipeResult.stream().anyMatch((o) -> o.id.equals("p2") && o.state.equals("RUNNING")));
        Assert.assertFalse(showPipeResult.stream().anyMatch((o) -> o.id.equals("p3")));
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), client.stopPipe("p1").getCode());
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), client.dropPipe("p2").getCode());
        showPipeResult = client.showPipe(new TShowPipeReq()).pipeInfoList;
        Assert.assertTrue(showPipeResult.stream().anyMatch((o) -> o.id.equals("p1") && o.state.equals("STOPPED")));
        Assert.assertFalse(showPipeResult.stream().anyMatch((o) -> o.id.equals("p2")));
        Assert.assertEquals(TSStatusCode.SUCCESS_STATUS.getStatusCode(), client.dropPipe("p1").getCode());
        showPipeResult = client.showPipe(new TShowPipeReq()).pipeInfoList;
        Assert.assertFalse(showPipeResult.stream().anyMatch((o) -> o.id.equals("p1")));
    }
}

