@Test
public void testValidPipeName() throws Exception {
    final DataNodeWrapper receiverDataNode = receiverEnv.getDataNodeWrapper(0);
    final String receiverIp = receiverDataNode.getIp();
    final int receiverPort = receiverDataNode.getPort();
    try (final SyncConfigNodeIServiceClient client = (SyncConfigNodeIServiceClient) senderEnv.getLeaderConfigNodeConnection()) {
        final List<String> validPipeNames = Arrays.asList("Pipe_1", "null", "`33`", "`root`", "中文", "with");
        final List<String> expectedPipeNames = Arrays.asList("Pipe_1", "null", "33", "root", "中文", "with");
        for (final String pipeName : validPipeNames) {
            try (final Connection connection = senderEnv.getConnection();
                final Statement statement = connection.createStatement()) {
                statement.execute(String.format("create pipe %s" + " with connector (" + "'connector'='iotdb-thrift-connector'," + "'connector.ip'='%s'," + "'connector.port'='%s'," + "'connector.batch.enable'='false')", pipeName, receiverIp, receiverPort));
            } catch (SQLException e) {
                e.printStackTrace();
                fail(e.getMessage());
            }
        }
        List<TShowPipeInfo> showPipeResult = client.showPipe(new TShowPipeReq()).pipeInfoList;
        for (final String pipeName : expectedPipeNames) {
            Assert.assertTrue(showPipeResult.stream().anyMatch((o) -> o.id.equals(pipeName) && o.state.equals("RUNNING")));
        }
        for (final String pipeName : validPipeNames) {
            try (final Connection connection = senderEnv.getConnection();
                final Statement statement = connection.createStatement()) {
                statement.execute(String.format("drop pipe %s", pipeName));
            } catch (SQLException e) {
                e.printStackTrace();
                fail(e.getMessage());
            }
        }
        showPipeResult = client.showPipe(new TShowPipeReq()).pipeInfoList;
        Assert.assertEquals(0, showPipeResult.size());
    }
}

