@Test
public void testSubscriptionAfterRestartCluster() throws Exception {
    final String host = EnvFactory.getEnv().getIP();
    final int port = Integer.parseInt(EnvFactory.getEnv().getPort());
    // Create topic
    final String topicName = "topic1";
    try (final SubscriptionSession session = new SubscriptionSession(host, port)) {
        session.open();
        session.createTopic(topicName);
    } catch (final Exception e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
    // Subscription
    final SubscriptionPullConsumer consumer;
    try {
        consumer = new SubscriptionPullConsumer.Builder().host(host).port(port).consumerId("c1").consumerGroupId("cg1").autoCommit(true).heartbeatIntervalMs(// narrow heartbeat interval
        1000).endpointsSyncIntervalMs(// narrow endpoints sync interval
        5000).buildPullConsumer();
        consumer.open();
        consumer.subscribe(topicName);
    } catch (final Exception e) {
        e.printStackTrace();
        fail(e.getMessage());
        return;
    }
    // Restart cluster
    try {
        TestUtils.restartCluster(EnvFactory.getEnv());
    } catch (final Throwable e) {
        e.printStackTrace();
        // Avoid failure
        return;
    }
    // Show topics and subscriptions
    try (final SyncConfigNodeIServiceClient client = (SyncConfigNodeIServiceClient) EnvFactory.getEnv().getLeaderConfigNodeConnection()) {
        final TShowTopicResp showTopicResp = client.showTopic(new TShowTopicReq());
        Assert.assertEquals(RpcUtils.SUCCESS_STATUS.getCode(), showTopicResp.status.getCode());
        Assert.assertNotNull(showTopicResp.topicInfoList);
