@Test
public void testTopicTimePrecision() throws Exception {
    final String host = senderEnv.getIP();
    final int port = Integer.parseInt(senderEnv.getPort());
    // Insert some historical data on sender
    // in nanosecond
    final long currentTime1 = System.currentTimeMillis() * 1000_000L;
    try (final ISession session = senderEnv.getSessionConnection()) {
        for (int i = 0; i < 100; ++i) {
            session.executeNonQueryStatement(String.format("insert into root.db.d1(time, s1) values (%s, 1)", i));
            session.executeNonQueryStatement(String.format("insert into root.db.d1(time, s2) values (%s, 1)", currentTime1 - i));
        }
        session.executeNonQueryStatement("flush");
    } catch (final Exception e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
    // Create topic on sender
    final String topic1 = "topic1";
    final String topic2 = "topic2";
    try (final SubscriptionSession session = new SubscriptionSession(host, port)) {
        session.open();
        {
            final Properties config = new Properties();
            config.put(TopicConstant.START_TIME_KEY, currentTime1 - 99);
            config.put(TopicConstant.END_TIME_KEY, // now should be strictly larger than current time 1
            TopicConstant.NOW_TIME_VALUE);
            session.createTopic(topic1, config);
        }
        {
            final Properties config = new Properties();
            config.put(TopicConstant.START_TIME_KEY, // now should be strictly smaller than current time 2
            TopicConstant.NOW_TIME_VALUE);
            session.createTopic(topic2, config);
        }
    } catch (final Exception e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
    // Insert some historical data on sender again
    // in nanosecond
    final long currentTime2 = System.currentTimeMillis() * 1000_000L;
    try (final ISession session = senderEnv.getSessionConnection()) {
        for (int i = 0; i < 100; ++i) {
            session.executeNonQueryStatement(String.format("insert into root.db.d2(time, s1) values (%s, 1)", currentTime2 + i));
        }
        session.executeNonQueryStatement("flush");
    } catch (final Exception e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
    // Subscribe on sender and insert on receiver
    final AtomicBoolean isClosed = new AtomicBoolean(false);
    final Thread thread = new Thread(() -> {
        try (final SubscriptionPullConsumer consumer = new SubscriptionPullConsumer.Builder().host(host).port(port).consumerId("c1").consumerGroupId("cg1").autoCommit(false).buildPullConsumer();
            final ISession session = receiverEnv.getSessionConnection()) {
            consumer.open();
            consumer.subscribe(topic1, topic2);
            while (!isClosed.get()) {
                // wait some time
                LockSupport.parkNanos(IoTDBSubscriptionITConstant.SLEEP_NS);
                final List<SubscriptionMessage> messages = consumer.poll(IoTDBSubscriptionITConstant.POLL_TIMEOUT_MS);
                for (final SubscriptionMessage message : messages) {
                    for (final Iterator<Tablet> it = message.getSessionDataSetsHandler().tabletIterator(); it.hasNext(); ) {
                        final Tablet tablet = it.next();
                        session.insertTablet(tablet);
                    }
                }
                consumer.commitSync(messages);
            }
            // Auto unsubscribe topics
        } catch (final Exception e) {
            e.printStackTrace();
            // Avoid failure
        } finally {
            LOGGER.info("consumer exiting...");
        }
    }, String.format("%s - consumer", testName.getMethodName()));
    thread.start();
    // Check data on receiver
    try {
        try (final Connection connection = receiverEnv.getConnection();
            final Statement statement = connection.createStatement()) {
            // Keep retrying if there are execution failures
            AWAIT.untilAsserted(() -> TestUtils.assertSingleResultSetEqual(TestUtils.executeQueryWithRetry(statement, "select count(*) from root.**"), new HashMap<String, String>() {

                {
                    put("count(root.db.d1.s2)", "100");
                    put("count(root.db.d2.s1)", "100");
                }
            }));
        }
    } catch (final Exception e) {
        e.printStackTrace();
        fail(e.getMessage());
    } finally {
        isClosed.set(true);
        thread.join();
    }
}

