@Test
public void testSubscribeOrUnsubscribeNonExistedTopicTest() {
    final String host = EnvFactory.getEnv().getIP();
    final int port = Integer.parseInt(EnvFactory.getEnv().getPort());
    // Subscribe non-existed topic
    final String topicName = "topic1";
    try (final SubscriptionPullConsumer consumer = new SubscriptionPullConsumer.Builder().host(host).port(port).consumerId("c1").consumerGroupId("cg1").autoCommit(false).buildPullConsumer()) {
        consumer.open();
        consumer.subscribe(topicName);
        fail();
    } catch (final Exception ignored) {
    } finally {
        LOGGER.info("consumer exiting...");
    }
    // Unsubscribe non-existed topic
    try (final SubscriptionPullConsumer consumer = new SubscriptionPullConsumer.Builder().host(host).port(port).consumerId("c1").consumerGroupId("cg1").autoCommit(false).buildPullConsumer()) {
        consumer.open();
        consumer.unsubscribe(topicName);
        fail();
    } catch (final Exception ignored) {
    } finally {
        LOGGER.info("consumer exiting...");
    }
}

