    } catch (Exception e) {
        flag = true;
    }
    assertFalse(flag);
    flag = false;
    try {
        metadata = new IoTDBResultMetadata(false, null, "QUERY", Collections.emptyList(), null, false);
        metadata.getColumnCount();
    } catch (Exception e) {
        flag = true;
    }
