    ZoneId zoneId = ZoneId.of("+0000");
    Assert.assertEquals("1969-12-31T23:59:59.999Z", RpcUtils.parseLongToDateWithPrecision(formatter, -1, zoneId, "ms"));
    Assert.assertEquals("1969-12-31T23:59:59.999999Z", RpcUtils.parseLongToDateWithPrecision(formatter, -1, zoneId, "us"));
    Assert.assertEquals("1969-12-31T23:59:59.999999999Z", RpcUtils.parseLongToDateWithPrecision(formatter, -1, zoneId, "ns"));
    Assert.assertEquals("1969-12-31T23:59:59.000Z", RpcUtils.parseLongToDateWithPrecision(formatter, -1000, zoneId, "ms"));
    Assert.assertEquals("1969-12-31T23:59:59.000000Z", RpcUtils.parseLongToDateWithPrecision(formatter, -1000_000, zoneId, "us"));
    Assert.assertEquals("1969-12-31T23:59:59.000000000Z", RpcUtils.parseLongToDateWithPrecision(formatter, -1000_000_000L, zoneId, "ns"));
    Assert.assertEquals("1970-01-01T00:00:00.001Z", RpcUtils.parseLongToDateWithPrecision(formatter, 1, zoneId, "ms"));
    Assert.assertEquals("1970-01-01T00:00:00.000001Z", RpcUtils.parseLongToDateWithPrecision(formatter, 1, zoneId, "us"));
    Assert.assertEquals("1970-01-01T00:00:00.000000001Z", RpcUtils.parseLongToDateWithPrecision(formatter, 1, zoneId, "ns"));
    zoneId = ZoneId.of("+0800");
    Assert.assertEquals("1970-01-01T07:59:59.999+08:00", RpcUtils.parseLongToDateWithPrecision(formatter, -1, zoneId, "ms"));
}

