@Test
public void testUpdateDataAllotTable() {
    DataPartitionPolicyTable dataPartitionPolicyTable = new DataPartitionPolicyTable();
    List<TConsensusGroupId> dataRegionGroups = new ArrayList<>();
    // Test 1: construct DataAllotTable from scratch
    TConsensusGroupId group1 = new TConsensusGroupId(TConsensusGroupType.DataRegion, 1);
    dataRegionGroups.add(group1);
    dataPartitionPolicyTable.reBalanceDataPartitionPolicy(dataRegionGroups);
    for (int i = 0; i < SERIES_SLOT_NUM; i++) {
        TSeriesPartitionSlot seriesPartitionSlot = new TSeriesPartitionSlot(i);
        // All SeriesPartitionSlots belong to group1
        Assert.assertEquals(group1, dataPartitionPolicyTable.getRegionGroupIdOrActivateIfNecessary(seriesPartitionSlot));
    }
    // Test2: extend DataRegionGroups
    Map<TSeriesPartitionSlot, TConsensusGroupId> lastDataAllotTable = new HashMap<>();
    dataRegionGroups.add(new TConsensusGroupId(TConsensusGroupType.DataRegion, 2));
    dataRegionGroups.add(new TConsensusGroupId(TConsensusGroupType.DataRegion, 3));
    dataPartitionPolicyTable.reBalanceDataPartitionPolicy(dataRegionGroups);
    int mu = SERIES_SLOT_NUM / 3;
    Map<TConsensusGroupId, AtomicInteger> counter = new HashMap<>();
    for (int i = 0; i < SERIES_SLOT_NUM; i++) {
        TSeriesPartitionSlot seriesPartitionSlot = new TSeriesPartitionSlot(i);
        TConsensusGroupId groupId = dataPartitionPolicyTable.getRegionGroupIdOrActivateIfNecessary(seriesPartitionSlot);
        lastDataAllotTable.put(seriesPartitionSlot, groupId);
        counter.computeIfAbsent(groupId, empty -> new AtomicInteger(0)).incrementAndGet();
    }
    // All DataRegionGroups divide SeriesPartitionSlots evenly
    for (Map.Entry<TConsensusGroupId, AtomicInteger> counterEntry : counter.entrySet()) {
        Assert.assertTrue(Math.abs(counterEntry.getValue().get() - mu) <= 1);
    }
    // Test 3: extend DataRegionGroups while inherit as much SeriesPartitionSlots as possible
    dataRegionGroups.add(new TConsensusGroupId(TConsensusGroupType.DataRegion, 4));
    dataRegionGroups.add(new TConsensusGroupId(TConsensusGroupType.DataRegion, 5));
    dataPartitionPolicyTable.reBalanceDataPartitionPolicy(dataRegionGroups);
    Map<TConsensusGroupId, AtomicInteger> unchangedSlots = new HashMap<>();
    mu = SERIES_SLOT_NUM / 5;
    counter.clear();
    for (int i = 0; i < SERIES_SLOT_NUM; i++) {
        TSeriesPartitionSlot seriesPartitionSlot = new TSeriesPartitionSlot(i);
        TConsensusGroupId groupId = dataPartitionPolicyTable.getRegionGroupIdOrActivateIfNecessary(seriesPartitionSlot);
        counter.computeIfAbsent(groupId, empty -> new AtomicInteger(0)).incrementAndGet();
        if (groupId.getId() < 4) {
            // Most of SeriesPartitionSlots in the first three DataRegionGroups should remain unchanged
            Assert.assertEquals(lastDataAllotTable.get(seriesPartitionSlot), groupId);
            unchangedSlots.computeIfAbsent(groupId, empty -> new AtomicInteger(0)).incrementAndGet();
        }
    }
    // All DataRegionGroups divide SeriesPartitionSlots evenly
    for (Map.Entry<TConsensusGroupId, AtomicInteger> counterEntry : counter.entrySet()) {
        Assert.assertTrue(Math.abs(counterEntry.getValue().get() - mu) <= 1);
    }
    // Most of SeriesPartitionSlots in the first three DataRegionGroups should remain unchanged
    for (Map.Entry<TConsensusGroupId, AtomicInteger> counterEntry : unchangedSlots.entrySet()) {
        Assert.assertEquals(mu, counterEntry.getValue().get());
    }
}

@Test
public void testScatterWidth() {
    final int dataRegionGroupNum = DATA_REGION_PER_DATA_NODE * TEST_DATA_NODE_NUM / DATA_REPLICATION_FACTOR;
    /* Allocate DataRegionGroups */
    long startTime = System.currentTimeMillis();
    List<TRegionReplicaSet> allocateResult = new ArrayList<>();
    for (int index = 0; index < dataRegionGroupNum; index++) {
        allocateResult.add(ALLOCATOR.generateOptimalRegionReplicasDistribution(AVAILABLE_DATA_NODE_MAP, FREE_SPACE_MAP, allocateResult, allocateResult, DATA_REPLICATION_FACTOR, new TConsensusGroupId(TConsensusGroupType.DataRegion, index)));
    }
    long endTime = System.currentTimeMillis();
    /* Statistics result */
    // Map<DataNodeId, RegionGroup Count>
    Map<Integer, Integer> regionCounter = new HashMap<>();
    allocateResult.forEach(regionReplicaSet -> regionReplicaSet.getDataNodeLocations().forEach(dataNodeLocation -> regionCounter.merge(dataNodeLocation.getDataNodeId(), 1, Integer::sum)));
    // Map<DataNodeId, ScatterWidth>
    // where a true in the bitset denotes the corresponding DataNode can help the DataNode in
    // Map-Key to share the RegionGroup-leader and restore data when restarting.
    // The more true in the bitset, the more safety the cluster DataNode in Map-Key is.
    Map<Integer, BitSet> scatterWidthMap = new HashMap<>();
    for (TRegionReplicaSet replicaSet : allocateResult) {
        for (int i = 0; i < DATA_REPLICATION_FACTOR; i++) {
            for (int j = i + 1; j < DATA_REPLICATION_FACTOR; j++) {
                int dataNodeId1 = replicaSet.getDataNodeLocations().get(i).getDataNodeId();
                int dataNodeId2 = replicaSet.getDataNodeLocations().get(j).getDataNodeId();
                scatterWidthMap.computeIfAbsent(dataNodeId1, empty -> new BitSet()).set(dataNodeId2);
                scatterWidthMap.computeIfAbsent(dataNodeId2, empty -> new BitSet()).set(dataNodeId1);
            }
        }
    }
    int scatterWidthSum = 0;
    int minScatterWidth = Integer.MAX_VALUE;
    int maxScatterWidth = Integer.MIN_VALUE;
    for (int i = 1; i <= TEST_DATA_NODE_NUM; i++) {
        Assert.assertTrue(regionCounter.get(i) <= DATA_REGION_PER_DATA_NODE);
        int scatterWidth = scatterWidthMap.get(i).cardinality();
        scatterWidthSum += scatterWidth;
        minScatterWidth = Math.min(minScatterWidth, scatterWidth);
        maxScatterWidth = Math.max(maxScatterWidth, scatterWidth);
    }
    LOGGER.info("Test {}:", ALLOCATOR.getClass().getSimpleName());
    LOGGER.info("Allocate {} DataRegionGroups for {} DataNodes in {}ms", dataRegionGroupNum, TEST_DATA_NODE_NUM, endTime - startTime);
    LOGGER.info("Scatter width avg: {}, min: {}, max: {}", (double) scatterWidthSum / TEST_DATA_NODE_NUM, minScatterWidth, maxScatterWidth);
}

