@Test
public void testGenLoadScoreGreedyRoutingPolicy() {
    /* Build TDataNodeLocations */
    List<TDataNodeLocation> dataNodeLocations = new ArrayList<>();
    for (int i = 0; i < 4; i++) {
        dataNodeLocations.add(new TDataNodeLocation(i, new TEndPoint("0.0.0.0", 6667 + i), new TEndPoint("0.0.0.0", 10730 + i), new TEndPoint("0.0.0.0", 10740 + i), new TEndPoint("0.0.0.0", 10760 + i), new TEndPoint("0.0.0.0", 10750 + i)));
    }
    /* Build nodeCacheMap */
    long currentTimeNs = System.nanoTime();
    Map<Integer, BaseNodeCache> nodeCacheMap = new HashMap<>();
    NodeStatus[] statuses = new NodeStatus[] { NodeStatus.Running, NodeStatus.Unknown, NodeStatus.Running, NodeStatus.ReadOnly };
    for (int i = 0; i < 4; i++) {
        nodeCacheMap.put(i, new DataNodeHeartbeatCache(i));
        nodeCacheMap.get(i).cacheHeartbeatSample(new NodeHeartbeatSample(currentTimeNs, statuses[i]));
    }
    nodeCacheMap.values().forEach(BaseNodeCache::updateCurrentStatistics);
    /* Get the loadScoreMap */
    Map<Integer, Long> loadScoreMap = new ConcurrentHashMap<>();
    nodeCacheMap.forEach((dataNodeId, heartbeatCache) -> loadScoreMap.put(dataNodeId, heartbeatCache.getLoadScore()));
    /* Build TRegionReplicaSet */
    TConsensusGroupId groupId1 = new TConsensusGroupId(TConsensusGroupType.SchemaRegion, 1);
    TRegionReplicaSet regionReplicaSet1 = new TRegionReplicaSet(groupId1, Arrays.asList(dataNodeLocations.get(1), dataNodeLocations.get(0)));
    TConsensusGroupId groupId2 = new TConsensusGroupId(TConsensusGroupType.DataRegion, 2);
    TRegionReplicaSet regionReplicaSet2 = new TRegionReplicaSet(groupId2, Arrays.asList(dataNodeLocations.get(2), dataNodeLocations.get(3)));
    /* Check result */
    Map<TConsensusGroupId, TRegionReplicaSet> result = new GreedyPriorityBalancer().generateOptimalRoutePriority(Arrays.asList(regionReplicaSet1, regionReplicaSet2), new HashMap<>(), loadScoreMap);
    Assert.assertEquals(2, result.size());
    TRegionReplicaSet result1 = result.get(groupId1);
    for (int i = 0; i < 2; i++) {
        Assert.assertEquals(dataNodeLocations.get(i), result1.getDataNodeLocations().get(i));
    }
    TRegionReplicaSet result2 = result.get(groupId2);
    for (int i = 3; i < 4; i++) {
        Assert.assertEquals(dataNodeLocations.get(i), result2.getDataNodeLocations().get(i - 2));
    }
}

@Test
public void testGenRealTimeRoutingPolicy() {
