    final ExtendSchemaTemplatePlan extendSchemaTemplatePlan = new ExtendSchemaTemplatePlan(new TemplateExtendInfo("template_name", Arrays.asList("s1", "s2"), Arrays.asList(TSDataType.FLOAT, TSDataType.BOOLEAN), Arrays.asList(TSEncoding.RLE, TSEncoding.PLAIN), Arrays.asList(CompressionType.SNAPPY, CompressionType.SNAPPY)));
    final ExtendSchemaTemplatePlan parsedTemplatePlan = (ExtendSchemaTemplatePlan) IoTDBConfigRegionExtractor.PATTERN_PARSE_VISITOR.visitExtendSchemaTemplate(extendSchemaTemplatePlan, fullPathPattern).orElseThrow(AssertionError::new);
    Assert.assertEquals(Collections.singletonList("s1"), parsedTemplatePlan.getTemplateExtendInfo().getMeasurements());
    Assert.assertEquals(extendSchemaTemplatePlan.getTemplateExtendInfo().getTemplateName(), parsedTemplatePlan.getTemplateExtendInfo().getTemplateName());
    Assert.assertEquals(extendSchemaTemplatePlan.getTemplateExtendInfo().getDataTypes().get(0), parsedTemplatePlan.getTemplateExtendInfo().getDataTypes().get(0));
    Assert.assertEquals(extendSchemaTemplatePlan.getTemplateExtendInfo().getEncodings().get(0), parsedTemplatePlan.getTemplateExtendInfo().getEncodings().get(0));
    Assert.assertEquals(extendSchemaTemplatePlan.getTemplateExtendInfo().getCompressors().get(0), parsedTemplatePlan.getTemplateExtendInfo().getCompressors().get(0));
}

