@Test
public void testWorkerThreadStuck() throws InterruptedException {
    Semaphore latch1 = new Semaphore(2);
    latch1.acquire(2);
    StuckProcedure busyProc1 = new StuckProcedure(latch1);
    Semaphore latch2 = new Semaphore(2);
    latch2.acquire(2);
    StuckProcedure busyProc2 = new StuckProcedure(latch2);
    long busyProcId1 = procExecutor.submitProcedure(busyProc1);
    long busyProcId2 = procExecutor.submitProcedure(busyProc2);
    long otherProcId = procExecutor.submitProcedure(new NoopProcedure());
    // wait until a new worker is being created
    int threads1 = waitThreadCount(3);
    LOG.info("new threads got created: " + (threads1 - 2));
    Assert.assertEquals(3, threads1);
    ProcedureTestUtil.waitForProcedure(procExecutor, otherProcId);
    Assert.assertEquals(true, procExecutor.isFinished(otherProcId));
    Assert.assertEquals(true, procExecutor.isRunning());
    Assert.assertEquals(false, procExecutor.isFinished(busyProcId1));
    Assert.assertEquals(false, procExecutor.isFinished(busyProcId2));
    // terminate the busy procedures
    latch1.release();
    latch2.release();
    LOG.info("set keep alive and wait threads being removed");
    int threads2 = waitThreadCount(2);
    LOG.info("threads got removed: " + (threads1 - threads2));
    Assert.assertEquals(2, threads2);
    // terminate the busy procedures
    latch1.release();
    latch2.release();
    // wait for all procs to complete
    ProcedureTestUtil.waitForProcedure(procExecutor, busyProcId1);
    ProcedureTestUtil.waitForProcedure(procExecutor, busyProcId2);
}

/**
 * This test will fully start the ConfigManager, generating some files that cannot be cleaned up,
 * which will affect other tests. Therefore, this test is not enabled by default.
 */
@Ignore
@Test
public void test() throws IOException, ConsensusException, InterruptedException {
    // start configManager for the first time
    ConfigManager configManager = new ConfigManager();
    conf.setConfigNodeId(0);
    conf.setInternalAddress("127.0.0.1");
    configManager.initConsensusManager();
    // write some raft logs to increase index, otherwise cannot take snapshot
    configManager.getConsensusManager().write(new TestOnlyPlan());
    configManager.getConsensusManager().write(new TestOnlyPlan());
    configManager.getConsensusManager().write(new TestOnlyPlan());
    ProcedureInfo procedureInfo = configManager.getProcedureManager().getStore().getProcedureInfo();
    ConfigProcedureStore.createOldProcWalDir();
    // prepare procedures
    RemoveDataNodeProcedure removeDataNodeProcedure = new RemoveDataNodeProcedure(new TDataNodeLocation(10000, new TEndPoint("127.0.0.1", 6600), new TEndPoint("127.0.0.1", 7700), new TEndPoint("127.0.0.1", 8800), new TEndPoint("127.0.0.1", 9900), new TEndPoint("127.0.0.1", 11000)));
    removeDataNodeProcedure.setProcId(10086);
    AddConfigNodeProcedure addConfigNodeProcedure = new AddConfigNodeProcedure(new TConfigNodeLocation(0, new TEndPoint("0.0.0.0", 22277), new TEndPoint("0.0.0.0", 22278)), new TNodeVersionInfo());
    addConfigNodeProcedure.setProcId(888888);
    List<Procedure> procedureList = Arrays.asList(new NeverFinishProcedure(0), removeDataNodeProcedure, new NeverFinishProcedure(199), addConfigNodeProcedure, new NeverFinishProcedure(29999));
    procedureList.forEach(procedure -> procedureInfo.oldUpdateProcedure(new UpdateProcedurePlan(procedure)));
    // take snapshot manually
    procedureInfo.oldLoad();
    procedureInfo.upgrade();
    // check if wal files deleted
    Assert.assertFalse(procedureInfo.isOldVersion());
    // reactivate configManager to load snapshot
    configManager.close();
    configManager = new ConfigManager();
    configManager.initConsensusManager();
    // check procedures which loaded from snapshot
    List<Procedure<ConfigNodeProcedureEnv>> newProcedureList = configManager.getProcedureManager().getStore().getProcedureInfo().getProcedures();
    Assert.assertEquals(procedureList.size(), newProcedureList.size());
    Assert.assertTrue(newProcedureList.containsAll(procedureList));
}

@Test
public void testRestart() {
    IndexController controller = new IndexController(storageDir.getAbsolutePath(), peer, 0, CHECK_POINT_GAP);
    Assert.assertEquals(0, controller.getCurrentIndex());
    Assert.assertEquals(0, controller.getLastFlushedIndex());
    controller.update(CHECK_POINT_GAP - 1, false);
    Assert.assertEquals(CHECK_POINT_GAP - 1, controller.getCurrentIndex());
    Assert.assertEquals(0, controller.getLastFlushedIndex());
    controller = new IndexController(storageDir.getAbsolutePath(), peer, 0, CHECK_POINT_GAP);
    Assert.assertEquals(0, controller.getCurrentIndex());
    Assert.assertEquals(0, controller.getLastFlushedIndex());
    controller.update(CHECK_POINT_GAP - 1, true);
    Assert.assertEquals(CHECK_POINT_GAP - 1, controller.getCurrentIndex());
    Assert.assertEquals(CHECK_POINT_GAP - 1, controller.getLastFlushedIndex());
    controller = new IndexController(storageDir.getAbsolutePath(), peer, 0, CHECK_POINT_GAP);
    Assert.assertEquals(CHECK_POINT_GAP - 1, controller.getCurrentIndex());
    Assert.assertEquals(CHECK_POINT_GAP - 1, controller.getLastFlushedIndex());
    controller.update(CHECK_POINT_GAP * 2, false);
    Assert.assertEquals(CHECK_POINT_GAP * 2, controller.getCurrentIndex());
    Assert.assertEquals(CHECK_POINT_GAP * 2, controller.getLastFlushedIndex());
    controller = new IndexController(storageDir.getAbsolutePath(), peer, 0, CHECK_POINT_GAP);
    Assert.assertEquals(CHECK_POINT_GAP * 2, controller.getCurrentIndex());
    Assert.assertEquals(CHECK_POINT_GAP * 2, controller.getLastFlushedIndex());
    controller.update(CHECK_POINT_GAP * 2 - 1, true);
    Assert.assertEquals(CHECK_POINT_GAP * 2, controller.getCurrentIndex());
    Assert.assertEquals(CHECK_POINT_GAP * 2, controller.getLastFlushedIndex());
    controller.update(CHECK_POINT_GAP * 2 + 1, true);
    Assert.assertEquals(CHECK_POINT_GAP * 2 + 1, controller.getCurrentIndex());
    Assert.assertEquals(CHECK_POINT_GAP * 2 + 1, controller.getLastFlushedIndex());
}

