    SchemaFile sf = (SchemaFile) SchemaFile.initSchemaFile("root.test.vRoot1", TEST_SCHEMA_REGION_ID);
    IDatabaseMNode<ICachedMNode> newSGNode = nodeFactory.createDatabaseDeviceMNode(null, "newSG").getAsDatabaseMNode();
    sf.updateDatabaseNode(newSGNode);
    ICachedMNode root = virtualTriangleMTree(5, "root.test");
    Iterator<ICachedMNode> ite = getTreeBFT(root);
    ICachedMNode lastNode = null;
    while (ite.hasNext()) {
        ICachedMNode curNode = ite.next();
        if (!curNode.isMeasurement()) {
            ICachedMNodeContainer container = getCachedMNodeContainer(curNode);
            container.transferAllBufferReceivingToFlushing();
            sf.writeMNode(curNode);
            lastNode = curNode;
        }
    }
    long address = getSegAddrInContainer(lastNode);
    int corruptPageIndex = SchemaFile.getPageIndex(address);
    ISchemaPage corPage = ISchemaPage.initSegmentedPage(ByteBuffer.allocate(SchemaFileConfig.PAGE_LENGTH), corruptPageIndex);
    // record number of children now
    Iterator<ICachedMNode> res = sf.getChildren(lastNode);
    int cnt = 0;
    while (res.hasNext()) {
        cnt++;
        res.next();
    }
    try {
        Class schemaFileClass = SchemaFile.class;
        Field channelField = schemaFileClass.getDeclaredField("channel");
        channelField.setAccessible(true);
        FileChannel fileChannel = (FileChannel) channelField.get(sf);
        corPage.flushPageToChannel(fileChannel);
    } catch (NoSuchFieldException e) {
        throw new RuntimeException(e);
    } catch (IllegalAccessException e) {
        throw new RuntimeException(e);
    } finally {
        sf.close();
    }
    sf = (SchemaFile) SchemaFile.loadSchemaFile("root.test.vRoot1", TEST_SCHEMA_REGION_ID);
    try {
        sf.getChildren(lastNode);
        fail();
    } catch (Exception e) {
        Assert.assertEquals(String.format("Segment(index:0) not found in page(index:%d).", corruptPageIndex), e.getMessage());
    } finally {
        sf.close();
    }
    // modify log file to restore pbtree file
    FileOutputStream outputStream = null;
    FileChannel channel;
    try {
        String[] logFilePath = new String[] { "target", "tmp", "system", "schema", "root.test.vRoot1", "0", SchemaConstant.PBTREE_LOG_FILE_NAME };
        File logFile = new File(String.join(File.separator, logFilePath));
        outputStream = new FileOutputStream(logFile, true);
        channel = outputStream.getChannel();
        channel.truncate(channel.size() - 1);
    } finally {
        outputStream.close();
    }
    // verify that pbtree file has been repaired
    sf = (SchemaFile) SchemaFile.loadSchemaFile("root.test.vRoot1", TEST_SCHEMA_REGION_ID);
    res = sf.getChildren(lastNode);
    int cnt2 = 0;
    while (res.hasNext()) {
        res.next();
        cnt2++;
    }
    Assert.assertEquals(cnt, cnt2);
    sf.close();
    IoTDBDescriptor.getInstance().getConfig().setSchemaRegionConsensusProtocolClass(previousConsensus);
}

