@Test
public void testCreateAlignedTimeSeriesWithMerge() throws Exception {
    final ISchemaRegion schemaRegion = getSchemaRegion("root.sg", 0);
    final Map<String, String> oldTagMap = Collections.singletonMap("tagK", "tagV");
    final Map<String, String> oldAttrMap = Collections.singletonMap("attrK1", "attrV1");
    schemaRegion.createAlignedTimeSeries(SchemaRegionWritePlanFactory.getCreateAlignedTimeSeriesPlan(new PartialPath("root.sg.wf02.wt01"), Arrays.asList("temperature", "status"), Arrays.asList(TSDataType.valueOf("FLOAT"), TSDataType.valueOf("INT32")), Arrays.asList(TSEncoding.valueOf("RLE"), TSEncoding.valueOf("RLE")), Arrays.asList(CompressionType.SNAPPY, CompressionType.SNAPPY), null, Arrays.asList(Collections.emptyMap(), oldTagMap), Arrays.asList(Collections.emptyMap(), oldAttrMap)));
    final Map<String, String> newTagMap = Collections.singletonMap("tagK", "newTagV");
    final Map<String, String> newAttrMap = Collections.singletonMap("attrK2", "attrV2");
    ICreateAlignedTimeSeriesPlan mergePlan = SchemaRegionWritePlanFactory.getCreateAlignedTimeSeriesPlan(new PartialPath("root.sg.wf02.wt01"), // The lists must be mutable
    new ArrayList<>(Arrays.asList("status", "height")), new ArrayList<>(Arrays.asList(TSDataType.valueOf("INT32"), TSDataType.valueOf("INT64"))), new ArrayList<>(Arrays.asList(TSEncoding.valueOf("PLAIN"), TSEncoding.valueOf("PLAIN"))), new ArrayList<>(Arrays.asList(CompressionType.ZSTD, CompressionType.GZIP)), new ArrayList<>(Arrays.asList("alias2", null)), new ArrayList<>(Arrays.asList(newTagMap, oldTagMap)), new ArrayList<>(Arrays.asList(newAttrMap, oldAttrMap)));
    ((CreateAlignedTimeSeriesPlanImpl) mergePlan).setWithMerge(true);
    schemaRegion.createAlignedTimeSeries(mergePlan);
    // The encoding and compressor won't be changed
    // The alias/tags/attributes are updated
    final Map<String, String> resultAttrMap = new HashMap<>(oldAttrMap);
    resultAttrMap.putAll(newAttrMap);
    checkSingleTimeSeries(schemaRegion, new PartialPath("root.sg.wf02.wt01.status"), true, TSDataType.INT32, TSEncoding.RLE, CompressionType.SNAPPY, "alias2", newTagMap, resultAttrMap);
    checkSingleTimeSeries(schemaRegion, new PartialPath("root.sg.wf02.wt01.height"), true, TSDataType.INT64, TSEncoding.PLAIN, CompressionType.GZIP, null, oldTagMap, oldAttrMap);
    // Test illegal plan
    try {
        mergePlan = SchemaRegionWritePlanFactory.getCreateAlignedTimeSeriesPlan(new PartialPath("root.sg.wf02.wt01"), Collections.singletonList("temperature"), Collections.singletonList(TSDataType.valueOf("BOOLEAN")), Collections.singletonList(TSEncoding.valueOf("PLAIN")), Collections.singletonList(CompressionType.ZSTD), Collections.singletonList("alias2"), Collections.singletonList(newTagMap), Collections.singletonList(newAttrMap));
        ((CreateAlignedTimeSeriesPlanImpl) mergePlan).setWithMerge(true);
        schemaRegion.createAlignedTimeSeries(mergePlan);
        Assert.fail("Create aligned time series with merge shall fail if the types are different");
    } catch (final MeasurementAlreadyExistException e) {
        // Success
    }
}

