public void testCheckMeasurementExistence() throws Exception {
    final ISchemaRegion schemaRegion = getSchemaRegion("root.sg", 0);
    schemaRegion.createTimeSeries(SchemaRegionWritePlanFactory.getCreateTimeSeriesPlan(new PartialPath("root.sg.wf01.wt01.status"), TSDataType.BOOLEAN, TSEncoding.PLAIN, CompressionType.SNAPPY, null, null, null, null), -1);
    schemaRegion.createTimeSeries(SchemaRegionWritePlanFactory.getCreateTimeSeriesPlan(new PartialPath("root.sg.wf01.wt01.v1.s1"), TSDataType.BOOLEAN, TSEncoding.PLAIN, CompressionType.SNAPPY, null, null, null, null), -1);
    schemaRegion.createTimeSeries(SchemaRegionWritePlanFactory.getCreateTimeSeriesPlan(new PartialPath("root.sg.wf01.wt01.temperature"), TSDataType.FLOAT, TSEncoding.RLE, CompressionType.GZIP, null, new HashMap<String, String>() {

        {
            put("tag1", "t1");
            put("tag2", "t2");
        }
    }, new HashMap<String, String>() {

        {
            put("attr1", "a1");
            put("attr2", "a2");
        }
    }, "temp"), -1);
    // all non exist
    final Map<Integer, MetadataException> res1 = schemaRegion.checkMeasurementExistence(new PartialPath("root.sg.wf01.wt01"), IntStream.range(0, 5).mapToObj(i -> "s" + i).collect(Collectors.toList()), IntStream.range(0, 5).mapToObj(i -> "alias" + i).collect(Collectors.toList()));
    Assert.assertEquals(0, res1.size());
    final Map<Integer, MetadataException> res2 = schemaRegion.checkMeasurementExistence(new PartialPath("root.sg.wf01"), Collections.singletonList("wt01"), Collections.singletonList("alias1"));
    Assert.assertEquals(0, res2.size());
    // all exist
    final Map<Integer, MetadataException> res3 = schemaRegion.checkMeasurementExistence(new PartialPath("root.sg.wf01.wt01"), Arrays.asList("status", "s1", "v1"), Arrays.asList("", "temp", ""));
    Assert.assertEquals(3, res3.size());
    Assert.assertTrue(res3.get(0) instanceof MeasurementAlreadyExistException);
    Assert.assertTrue(res3.get(1) instanceof AliasAlreadyExistException);
    Assert.assertTrue(res3.get(2) instanceof PathAlreadyExistException);
}

@Test
public void testCreateTimeSeriesWithMerge() throws Exception {
    final ISchemaRegion schemaRegion = getSchemaRegion("root.sg", 0);
    final Map<String, String> oldTagMap = Collections.singletonMap("tagK", "tagV");
    final Map<String, String> oldAttrMap = Collections.singletonMap("attrK1", "attrV1");
    schemaRegion.createTimeSeries(SchemaRegionWritePlanFactory.getCreateTimeSeriesPlan(new PartialPath("root.sg.wf01.wt01.v1.s1"), TSDataType.BOOLEAN, TSEncoding.PLAIN, CompressionType.SNAPPY, null, oldTagMap, oldAttrMap, null), -1);
    final Map<String, String> newTagMap = Collections.singletonMap("tagK", "newTagV");
    final Map<String, String> newAttrMap = Collections.singletonMap("attrK2", "attrV2");
    ICreateTimeSeriesPlan mergePlan = SchemaRegionWritePlanFactory.getCreateTimeSeriesPlan(new PartialPath("root.sg.wf01.wt01.v1.s1"), TSDataType.BOOLEAN, TSEncoding.RLE, CompressionType.ZSTD, null, newTagMap, newAttrMap, "alias2");
    ((CreateTimeSeriesPlanImpl) mergePlan).setWithMerge(true);
    schemaRegion.createTimeSeries(mergePlan, -1);
    // The encoding and compressor won't be changed
    // The alias/tags/attributes are updated
    final Map<String, String> resultAttrMap = new HashMap<>(oldAttrMap);
    resultAttrMap.putAll(newAttrMap);
    checkSingleTimeSeries(schemaRegion, new PartialPath("root.sg.wf01.wt01.v1.s1"), false, TSDataType.BOOLEAN, TSEncoding.PLAIN, CompressionType.SNAPPY, "alias2", newTagMap, resultAttrMap);
    // Test illegal plan
    try {
        mergePlan = SchemaRegionWritePlanFactory.getCreateTimeSeriesPlan(new PartialPath("root.sg.wf01.wt01.v1.s1"), TSDataType.INT64, TSEncoding.PLAIN, CompressionType.ZSTD, null, oldTagMap, oldAttrMap, null);
        ((CreateTimeSeriesPlanImpl) mergePlan).setWithMerge(true);
        schemaRegion.createTimeSeries(mergePlan, -1);
        Assert.fail("Create time series with merge shall fail if the types are different");
    } catch (final MeasurementAlreadyExistException e) {
        // Success
    }
}

/**
 * Test {@link ISchemaRegion#constructSchemaBlackList}, {@link
 * ISchemaRegion#rollbackSchemaBlackList}, {@link ISchemaRegion#fetchSchemaBlackList} and{@link
 * ISchemaRegion#deleteTimeseriesInBlackList}
 */
@Test
public void testDeleteTimeSeries() throws Exception {
    final ISchemaRegion schemaRegion = getSchemaRegion("root.sg", 0);
    schemaRegion.createTimeSeries(SchemaRegionWritePlanFactory.getCreateTimeSeriesPlan(new PartialPath("root.sg.wf01.wt01.status"), TSDataType.BOOLEAN, TSEncoding.PLAIN, CompressionType.SNAPPY, null, null, null, null), -1);
    schemaRegion.createTimeSeries(SchemaRegionWritePlanFactory.getCreateTimeSeriesPlan(new PartialPath("root.sg.wf01.wt02.status"), TSDataType.BOOLEAN, TSEncoding.PLAIN, CompressionType.SNAPPY, null, null, null, null), -1);
    schemaRegion.createTimeSeries(SchemaRegionWritePlanFactory.getCreateTimeSeriesPlan(new PartialPath("root.sg.wf01.wt01.temperature"), TSDataType.FLOAT, TSEncoding.RLE, CompressionType.SNAPPY, null, null, null, null), -1);
    schemaRegion.createTimeSeries(SchemaRegionWritePlanFactory.getCreateTimeSeriesPlan(new PartialPath("root.sg.wf02.wt01.temperature"), TSDataType.FLOAT, TSEncoding.RLE, CompressionType.SNAPPY, null, null, null, null), -1);
    final PathPatternTree patternTree = new PathPatternTree();
    patternTree.appendPathPattern(new PartialPath("root.sg.wf01.wt01.*"));
    patternTree.appendPathPattern(new PartialPath("root.sg.wf01.*.status"));
    patternTree.appendPathPattern(new PartialPath("root.sg.wf02.wt01.temperature"));
    patternTree.constructTree();
    Assert.assertTrue(schemaRegion.constructSchemaBlackList(patternTree).getLeft() >= 4);
    Assert.assertEquals(new HashSet<>(Arrays.asList(new PartialPath("root.sg.wf01.wt01.*"), new PartialPath("root.sg.wf01.wt02.status"), new PartialPath("root.sg.wf01.wt01.status"), new PartialPath("root.sg.wf02.wt01.temperature"))), schemaRegion.fetchSchemaBlackList(patternTree));
    final PathPatternTree rollbackTree = new PathPatternTree();
    rollbackTree.appendPathPattern(new PartialPath("root.sg.wf02.wt01.temperature"));
    rollbackTree.constructTree();
    schemaRegion.rollbackSchemaBlackList(rollbackTree);
    Assert.assertEquals(new HashSet<>(Arrays.asList(new PartialPath("root.sg.wf01.wt01.*"), new PartialPath("root.sg.wf01.wt02.status"), new PartialPath("root.sg.wf01.wt01.status"))), schemaRegion.fetchSchemaBlackList(patternTree));
    schemaRegion.deleteTimeseriesInBlackList(patternTree);
    final List<MeasurementPath> schemas = schemaRegion.fetchSeriesSchema(ALL_MATCH_SCOPE, Collections.emptyMap(), false, false, true, false).searchMeasurementPaths(ALL_MATCH_PATTERN).left;
    Assert.assertEquals(1, schemas.size());
    Assert.assertEquals("root.sg.wf02.wt01.temperature", schemas.get(0).getFullPath());
}

@Test
public void testGetAllTimeSeriesCount() throws Exception {
    final ISchemaRegion schemaRegion = getSchemaRegion("root.laptop", 0);
    SchemaRegionTestUtil.createSimpleTimeSeriesByList(schemaRegion, Arrays.asList("root.laptop.d0", "root.laptop.d1.s1", "root.laptop.d1.s2.t1", "root.laptop.d1.s3", "root.laptop.d2.s1", "root.laptop.d2.s2"));
    // for Non prefix matched path
    Assert.assertEquals(6, getAllTimeSeriesCount(schemaRegion, new PartialPath("root.**"), null, false));
    Assert.assertEquals(6, getAllTimeSeriesCount(schemaRegion, new PartialPath("root.laptop.**"), null, false));
    Assert.assertEquals(1, getAllTimeSeriesCount(schemaRegion, new PartialPath("root.laptop.*"), null, false));
    Assert.assertEquals(4, getAllTimeSeriesCount(schemaRegion, new PartialPath("root.laptop.*.*"), null, false));
    Assert.assertEquals(5, getAllTimeSeriesCount(schemaRegion, new PartialPath("root.laptop.*.**"), null, false));
    Assert.assertEquals(1, getAllTimeSeriesCount(schemaRegion, new PartialPath("root.laptop.*.*.t1"), null, false));
    Assert.assertEquals(2, getAllTimeSeriesCount(schemaRegion, new PartialPath("root.laptop.*.s1"), null, false));
    Assert.assertEquals(3, getAllTimeSeriesCount(schemaRegion, new PartialPath("root.laptop.d1.**"), null, false));
    Assert.assertEquals(2, getAllTimeSeriesCount(schemaRegion, new PartialPath("root.laptop.d1.*"), null, false));
    Assert.assertEquals(1, getAllTimeSeriesCount(schemaRegion, new PartialPath("root.laptop.d2.s1"), null, false));
    Assert.assertEquals(2, getAllTimeSeriesCount(schemaRegion, new PartialPath("root.laptop.d2.**"), null, false));
    Assert.assertEquals(0, getAllTimeSeriesCount(schemaRegion, new PartialPath("root.laptop"), null, false));
    Assert.assertEquals(0, getAllTimeSeriesCount(schemaRegion, new PartialPath("root.laptop.d3.s1"), null, false));
    // for prefix matched path
    Assert.assertEquals(6, getAllTimeSeriesCount(schemaRegion, new PartialPath("root"), null, true));
    Assert.assertEquals(6, getAllTimeSeriesCount(schemaRegion, new PartialPath("root.laptop"), null, true));
    Assert.assertEquals(2, getAllTimeSeriesCount(schemaRegion, new PartialPath("root.laptop.d2"), null, true));
}

@Test
public void testGetMeasurementCountGroupByLevel() throws Exception {
    final ISchemaRegion schemaRegion = getSchemaRegion("root.laptop", 0);
    SchemaRegionTestUtil.createSimpleTimeSeriesByList(schemaRegion, Arrays.asList("root.laptop.d0", "root.laptop.d1.s1", "root.laptop.d1.s2.t1", "root.laptop.d1.s3", "root.laptop.d2.s1", "root.laptop.d2.s2"));
    final Map<PartialPath, Long> expected = new HashMap<>();
    expected.put(new PartialPath("root"), (long) 6);
    Assert.assertEquals(expected, getMeasurementCountGroupByLevel(schemaRegion, new PartialPath("root.**"), 0, false));
    expected.clear();
    expected.put(new PartialPath("root.laptop"), (long) 1);
    Assert.assertEquals(expected, getMeasurementCountGroupByLevel(schemaRegion, new PartialPath("root.laptop.*"), 1, false));
    expected.clear();
    expected.put(new PartialPath("root.laptop.d0"), (long) 1);
    Assert.assertEquals(expected, getMeasurementCountGroupByLevel(schemaRegion, new PartialPath("root.laptop.d0"), 2, false));
    expected.clear();
    expected.put(new PartialPath("root.laptop.d1"), (long) 2);
    Assert.assertEquals(expected, getMeasurementCountGroupByLevel(schemaRegion, new PartialPath("root.laptop.d1.*"), 2, false));
    expected.clear();
    expected.put(new PartialPath("root.laptop.d1"), (long) 3);
    Assert.assertEquals(expected, getMeasurementCountGroupByLevel(schemaRegion, new PartialPath("root.laptop.d1.**"), 2, false));
    expected.clear();
    expected.put(new PartialPath("root.laptop.d2"), (long) 2);
    Assert.assertEquals(expected, getMeasurementCountGroupByLevel(schemaRegion, new PartialPath("root.laptop.d2.*"), 2, false));
    expected.clear();
    expected.put(new PartialPath("root.laptop"), (long) 2);
    Assert.assertEquals(expected, getMeasurementCountGroupByLevel(schemaRegion, new PartialPath("root.laptop.*.s1"), 1, false));
    expected.clear();
    expected.put(new PartialPath("root.laptop.d1"), (long) 1);
    expected.put(new PartialPath("root.laptop.d2"), (long) 1);
    Assert.assertEquals(expected, getMeasurementCountGroupByLevel(schemaRegion, new PartialPath("root.laptop.*.s1"), 2, false));
    expected.clear();
    expected.put(new PartialPath("root.laptop"), (long) 1);
    Assert.assertEquals(expected, getMeasurementCountGroupByLevel(schemaRegion, new PartialPath("root.laptop.*.s2"), 1, false));
    expected.clear();
    expected.put(new PartialPath("root.laptop.d1"), (long) 2);
    expected.put(new PartialPath("root.laptop.d2"), (long) 2);
    Assert.assertEquals(expected, getMeasurementCountGroupByLevel(schemaRegion, new PartialPath("root.laptop.*.*"), 2, false));
    expected.clear();
    // for prefix matched path
    expected.put(new PartialPath("root"), (long) 6);
    Assert.assertEquals(expected, getMeasurementCountGroupByLevel(schemaRegion, new PartialPath("root"), 0, true));
    expected.clear();
    expected.put(new PartialPath("root.laptop.d1"), (long) 3);
    Assert.assertEquals(expected, getMeasurementCountGroupByLevel(schemaRegion, new PartialPath("root.laptop.d1"), 2, true));
    expected.clear();
}

