            // "d0" or "d1" node may remain in PartialMemory mode
            Assert.assertEquals("PBTree-PartialMemory", testParams.getTestModeName());
            final long d0ExistSize = size1 + nodeFactory.createMeasurementMNode(sg1.getAsDeviceMNode(), "d0", new MeasurementSchema("d0", TSDataType.INT64, TSEncoding.PLAIN, CompressionType.SNAPPY), null).estimateSize();
            final long d1ExistSize = size1 + nodeFactory.createInternalMNode(sg1.getAsMNode(), "d1").estimateSize();
            Assert.assertTrue(d0ExistSize == schemaRegion1.getSchemaRegionStatistics().getRegionMemoryUsage() || d1ExistSize == schemaRegion1.getSchemaRegionStatistics().getRegionMemoryUsage());
            ReleaseFlushMonitor.getInstance().forceFlushAndRelease();
            // wait release and flush task
            Thread.sleep(1000);
            Assert.assertEquals(size1, schemaRegion1.getSchemaRegionStatistics().getRegionMemoryUsage());
        }
        // schemaRegion2
        final IMNode<?> sg2 = nodeFactory.createDatabaseMNode(null, "sg2");
        sg2.setFullPath("root.sg2");
