        final IMNodeFactory nodeFactory = testParams.getSchemaEngineMode().equals("Memory") ? MNodeFactoryLoader.getInstance().getMemMNodeIMNodeFactory() : MNodeFactoryLoader.getInstance().getCachedMNodeIMNodeFactory();
        // schemaRegion1
        final IMNode<?> sg1 = nodeFactory.createDatabaseDeviceMNode(null, "sg1");
        sg1.setFullPath("root.sg1");
        long size1 = sg1.estimateSize();
        IMNode<?> tmp = nodeFactory.createMeasurementMNode(sg1.getAsDeviceMNode(), "d0", new MeasurementSchema("d0", TSDataType.INT64, TSEncoding.PLAIN, CompressionType.SNAPPY), null);
        size1 += tmp.estimateSize();
        tmp = nodeFactory.createInternalMNode(sg1.getAsMNode(), "d1");
        size1 += tmp.estimateSize();
        tmp = nodeFactory.createDeviceMNode(tmp, "s2");
        size1 += tmp.estimateSize();
        size1 += nodeFactory.createMeasurementMNode(tmp.getAsDeviceMNode(), "t1", new MeasurementSchema("t1", TSDataType.INT64, TSEncoding.PLAIN, CompressionType.SNAPPY), null).estimateSize();
        Assert.assertEquals(size1, schemaRegion1.getSchemaRegionStatistics().getRegionMemoryUsage());
        // schemaRegion2
        final IMNode<?> sg2 = nodeFactory.createDatabaseMNode(null, "sg2");
        sg2.setFullPath("root.sg2");
        long size2 = sg2.estimateSize();
        tmp = nodeFactory.createDeviceMNode(sg2, "d1");
        size2 += tmp.estimateSize();
        size2 += nodeFactory.createMeasurementMNode(tmp.getAsDeviceMNode(), "s3", new MeasurementSchema("s3", TSDataType.INT64, TSEncoding.PLAIN, CompressionType.SNAPPY), null).estimateSize();
        tmp = nodeFactory.createDeviceMNode(sg2, "d2");
