@Test
public void testPBTreeNodeStatistics() throws Exception {
    if (testParams.getSchemaEngineMode().equals("PBTree")) {
        final ISchemaRegion schemaRegion1 = getSchemaRegion("root.sg1", 0);
        final ISchemaRegion schemaRegion2 = getSchemaRegion("root.sg2", 1);
        final CachedSchemaEngineStatistics engineStatistics = SchemaEngine.getInstance().getSchemaEngineStatistics().getAsCachedSchemaEngineStatistics();
        SchemaRegionTestUtil.createSimpleTimeSeriesByList(schemaRegion1, Arrays.asList("root.sg1.d0", "root.sg1.d1.s1", "root.sg1.d1.s2.t1"));
        SchemaRegionTestUtil.createSimpleTimeSeriesByList(schemaRegion2, Arrays.asList("root.sg2.d1.s3", "root.sg2.d2.s1", "root.sg2.d2.s2"));
        final PathPatternTree patternTree = new PathPatternTree();
        patternTree.appendPathPattern(new PartialPath("root.**.s1"));
        patternTree.constructTree();
        Assert.assertTrue(schemaRegion1.constructSchemaBlackList(patternTree).getLeft() >= 1);
        Assert.assertTrue(schemaRegion2.constructSchemaBlackList(patternTree).getLeft() >= 1);
        schemaRegion1.deleteTimeseriesInBlackList(patternTree);
        schemaRegion2.deleteTimeseriesInBlackList(patternTree);
        Thread.sleep(1000);
        final CachedSchemaRegionStatistics cachedRegionStatistics1 = schemaRegion1.getSchemaRegionStatistics().getAsCachedSchemaRegionStatistics();
        final CachedSchemaRegionStatistics cachedRegionStatistics2 = schemaRegion2.getSchemaRegionStatistics().getAsCachedSchemaRegionStatistics();
        // check correctness of statistics
        if (testParams.getCachedMNodeSize() > 3) {
            Assert.assertEquals(1, cachedRegionStatistics1.getPinnedMNodeNum());
            Assert.assertEquals(4, cachedRegionStatistics1.getUnpinnedMNodeNum());
            Assert.assertEquals(1, cachedRegionStatistics2.getPinnedMNodeNum());
            Assert.assertEquals(4, cachedRegionStatistics2.getUnpinnedMNodeNum());
        } else {
            Assert.assertEquals(1, cachedRegionStatistics1.getPinnedMNodeNum());
            if (0 != cachedRegionStatistics1.getUnpinnedMNodeNum()) {
                // "d0" may remain in PartialMemory mode
                Assert.assertEquals("PBTree-PartialMemory", testParams.getTestModeName());
                ReleaseFlushMonitor.getInstance().forceFlushAndRelease();
                Thread.sleep(1000);
                Assert.assertEquals(0, cachedRegionStatistics1.getUnpinnedMNodeNum());
            }
            Assert.assertEquals(1, cachedRegionStatistics2.getPinnedMNodeNum());
            Assert.assertEquals(0, cachedRegionStatistics2.getUnpinnedMNodeNum());
        }
        // check consistence between region and engine
        Assert.assertEquals(cachedRegionStatistics1.getPinnedMNodeNum() + cachedRegionStatistics2.getPinnedMNodeNum(), engineStatistics.getPinnedMNodeNum());
        Assert.assertEquals(cachedRegionStatistics1.getUnpinnedMNodeNum() + cachedRegionStatistics2.getUnpinnedMNodeNum(), engineStatistics.getUnpinnedMNodeNum());
        Assert.assertEquals(cachedRegionStatistics1.getPinnedMemorySize() + cachedRegionStatistics2.getPinnedMemorySize(), engineStatistics.getPinnedMemorySize());
        Assert.assertEquals(cachedRegionStatistics1.getUnpinnedMemorySize() + cachedRegionStatistics2.getUnpinnedMemorySize(), engineStatistics.getUnpinnedMemorySize());
    }
}

@Test
public void testTemplateStatistics() throws Exception {
    ISchemaEngineStatistics engineStatistics = SchemaEngine.getInstance().getSchemaEngineStatistics();
    ISchemaRegion schemaRegion1 = getSchemaRegion("root.sg1", 0);
    ISchemaRegion schemaRegion2 = getSchemaRegion("root.sg2", 1);
    schemaRegion1.createTimeSeries(SchemaRegionWritePlanFactory.getCreateTimeSeriesPlan(new PartialPath("root.sg.wf01.wt01.status"), TSDataType.BOOLEAN, TSEncoding.PLAIN, CompressionType.SNAPPY, null, null, null, null), -1);
    Template template1 = new Template("t1", Arrays.asList("s1", "s2", "s3"), Arrays.asList(TSDataType.DOUBLE, TSDataType.INT32, TSDataType.BOOLEAN), Arrays.asList(TSEncoding.RLE, TSEncoding.RLE, TSEncoding.RLE), Arrays.asList(CompressionType.SNAPPY, CompressionType.SNAPPY, CompressionType.SNAPPY));
    template1.setId(1);
    Template template2 = new Template("t2", Arrays.asList("temperature", "status"), Arrays.asList(TSDataType.DOUBLE, TSDataType.INT32), Arrays.asList(TSEncoding.RLE, TSEncoding.RLE), Arrays.asList(CompressionType.SNAPPY, CompressionType.SNAPPY));
    template2.setId(2);
    ClusterTemplateManager.getInstance().putTemplate(template1);
    ClusterTemplateManager.getInstance().putTemplate(template2);
    for (int i = 0; i < 4; i++) {
        schemaRegion1.activateSchemaTemplate(SchemaRegionWritePlanFactory.getActivateTemplateInClusterPlan(new PartialPath("root.sg1.d" + i), 2, 1), template1);
        schemaRegion2.activateSchemaTemplate(SchemaRegionWritePlanFactory.getActivateTemplateInClusterPlan(new PartialPath("root.sg2.d" + i), 2, 1), template1);
    }
    schemaRegion2.activateSchemaTemplate(SchemaRegionWritePlanFactory.getActivateTemplateInClusterPlan(new PartialPath("root.sg2.wf01.wt02"), 3, 2), template2);
    // check template statistic
    Assert.assertEquals(26, engineStatistics.getTemplateSeriesNumber());
    Assert.assertEquals(27, engineStatistics.getTotalSeriesNumber());
    Assert.assertEquals(13, schemaRegion1.getSchemaRegionStatistics().getSeriesNumber(true));
    Assert.assertEquals(12, schemaRegion1.getSchemaRegionStatistics().getTemplateSeriesNumber());
    Assert.assertEquals(14, schemaRegion2.getSchemaRegionStatistics().getSeriesNumber(true));
    Assert.assertEquals(14, schemaRegion2.getSchemaRegionStatistics().getTemplateSeriesNumber());
    // deactivate template
    // construct schema blacklist with template on root.sg.wf01.wt01 and root.sg.wf02
    Map<PartialPath, List<Integer>> allDeviceTemplateMap = new HashMap<>();
    allDeviceTemplateMap.put(new PartialPath("root.**.d0"), Arrays.asList(1, 2));
    schemaRegion1.constructSchemaBlackListWithTemplate(SchemaRegionWritePlanFactory.getPreDeactivateTemplatePlan(allDeviceTemplateMap));
    schemaRegion2.constructSchemaBlackListWithTemplate(SchemaRegionWritePlanFactory.getPreDeactivateTemplatePlan(allDeviceTemplateMap));
    schemaRegion1.deactivateTemplateInBlackList(SchemaRegionWritePlanFactory.getDeactivateTemplatePlan(allDeviceTemplateMap));
    schemaRegion2.deactivateTemplateInBlackList(SchemaRegionWritePlanFactory.getDeactivateTemplatePlan(allDeviceTemplateMap));
    // check template statistic
    Assert.assertEquals(20, engineStatistics.getTemplateSeriesNumber());
    Assert.assertEquals(21, engineStatistics.getTotalSeriesNumber());
    Assert.assertEquals(10, schemaRegion1.getSchemaRegionStatistics().getSeriesNumber(true));
    Assert.assertEquals(9, schemaRegion1.getSchemaRegionStatistics().getTemplateSeriesNumber());
    Assert.assertEquals(11, schemaRegion2.getSchemaRegionStatistics().getSeriesNumber(true));
    Assert.assertEquals(11, schemaRegion2.getSchemaRegionStatistics().getTemplateSeriesNumber());
}

