@Test
public void testCachedMatcher() throws Exception {
    PipeRealtimeDataRegionExtractor dataRegionExtractor = new PipeRealtimeDataRegionFakeExtractor();
    dataRegionExtractor.customize(new PipeParameters(new HashMap<String, String>() {

        {
            put(PipeExtractorConstant.EXTRACTOR_PATTERN_KEY, "root");
        }
    }), new PipeTaskRuntimeConfiguration(new PipeTaskExtractorRuntimeEnvironment("1", 1, 1, null)));
    extractors.add(dataRegionExtractor);
    int deviceExtractorNum = 10;
    int seriesExtractorNum = 10;
    for (int i = 0; i < deviceExtractorNum; i++) {
        PipeRealtimeDataRegionExtractor deviceExtractor = new PipeRealtimeDataRegionFakeExtractor();
        int finalI1 = i;
        deviceExtractor.customize(new PipeParameters(new HashMap<String, String>() {

            {
                put(PipeExtractorConstant.EXTRACTOR_PATTERN_KEY, "root." + finalI1);
            }
        }), new PipeTaskRuntimeConfiguration(new PipeTaskExtractorRuntimeEnvironment("1", 1, 1, null)));
        extractors.add(deviceExtractor);
        for (int j = 0; j < seriesExtractorNum; j++) {
            PipeRealtimeDataRegionExtractor seriesExtractor = new PipeRealtimeDataRegionFakeExtractor();
            int finalI = i;
            int finalJ = j;
            seriesExtractor.customize(new PipeParameters(new HashMap<String, String>() {

                {
                    put(PipeExtractorConstant.EXTRACTOR_PATTERN_KEY, "root." + finalI + "." + finalJ);
                }
            }), new PipeTaskRuntimeConfiguration(new PipeTaskExtractorRuntimeEnvironment("1", 1, 1, null)));
            extractors.add(seriesExtractor);
        }
    }
    Future<?> future = executorService.submit(() -> extractors.forEach(extractor -> matcher.register(extractor)));
    int epochNum = 10000;
    int deviceNum = 1000;
    int seriesNum = 100;
    Map<String, String[]> deviceMap = IntStream.range(0, deviceNum).mapToObj(String::valueOf).collect(Collectors.toMap(s -> "root." + s, s -> new String[0]));
    String[] measurements = IntStream.range(0, seriesNum).mapToObj(String::valueOf).toArray(String[]::new);
    long totalTime = 0;
    for (int i = 0; i < epochNum; i++) {
        for (int j = 0; j < deviceNum; j++) {
            MockedPipeRealtimeEvent event = new MockedPipeRealtimeEvent(null, null, Collections.singletonMap("root." + i, measurements), null);
            long startTime = System.currentTimeMillis();
            matcher.match(event).forEach(extractor -> extractor.extract(event));
            totalTime += (System.currentTimeMillis() - startTime);
        }
        MockedPipeRealtimeEvent event = new MockedPipeRealtimeEvent(null, null, deviceMap, null);
        long startTime = System.currentTimeMillis();
        matcher.match(event).forEach(extractor -> extractor.extract(event));
        totalTime += (System.currentTimeMillis() - startTime);
    }
    System.out.println("matcher.getRegisterCount() = " + matcher.getRegisterCount());
    System.out.println("totalTime = " + totalTime);
    System.out.println("device match per second = " + ((double) (epochNum * (deviceNum + 1)) / (double) (totalTime) * 1000.0));
    future.get();
}

@Test
public void testIotdbPipePattern() {
    // Test legal and illegal pattern
    final String[] legalPatterns = { "root", "root.db", "root.db.d1.s", "root.db.`1`", "root.*.d.*s.s" };
    final String[] illegalPatterns = { "root.", "roo", "", "root..", "root./" };
    for (final String s : legalPatterns) {
        Assert.assertTrue(new IoTDBPipePattern(s).isLegal());
    }
    for (final String t : illegalPatterns) {
        try {
            Assert.assertFalse(new IoTDBPipePattern(t).isLegal());
        } catch (final Exception e) {
            Assert.assertTrue(e instanceof PipeException);
        }
    }
    // Test pattern cover db
    final String db = "root.db";
    final String[] patternsCoverDb = { "root.**", "root.db.**", "root.*db*.**" };
    final String[] patternsNotCoverDb = { "root.db", "root.*", "root.*.*", "root.db.*.**", "root.db.d1", "root.**.db.**" };
    for (final String s : patternsCoverDb) {
        Assert.assertTrue(new IoTDBPipePattern(s).coversDb(db));
    }
    for (final String t : patternsNotCoverDb) {
        Assert.assertFalse(new IoTDBPipePattern(t).coversDb(db));
    }
    final String device = "root.db.d1";
    // Test pattern cover device
    final String[] patternsCoverDevice = { "root.**", "root.db.**", "root.*.*.*", "root.db.d1.*", "root.*db*.*d*.*", "root.**.*1.*" };
    final String[] patternsNotCoverDevice = { "root.*", "root.*.*", "root.db.d1", "root.db.d2.*", "root.**.d2.**" };
    for (final String s : patternsCoverDevice) {
        Assert.assertTrue(new IoTDBPipePattern(s).coversDevice(device));
    }
    for (String t : patternsNotCoverDevice) {
        Assert.assertFalse(new IoTDBPipePattern(t).coversDevice(device));
    }
    // Test pattern may overlap with device
    final String[] patternsOverlapWithDevice = { "root.db.**", "root.db.d1", "root.db.d1.*", "root.db.d1.s1", "root.**.d2.**", "root.*.d*.**" };
    final String[] patternsNotOverlapWithDevice = { "root.db.d2.**", "root.db2.d1.**", "root.db.db.d1.**" };
    for (final String s : patternsOverlapWithDevice) {
        Assert.assertTrue(new IoTDBPipePattern(s).mayOverlapWithDevice(device));
    }
    for (final String t : patternsNotOverlapWithDevice) {
        Assert.assertFalse(new IoTDBPipePattern(t).mayOverlapWithDevice(device));
    }
    // Test pattern match measurement
    final String measurement = "s1";
    final String[] patternsMatchMeasurement = { "root.db.d1.s1", "root.db.d1.*" };
    final String[] patternsNotMatchMeasurement = { "root.db.d1", "root.db.d1", "root.db.d1.*.*" };
    for (final String s : patternsMatchMeasurement) {
        Assert.assertTrue(new IoTDBPipePattern(s).matchesMeasurement(device, measurement));
    }
    for (final String t : patternsNotMatchMeasurement) {
        Assert.assertFalse(new IoTDBPipePattern(t).matchesMeasurement(device, measurement));
    }
}

