@Test(timeout = 15000L)
public void concurrencyTest() {
    final String queryId = "q0";
    final long mockTsBlockSize = 1024L * 1024L;
    // Construct a mock LocalMemoryManager with capacity 5 * mockTsBlockSize per query.
    LocalMemoryManager mockLocalMemoryManager = Mockito.mock(LocalMemoryManager.class);
    MemoryPool spyMemoryPool = Mockito.spy(new MemoryPool("test", 10 * mockTsBlockSize, 5 * mockTsBlockSize));
    Mockito.when(mockLocalMemoryManager.getQueryPool()).thenReturn(spyMemoryPool);
    SharedTsBlockQueue queue = new SharedTsBlockQueue(new TFragmentInstanceId(queryId, 0, "0"), "test", mockLocalMemoryManager, newDirectExecutorService());
    queue.getCanAddTsBlock().set(null);
    queue.setMaxBytesCanReserve(Long.MAX_VALUE);
    ExecutorService executor = Executors.newFixedThreadPool(2);
    AtomicReference<Integer> numOfTimesSenderBlocked = new AtomicReference<>(0);
    AtomicReference<Integer> numOfTimesReceiverBlocked = new AtomicReference<>(0);
    AtomicReference<Integer> numOfTsBlocksToSend = new AtomicReference<>(1000);
    AtomicReference<Integer> numOfTsBlocksToReceive = new AtomicReference<>(1000);
    executor.submit(new SendTask(queue, mockTsBlockSize, numOfTsBlocksToSend, numOfTimesSenderBlocked, executor));
    executor.submit(new ReceiveTask(queue, numOfTsBlocksToReceive, numOfTimesReceiverBlocked, executor));
    while (numOfTsBlocksToSend.get() != 0 && numOfTsBlocksToReceive.get() != 0) {
        String message = String.format("Sender %d: %d, Receiver %d: %d", numOfTimesSenderBlocked.get(), numOfTsBlocksToSend.get(), numOfTimesReceiverBlocked.get(), numOfTsBlocksToReceive.get());
        System.out.println(message);
        try {
            Thread.sleep(10L);
        } catch (InterruptedException e) {
            Assert.fail(e.getMessage());
        }
    }
}

@Test
public void testAbort() {
    final String queryId = "q0";
    final long mockTsBlockSize = 1024L * 1024L;
    final TFragmentInstanceId remoteFragmentInstanceId = new TFragmentInstanceId(queryId, 0, "0");
    final String remotePlanNodeId = "exchange_0";
    final TFragmentInstanceId localFragmentInstanceId = new TFragmentInstanceId(queryId, 1, "0");
    // Construct a mock LocalMemoryManager with capacity 5 * mockTsBlockSize per read.
    LocalMemoryManager mockLocalMemoryManager = Mockito.mock(LocalMemoryManager.class);
    MemoryPool spyMemoryPool = Mockito.spy(new MemoryPool("test", 10 * mockTsBlockSize, 5 * mockTsBlockSize));
    Mockito.when(mockLocalMemoryManager.getQueryPool()).thenReturn(spyMemoryPool);
    // Construct a mock SinkListener.
    MPPDataExchangeManager.SinkListener mockSinkListener = Mockito.mock(MPPDataExchangeManager.SinkListener.class);
    // Construct a shared tsblock queue.
    SharedTsBlockQueue queue = new SharedTsBlockQueue(remoteFragmentInstanceId, remotePlanNodeId, mockLocalMemoryManager, newDirectExecutorService());
    // Construct SinkChannel.
    LocalSinkChannel localSinkChannel = new LocalSinkChannel(localFragmentInstanceId, queue, mockSinkListener);
    queue.setMaxBytesCanReserve(Long.MAX_VALUE);
    ShuffleSinkHandle shuffleSinkHandle = new ShuffleSinkHandle(remoteFragmentInstanceId, Collections.singletonList(localSinkChannel), new DownStreamChannelIndex(0), ShuffleSinkHandle.ShuffleStrategyEnum.SIMPLE_ROUND_ROBIN, mockSinkListener);
    // Construct SourceHandle
    LocalSourceHandle localSourceHandle = new LocalSourceHandle(localFragmentInstanceId, remotePlanNodeId, queue, Mockito.mock(MPPDataExchangeManager.SourceHandleListener.class));
    Assert.assertFalse(localSinkChannel.isFull().isDone());
    localSourceHandle.isBlocked();
    // blocked of LocalSinkChannel should be completed after calling isBlocked() of corresponding
    // LocalSourceHandle
    Assert.assertTrue(localSinkChannel.isFull().isDone());
    Assert.assertFalse(localSinkChannel.isFinished());
    Assert.assertFalse(localSinkChannel.isAborted());
    Assert.assertEquals(0L, localSinkChannel.getBufferRetainedSizeInBytes());
    // Send TsBlocks.
    int numOfSentTsblocks = 0;
    while (shuffleSinkHandle.isFull().isDone()) {
        shuffleSinkHandle.send(Utils.createMockTsBlock(mockTsBlockSize));
        numOfSentTsblocks += 1;
    }
    Assert.assertEquals(11, numOfSentTsblocks);
    ListenableFuture<?> blocked = localSinkChannel.isFull();
    Assert.assertFalse(blocked.isDone());
    Assert.assertFalse(localSinkChannel.isFinished());
    Assert.assertEquals(11 * mockTsBlockSize, localSinkChannel.getBufferRetainedSizeInBytes());
    Mockito.verify(spyMemoryPool, Mockito.times(11)).reserve(queryId, FragmentInstanceId.createFragmentInstanceIdFromTFragmentInstanceId(remoteFragmentInstanceId), remotePlanNodeId, mockTsBlockSize, Long.MAX_VALUE);
    // Abort.
    shuffleSinkHandle.abort();
    Assert.assertTrue(blocked.isDone());
    Assert.assertFalse(localSinkChannel.isFinished());
    Assert.assertTrue(localSinkChannel.isAborted());
    Mockito.verify(mockSinkListener, Mockito.times(1)).onAborted(localSinkChannel);
}

