@Test
public void testToFinished() {
    ExecutorService instanceNotificationExecutor = IoTDBThreadPoolFactory.newFixedThreadPool(1, "test-instance-notification");
    try {
        FragmentInstanceId instanceId = new FragmentInstanceId(new PlanFragmentId(MOCK_QUERY_ID, 0), "0");
        long time1 = System.currentTimeMillis();
        FragmentInstanceStateMachine stateMachine = new FragmentInstanceStateMachine(instanceId, instanceNotificationExecutor);
        long time2 = System.currentTimeMillis();
        assertEquals(FragmentInstanceState.RUNNING, stateMachine.getState());
        assertTrue(stateMachine.getCreatedTime() >= time1 && stateMachine.getCreatedTime() <= time2);
        assertEquals(instanceId, stateMachine.getFragmentInstanceId());
        ListenableFuture<FragmentInstanceState> future = stateMachine.getStateChange(FragmentInstanceState.RUNNING);
        stateMachine.transitionToFlushing();
        assertEquals(FragmentInstanceState.FLUSHING, stateMachine.getState());
        assertEquals(FragmentInstanceState.FLUSHING, future.get());
        stateMachine.addSourceTaskFailureListener(Mockito.mock(FragmentInstanceFailureListener.class));
        stateMachine.sourceTaskFailed(instanceId, new RuntimeException("Unknown"));
        stateMachine.finished();
        assertEquals(FragmentInstanceState.FINISHED, stateMachine.getState());
    } catch (ExecutionException | InterruptedException e) {
        e.printStackTrace();
        fail(e.getMessage());
    } finally {
        instanceNotificationExecutor.shutdown();
    }
}

