        SeriesScanOperator seriesScanOperator2 = new SeriesScanOperator(driverContext.getOperatorContexts().get(1), planNodeId2, measurementPath2, Ordering.ASC, SeriesScanOptions.getDefaultSeriesScanOptions(measurementPath2));
        seriesScanOperator2.initQueryDataSource(new QueryDataSource(seqResources, unSeqResources));
