        seriesScanOperator1.initQueryDataSource(new QueryDataSource(seqResources, unSeqResources));
        seriesScanOperator1.getOperatorContext().setMaxRunTime(new Duration(500, TimeUnit.MILLISECONDS));
        MeasurementPath measurementPath2 = new MeasurementPath(TIME_JOIN_OPERATOR_TEST_SG + ".device0.sensor1", TSDataType.INT32);
        SeriesScanOperator seriesScanOperator2 = new SeriesScanOperator(driverContext.getOperatorContexts().get(1), planNodeId2, measurementPath2, Ordering.ASC, scanOptionsBuilder.build());
        seriesScanOperator2.initQueryDataSource(new QueryDataSource(seqResources, unSeqResources));
        seriesScanOperator2.getOperatorContext().setMaxRunTime(new Duration(500, TimeUnit.MILLISECONDS));
        FullOuterTimeJoinOperator timeJoinOperator = new FullOuterTimeJoinOperator(driverContext.getOperatorContexts().get(2), Arrays.asList(seriesScanOperator1, seriesScanOperator2), Ordering.ASC, Arrays.asList(TSDataType.INT32, TSDataType.INT32), Arrays.asList(new SingleColumnMerger(new InputLocation(0, 0), new AscTimeComparator()), new SingleColumnMerger(new InputLocation(1, 0), new AscTimeComparator())), new AscTimeComparator());
        timeJoinOperator.getOperatorContext().setMaxRunTime(new Duration(500, TimeUnit.MILLISECONDS));
        LimitOperator limitOperator = new LimitOperator(driverContext.getOperatorContexts().get(3), 250, timeJoinOperator);
        int count = 0;
        while (limitOperator.isBlocked().isDone() && limitOperator.hasNext()) {
            TsBlock tsBlock = limitOperator.next();
            assertEquals(2, tsBlock.getValueColumnCount());
            assertTrue(tsBlock.getColumn(0) instanceof IntColumn);
            assertTrue(tsBlock.getColumn(1) instanceof IntColumn);
            for (int i = 0; i < tsBlock.getPositionCount(); i++, count++) {
                assertEquals(count, tsBlock.getTimeByIndex(i));
                if ((long) count < 200) {
                    assertEquals(20000 + (long) count, tsBlock.getColumn(0).getInt(i));
                    assertEquals(20000 + (long) count, tsBlock.getColumn(1).getInt(i));
                } else if ((long) count < 260 || ((long) count >= 300 && (long) count < 380) || (long) count >= 400) {
                    assertEquals(10000 + (long) count, tsBlock.getColumn(0).getInt(i));
                    assertEquals(10000 + (long) count, tsBlock.getColumn(1).getInt(i));
                } else {
                    assertEquals(count, tsBlock.getColumn(0).getInt(i));
                    assertEquals(count, tsBlock.getColumn(1).getInt(i));
                }
            }
        }
        assertEquals(250, count);
    } catch (IllegalPathException e) {
        e.printStackTrace();
        fail();
    } finally {
        instanceNotificationExecutor.shutdown();
    }
}

