@Test
public void testMonthIntervalMSFillFilter() {
    MonthIntervalMSFillFilter fillFilter1 = new MonthIntervalMSFillFilter(1, 0, ZoneId.systemDefault());
    MonthIntervalMSFillFilter fillFilter2 = new MonthIntervalMSFillFilter(1, 86_400_000, ZoneId.systemDefault());
    DateTimeFormatter formatter = DateTimeFormatter.ISO_LOCAL_DATE_TIME;
    LocalDateTime localDateTime = LocalDateTime.parse("2023-02-01T11:47:30", formatter);
    ZoneOffset zoneOffset = ZoneId.systemDefault().getRules().getOffset(localDateTime);
    Instant instant = localDateTime.toInstant(zoneOffset);
    long previousTime = instant.toEpochMilli();
    assertTrue(fillFilter1.needFill(localDateTime.plusMonths(1).toInstant(zoneOffset).toEpochMilli(), previousTime));
    assertFalse(fillFilter1.needFill(localDateTime.plusMonths(1).toInstant(zoneOffset).toEpochMilli() + 1, previousTime));
    assertTrue(fillFilter2.needFill(localDateTime.plusMonths(1).toInstant(zoneOffset).toEpochMilli() + 1, previousTime));
    assertTrue(fillFilter2.needFill(localDateTime.plusMonths(1).plusDays(1).toInstant(zoneOffset).toEpochMilli(), previousTime));
    assertFalse(fillFilter2.needFill(localDateTime.plusMonths(1).plusDays(1).toInstant(zoneOffset).toEpochMilli() + 1, previousTime));
}

@Test
public void testMonthIntervalUSFillFilter() {
    MonthIntervalUSFillFilter fillFilter1 = new MonthIntervalUSFillFilter(1, 0, ZoneId.systemDefault());
    MonthIntervalUSFillFilter fillFilter2 = new MonthIntervalUSFillFilter(1, 86_400_000_000L, ZoneId.systemDefault());
    DateTimeFormatter formatter = DateTimeFormatter.ISO_LOCAL_DATE_TIME;
    LocalDateTime localDateTime = LocalDateTime.parse("2023-02-01T11:47:30", formatter);
    ZoneOffset zoneOffset = ZoneId.systemDefault().getRules().getOffset(localDateTime);
    Instant instant = localDateTime.toInstant(zoneOffset);
    long previousTime = instant.getEpochSecond() * 1_000_000L + instant.getLong(ChronoField.MICRO_OF_SECOND);
    Instant current = localDateTime.plusMonths(1).toInstant(zoneOffset);
    assertTrue(fillFilter1.needFill(current.getEpochSecond() * 1_000_000 + current.getLong(ChronoField.MICRO_OF_SECOND), previousTime));
    assertFalse(fillFilter1.needFill(current.getEpochSecond() * 1_000_000 + current.getLong(ChronoField.MICRO_OF_SECOND) + 1, previousTime));
    assertTrue(fillFilter2.needFill(current.getEpochSecond() * 1_000_000 + current.getLong(ChronoField.MICRO_OF_SECOND) + 1, previousTime));
    current = localDateTime.plusMonths(1).plusDays(1).toInstant(zoneOffset);
    assertTrue(fillFilter2.needFill(current.getEpochSecond() * 1_000_000 + current.getLong(ChronoField.MICRO_OF_SECOND), previousTime));
    assertFalse(fillFilter2.needFill(current.getEpochSecond() * 1_000_000 + current.getLong(ChronoField.MICRO_OF_SECOND) + 1, previousTime));
}

