@Test
public void testStorageGroupCache() {
    Map<String, List<String>> storageGroupToDeviceMap;
    Map<String, String> deviceToStorageGroupMap;
    // test devices in one database
    List<List<String>> existedDevicesInOneStorageGroup = Arrays.asList(Arrays.asList("root.sg1.d1", "root.sg1.d2"), Arrays.asList("root.sg2.d1", "root.sg2.d2"));
    for (List<String> searchDevices : existedDevicesInOneStorageGroup) {
        storageGroupToDeviceMap = partitionCache.getStorageGroupToDevice(searchDevices, false, false, AuthorityChecker.SUPER_USER);
        assertEquals(1, storageGroupToDeviceMap.size());
        for (List<String> devices : storageGroupToDeviceMap.values()) {
            assertEquals(2, devices.size());
        }
        deviceToStorageGroupMap = partitionCache.getDeviceToStorageGroup(searchDevices, false, false, AuthorityChecker.SUPER_USER);
        assertEquals(2, deviceToStorageGroupMap.size());
    }
    // test devices in two database
    List<List<String>> existedDevicesInMultiStorageGroup = Arrays.asList(Arrays.asList("root.sg1.d1", "root.sg2.d2"), Arrays.asList("root.sg1.d1", "root.sg2.d2"));
    for (List<String> searchDevices : existedDevicesInMultiStorageGroup) {
        storageGroupToDeviceMap = partitionCache.getStorageGroupToDevice(searchDevices, false, false, AuthorityChecker.SUPER_USER);
        assertEquals(2, storageGroupToDeviceMap.size());
        for (List<String> devices : storageGroupToDeviceMap.values()) {
            assertEquals(1, devices.size());
        }
        deviceToStorageGroupMap = partitionCache.getDeviceToStorageGroup(searchDevices, false, false, AuthorityChecker.SUPER_USER);
        assertEquals(2, deviceToStorageGroupMap.size());
    }
    // test missed devices in storageGroupCache
    List<List<String>> nonExistedDevices = Arrays.asList(Arrays.asList("root.sg5.d1", "root.sg5.d2"), Arrays.asList("root.sg.d1", "root.sg.d2"), Arrays.asList("root.sg3.**", "root.sg4.**"));
    for (List<String> searchDevices : nonExistedDevices) {
        storageGroupToDeviceMap = partitionCache.getStorageGroupToDevice(searchDevices, false, false, AuthorityChecker.SUPER_USER);
        assertEquals(0, storageGroupToDeviceMap.size());
        deviceToStorageGroupMap = partitionCache.getDeviceToStorageGroup(searchDevices, false, false, AuthorityChecker.SUPER_USER);
        assertEquals(0, deviceToStorageGroupMap.size());
    }
    // test invalid all cache
    partitionCache.invalidAllCache();
    List<String> oneDeviceList = Collections.singletonList("root.sg1.d1");
    storageGroupToDeviceMap = partitionCache.getStorageGroupToDevice(oneDeviceList, false, false, AuthorityChecker.SUPER_USER);
    assertEquals(0, storageGroupToDeviceMap.size());
    deviceToStorageGroupMap = partitionCache.getDeviceToStorageGroup(oneDeviceList, false, false, AuthorityChecker.SUPER_USER);
    assertEquals(0, deviceToStorageGroupMap.size());
}

