    checkPushDown("select __endTime, count(s1) from root.sg.d1 group by ([0, 100), 10ms, 5ms) fill(previous);", new TestPlanBuilder().aggregationScan("5", schemaMap.get("root.sg.d1.s1"), aggregationDescriptorList1, groupByTimeParameter, false).slidingWindow("2", aggregationDescriptorList2, groupByTimeParameter, false).columnInject("3", groupByTimeParameter).fill("4", FillPolicy.PREVIOUS).getRoot(), new TestPlanBuilder().aggregationScan("5", schemaMap.get("root.sg.d1.s1"), aggregationDescriptorList1, groupByTimeParameter, false).slidingWindow("2", aggregationDescriptorList2, groupByTimeParameter, true).fill("4", FillPolicy.PREVIOUS).getRoot());
}

