@Test
public void testCannotPushDown() {
    checkCannotPushDown("select s1, s2 from root.sg.d1 limit 100;", new TestPlanBuilder().fullOuterTimeJoin(Arrays.asList(schemaMap.get("root.sg.d1.s1"), schemaMap.get("root.sg.d1.s2"))).limit("3", 100).getRoot());
    checkCannotPushDown("select diff(s1 + 1) + 1 from root.sg.d1 limit 100 offset 100;", new TestPlanBuilder().scan("0", schemaMap.get("root.sg.d1.s1")).transform("1", Collections.singletonList(add(function("diff", add(timeSeries(schemaMap.get("root.sg.d1.s1")), intValue("1"))), intValue("1")))).offset("2", 100).limit("3", 100).getRoot());
    LinkedHashMap<String, String> functionAttributes = new LinkedHashMap<>();
    functionAttributes.put("windowSize", "10");
    checkCannotPushDown("select m4(s1,'windowSize'='10') from root.sg.d1 limit 100 offset 100;", new TestPlanBuilder().scan("0", schemaMap.get("root.sg.d1.s1")).transform("1", Collections.singletonList(function("m4", functionAttributes, timeSeries(schemaMap.get("root.sg.d1.s1"))))).offset("2", 100).limit("3", 100).getRoot());
    checkCannotPushDown("select s1 from root.sg.d1 fill(linear) limit 100;", new TestPlanBuilder().scan("0", schemaMap.get("root.sg.d1.s1")).fill("1", FillPolicy.LINEAR).limit("2", 100).getRoot());
    checkCannotPushDown("select s1 from root.sg.d1 fill(previous) limit 100;", new TestPlanBuilder().scan("0", schemaMap.get("root.sg.d1.s1")).fill("1", FillPolicy.PREVIOUS).limit("2", 100).getRoot());
    checkCannotPushDown("select s1 from root.sg.d1 where s1 > 10 limit 100 offset 100;", new TestPlanBuilder().scan("0", schemaMap.get("root.sg.d1.s1")).filter("1", Collections.singletonList(timeSeries(schemaMap.get("root.sg.d1.s1"))), gt(timeSeries(schemaMap.get("root.sg.d1.s1")), intValue("10")), false).offset("2", 100).limit("3", 100).getRoot());
}

