    String sql = "SELECT count(s1), max_value(s2), last_value(s1) FROM root.sg.* WHERE time > 100 and s2 > 10 " + "ORDER BY DEVICE,TIME DESC LIMIT 100 OFFSET 100 ALIGN BY DEVICE";
    QueryId queryId = new QueryId("test");
    // fake initResultNodeContext()
    queryId.genPlanNodeId();
    List<PlanNode> sourceNodeList1 = new ArrayList<>();
    sourceNodeList1.add(new SeriesScanNode(queryId.genPlanNodeId(), (MeasurementPath) schemaMap.get("root.sg.d1.s1"), Ordering.DESC));
    sourceNodeList1.add(new SeriesScanNode(queryId.genPlanNodeId(), (MeasurementPath) schemaMap.get("root.sg.d1.s2"), Ordering.DESC));
    FullOuterTimeJoinNode fullOuterTimeJoinNode1 = new FullOuterTimeJoinNode(queryId.genPlanNodeId(), Ordering.DESC, sourceNodeList1);
    GreaterThanExpression predicate1 = new GreaterThanExpression(new TimeSeriesOperand(schemaMap.get("root.sg.d1.s2")), new ConstantOperand(TSDataType.INT64, "10"));
    FilterNode filterNode1 = new FilterNode(queryId.genPlanNodeId(), fullOuterTimeJoinNode1, new Expression[] { new TimeSeriesOperand(schemaMap.get("root.sg.d1.s1")), new TimeSeriesOperand(schemaMap.get("root.sg.d1.s2")) }, predicate1, false, Ordering.DESC, true);
    RawDataAggregationNode aggregationNode1 = new RawDataAggregationNode(queryId.genPlanNodeId(), filterNode1, Arrays.asList(new AggregationDescriptor(TAggregationType.COUNT.name().toLowerCase(), AggregationStep.SINGLE, Collections.singletonList(new TimeSeriesOperand(schemaMap.get("root.sg.d1.s1")))), new AggregationDescriptor(TAggregationType.MAX_VALUE.name().toLowerCase(), AggregationStep.SINGLE, Collections.singletonList(new TimeSeriesOperand(schemaMap.get("root.sg.d1.s2")))), new AggregationDescriptor(TAggregationType.LAST_VALUE.name().toLowerCase(), AggregationStep.SINGLE, Collections.singletonList(new TimeSeriesOperand(schemaMap.get("root.sg.d1.s1"))))), null, Ordering.DESC);
    List<PlanNode> sourceNodeList2 = new ArrayList<>();
    sourceNodeList2.add(new SeriesScanNode(queryId.genPlanNodeId(), (MeasurementPath) schemaMap.get("root.sg.d2.s1"), Ordering.DESC));
    sourceNodeList2.add(new SeriesScanNode(queryId.genPlanNodeId(), (MeasurementPath) schemaMap.get("root.sg.d2.s2"), Ordering.DESC));
    FullOuterTimeJoinNode fullOuterTimeJoinNode2 = new FullOuterTimeJoinNode(queryId.genPlanNodeId(), Ordering.DESC, sourceNodeList2);
    GreaterThanExpression predicate2 = new GreaterThanExpression(new TimeSeriesOperand(schemaMap.get("root.sg.d2.s2")), new ConstantOperand(TSDataType.INT32, "10"));
    FilterNode filterNode2 = new FilterNode(queryId.genPlanNodeId(), fullOuterTimeJoinNode2, new Expression[] { new TimeSeriesOperand(schemaMap.get("root.sg.d2.s1")), new TimeSeriesOperand(schemaMap.get("root.sg.d2.s2")) }, predicate2, false, Ordering.DESC, true);
    RawDataAggregationNode aggregationNode2 = new RawDataAggregationNode(queryId.genPlanNodeId(), filterNode2, Arrays.asList(new AggregationDescriptor(TAggregationType.COUNT.name().toLowerCase(), AggregationStep.SINGLE, Collections.singletonList(new TimeSeriesOperand(schemaMap.get("root.sg.d2.s1")))), new AggregationDescriptor(TAggregationType.MAX_VALUE.name().toLowerCase(), AggregationStep.SINGLE, Collections.singletonList(new TimeSeriesOperand(schemaMap.get("root.sg.d2.s2")))), new AggregationDescriptor(TAggregationType.LAST_VALUE.name().toLowerCase(), AggregationStep.SINGLE, Collections.singletonList(new TimeSeriesOperand(schemaMap.get("root.sg.d2.s1"))))), null, Ordering.DESC);
    Map<String, List<Integer>> deviceToMeasurementIndexesMap = new HashMap<>();
    deviceToMeasurementIndexesMap.put("root.sg.d1", Arrays.asList(1, 2, 3));
    deviceToMeasurementIndexesMap.put("root.sg.d2", Arrays.asList(1, 2, 3));
    DeviceViewNode deviceViewNode = new DeviceViewNode(queryId.genPlanNodeId(), new OrderByParameter(Arrays.asList(new SortItem(OrderByKey.DEVICE, Ordering.ASC), new SortItem(OrderByKey.TIME, Ordering.DESC))), Arrays.asList(ColumnHeaderConstant.DEVICE, "count(s1)", "max_value(s2)", "last_value(s1)"), deviceToMeasurementIndexesMap);
    deviceViewNode.addChildDeviceNode("root.sg.d1", aggregationNode1);
    deviceViewNode.addChildDeviceNode("root.sg.d2", aggregationNode2);
    OffsetNode offsetNode = new OffsetNode(queryId.genPlanNodeId(), deviceViewNode, 100);
    LimitNode limitNode = new LimitNode(queryId.genPlanNodeId(), offsetNode, 100);
    PlanNode actualPlan = parseSQLToPlanNode(sql);
    Assert.assertEquals(actualPlan, limitNode);
}

