        assertEquals(root.calculateMaxPeekMemoryWithCounter() + rootPipelineMemoryEstimator.getChildren().stream().map(PipelineMemoryEstimator::calculateEstimatedRunningMemorySize).reduce(0L, Long::sum), rootPipelineMemoryEstimator.calculateEstimatedRunningMemorySize());
        List<PipelineMemoryEstimator> childrenPipelineMemoryEstimators = rootPipelineMemoryEstimator.getChildren();
        assertEquals(1, childrenPipelineMemoryEstimators.size());
        for (int i = 0; i < 1; i++) {
            assertEquals(ConsumeAllChildrenPipelineMemoryEstimator.class, childrenPipelineMemoryEstimators.get(i).getClass());
