        assertEquals(SystemInfo.getInstance().getFlushThershold(), cacheHitRatioMonitor.getFlushThershold(), delta);
        assertEquals(SystemInfo.getInstance().getRejectThershold(), cacheHitRatioMonitor.getRejectThershold(), delta);
        assertEquals(FlushManager.getInstance().getNumberOfWorkingTasks(), cacheHitRatioMonitor.flushingMemTableNum());
        assertEquals(MemTableManager.getInstance().getCurrentMemtableNumber(), cacheHitRatioMonitor.totalMemTableNum());
    } catch (StartupException e) {
        e.printStackTrace();
        fail(e.getMessage());
    } finally {
        cacheHitRatioMonitor.stop();
    }
}

