        taskResource = selector.selectOneInsertionTask(new CrossSpaceCompactionCandidate(tsFileManager.getTsFileList(true), tsFileManager.getTsFileList(false)));
        Assert.assertTrue(taskResource.isValid());
        Assert.assertEquals(tsFileManager.getTsFileList(false).get(0), taskResource.firstUnSeqFileInParitition);
        Assert.assertEquals(tsFileManager.getTsFileList(false).get(0), taskResource.toInsertUnSeqFile);
        Assert.assertEquals(null, taskResource.nextSeqFile);
        if (i == 1) {
            Assert.assertEquals(null, taskResource.prevSeqFile);
        } else if (i == 2) {
            Assert.assertEquals(tsFileManager.getTsFileList(true).get(0), taskResource.prevSeqFile);
        } else {
            Assert.assertEquals(tsFileManager.getTsFileList(true).get(1), taskResource.prevSeqFile);
        }
        InsertionCrossSpaceCompactionTask task = new InsertionCrossSpaceCompactionTask(new Phaser(1), 0, tsFileManager, taskResource, tsFileManager.getNextCompactionTaskId());
        task.start();
        i++;
    }
    Assert.assertEquals(3, tsFileManager.getTsFileList(true).size());
    Assert.assertEquals(0, tsFileManager.getTsFileList(false).size());
}

