@Test
public void testDeleteInSelection() throws Exception {
    RewriteCrossSpaceCompactionSelector selector = new RewriteCrossSpaceCompactionSelector("", "", 0, null);
    AtomicBoolean fail = new AtomicBoolean(false);
    Thread thread1 = new Thread(() -> {
        try {
            Thread.sleep(1000);
            List<CrossCompactionTaskResource> selected = selector.selectCrossSpaceTask(seqResources, unseqResources);
        } catch (Exception e) {
            logger.error("Exception occurs", e);
            fail.set(true);
        }
