    Thread thread2 = new Thread(() -> {
        if (!seqResources.get(0).remove()) {
            fail.set(true);
        }
        if (!unseqResources.get(0).remove()) {
            fail.set(true);
        }
    });
    thread1.start();
    thread2.start();
    thread1.join();
    thread2.join();
    if (fail.get()) {
        Assert.fail();
    }
}

