            tsFileIOWriter.endChunkGroup();
            resource.updateStartTime(new PlainDeviceID(COMPACTION_TEST_SG + PATH_SEPARATOR + "d" + deviceIndex), 500);
            resource.updateEndTime(new PlainDeviceID(COMPACTION_TEST_SG + PATH_SEPARATOR + "d" + deviceIndex), 2300);
            timeserisPathList.addAll(timeseriesPath);
            tsDataTypes.addAll(dataTypes);
        }
        tsFileIOWriter.endFile();
    }
    resource.serialize();
    unseqResources.add(resource);
    // start compacting
    tsFileManager.addAll(seqResources, true);
    tsFileManager.addAll(unseqResources, false);
    Map<PartialPath, List<TimeValuePair>> sourceDatas = readSourceFiles(createTimeseries(maxDeviceNum, maxMeasurementNum, true), tsDataTypes);
    CrossSpaceCompactionTask task = new CrossSpaceCompactionTask(0, tsFileManager, seqResources, unseqResources, new FastCompactionPerformer(true), 0, 0);
    Assert.assertTrue(task.start());
    validateSeqFiles(true);
    validateTargetDatas(sourceDatas, tsDataTypes);
    InnerSpaceCompactionTask innerTask = new InnerSpaceCompactionTask(0, tsFileManager, tsFileManager.getTsFileList(true), true, new FastCompactionPerformer(false), 0);
    Assert.assertTrue(innerTask.start());
    validateSeqFiles(true);
    validateTargetDatas(sourceDatas, tsDataTypes);
}

