    TSFileDescriptor.getInstance().getConfig().setMaxNumberOfPointsInPage(30);
    registerTimeseriesInMManger(4, 5, false);
    createFiles(2, 2, 3, 300, 0, 0, 50, 50, false, true);
    createFiles(2, 4, 5, 300, 700, 700, 50, 50, false, true);
    createFiles(3, 3, 4, 200, 20, 10020, 30, 30, false, false);
    createFiles(2, 1, 5, 100, 450, 20450, 0, 0, false, false);
    // generate mods file
    List<String> seriesPaths = new ArrayList<>();
    for (int i = 0; i < 5; i++) {
        seriesPaths.add(COMPACTION_TEST_SG + PATH_SEPARATOR + "d0" + PATH_SEPARATOR + "s" + i);
        seriesPaths.add(COMPACTION_TEST_SG + PATH_SEPARATOR + "d1" + PATH_SEPARATOR + "s" + i);
        seriesPaths.add(COMPACTION_TEST_SG + PATH_SEPARATOR + "d2" + PATH_SEPARATOR + "s" + i);
    }
    generateModsFile(seriesPaths, seqResources, Long.MIN_VALUE, Long.MAX_VALUE);
    for (int i = 0; i < 4; i++) {
        for (int j = 0; j < 5; j++) {
            PartialPath path = new MeasurementPath(COMPACTION_TEST_SG + PATH_SEPARATOR + "d" + i, "s" + j, new MeasurementSchema("s" + j, TSDataType.INT64));
            IDataBlockReader tsBlockReader = new SeriesDataBlockReader(path, FragmentInstanceContext.createFragmentInstanceContextForCompaction(EnvironmentUtils.TEST_QUERY_CONTEXT.getQueryId()), seqResources, unseqResources, true);
            int count = 0;
            while (tsBlockReader.hasNextBatch()) {
                TsBlock block = tsBlockReader.nextBatch();
                IBatchDataIterator iterator = block.getTsBlockSingleColumnIterator();
                while (iterator.hasNext()) {
                    if (i == 0 && ((450 <= iterator.currentTime() && iterator.currentTime() < 550) || (550 <= iterator.currentTime() && iterator.currentTime() < 650))) {
                        assertEquals(iterator.currentTime() + 20000, iterator.currentValue());
                    } else if ((i < 3 && j < 4) && ((20 <= iterator.currentTime() && iterator.currentTime() < 220) || (250 <= iterator.currentTime() && iterator.currentTime() < 450) || (480 <= iterator.currentTime() && iterator.currentTime() < 680))) {
                        assertEquals(iterator.currentTime() + 10000, iterator.currentValue());
                    } else {
                        assertEquals(iterator.currentTime(), iterator.currentValue());
                    }
                    count++;
                    iterator.next();
                }
            }
            tsBlockReader.close();
            if (i < 1) {
                if (j < 4) {
                    assertEquals(630, count);
                } else {
                    assertEquals(200, count);
                }
            } else if (i < 3) {
                if (j < 4) {
                    assertEquals(600, count);
                } else {
                    assertEquals(0, count);
                }
            } else {
                assertEquals(600, count);
            }
        }
    }
    targetResources.addAll(CompactionFileGeneratorUtils.getCrossCompactionTargetTsFileResources(seqResources));
    FileReaderManager.getInstance().closeAndRemoveAllOpenedReaders();
    ICompactionPerformer performer = new FastCompactionPerformer(seqResources, unseqResources, targetResources);
    performer.setSummary(new FastCompactionTaskSummary());
    performer.perform();
    Assert.assertEquals(0, FileReaderManager.getInstance().getClosedFileReaderMap().size());
    Assert.assertEquals(0, FileReaderManager.getInstance().getUnclosedFileReaderMap().size());
    CompactionUtils.moveTargetFile(targetResources, CompactionTaskType.CROSS, COMPACTION_TEST_SG);
    Assert.assertEquals(4, targetResources.size());
    List<IDeviceID> deviceIdList = new ArrayList<>();
    deviceIdList.add(new PlainDeviceID(COMPACTION_TEST_SG + PATH_SEPARATOR + "d0"));
    deviceIdList.add(new PlainDeviceID(COMPACTION_TEST_SG + PATH_SEPARATOR + "d1"));
    for (int i = 0; i < 2; i++) {
        Assert.assertTrue(targetResources.get(i).isDeviceIdExist(new PlainDeviceID(COMPACTION_TEST_SG + PATH_SEPARATOR + "d0")));
        Assert.assertTrue(targetResources.get(i).isDeviceIdExist(new PlainDeviceID(COMPACTION_TEST_SG + PATH_SEPARATOR + "d1")));
        Assert.assertFalse(targetResources.get(i).isDeviceIdExist(new PlainDeviceID(COMPACTION_TEST_SG + PATH_SEPARATOR + "d2")));
        Assert.assertFalse(targetResources.get(i).isDeviceIdExist(new PlainDeviceID(COMPACTION_TEST_SG + PATH_SEPARATOR + "d3")));
        check(targetResources.get(i), deviceIdList);
    }
    deviceIdList.add(new PlainDeviceID(COMPACTION_TEST_SG + PATH_SEPARATOR + "d2"));
    deviceIdList.add(new PlainDeviceID(COMPACTION_TEST_SG + PATH_SEPARATOR + "d3"));
    for (int i = 2; i < 3; i++) {
        Assert.assertTrue(targetResources.get(i).isDeviceIdExist(new PlainDeviceID(COMPACTION_TEST_SG + PATH_SEPARATOR + "d0")));
        Assert.assertTrue(targetResources.get(i).isDeviceIdExist(new PlainDeviceID(COMPACTION_TEST_SG + PATH_SEPARATOR + "d1")));
        Assert.assertTrue(targetResources.get(i).isDeviceIdExist(new PlainDeviceID(COMPACTION_TEST_SG + PATH_SEPARATOR + "d2")));
        Assert.assertTrue(targetResources.get(i).isDeviceIdExist(new PlainDeviceID(COMPACTION_TEST_SG + PATH_SEPARATOR + "d3")));
        check(targetResources.get(i), deviceIdList);
    }
    deviceIdList.clear();
    deviceIdList.add(new PlainDeviceID(COMPACTION_TEST_SG + PATH_SEPARATOR + "d3"));
    for (int i = 3; i < 4; i++) {
        Assert.assertFalse(targetResources.get(i).isDeviceIdExist(new PlainDeviceID(COMPACTION_TEST_SG + PATH_SEPARATOR + "d0")));
        Assert.assertFalse(targetResources.get(i).isDeviceIdExist(new PlainDeviceID(COMPACTION_TEST_SG + PATH_SEPARATOR + "d1")));
        Assert.assertFalse(targetResources.get(i).isDeviceIdExist(new PlainDeviceID(COMPACTION_TEST_SG + PATH_SEPARATOR + "d2")));
        Assert.assertTrue(targetResources.get(i).isDeviceIdExist(new PlainDeviceID(COMPACTION_TEST_SG + PATH_SEPARATOR + "d3")));
        check(targetResources.get(i), deviceIdList);
    }
    Map<String, Long> measurementMaxTime = new HashMap<>();
    for (int i = 0; i < 4; i++) {
        for (int j = 0; j < 5; j++) {
            measurementMaxTime.putIfAbsent(COMPACTION_TEST_SG + PATH_SEPARATOR + "d" + i + PATH_SEPARATOR + "s" + j, Long.MIN_VALUE);
            PartialPath path = new MeasurementPath(COMPACTION_TEST_SG + PATH_SEPARATOR + "d" + i, "s" + j, new MeasurementSchema("s" + j, TSDataType.INT64));
            IDataBlockReader tsBlockReader = new SeriesDataBlockReader(path, FragmentInstanceContext.createFragmentInstanceContextForCompaction(EnvironmentUtils.TEST_QUERY_CONTEXT.getQueryId()), targetResources, new ArrayList<>(), true);
            int count = 0;
            while (tsBlockReader.hasNextBatch()) {
                TsBlock block = tsBlockReader.nextBatch();
                IBatchDataIterator iterator = block.getTsBlockSingleColumnIterator();
                while (iterator.hasNext()) {
                    if (measurementMaxTime.get(COMPACTION_TEST_SG + PATH_SEPARATOR + "d" + i + PATH_SEPARATOR + "s" + j) >= iterator.currentTime()) {
                        Assert.fail();
                    }
                    measurementMaxTime.put(COMPACTION_TEST_SG + PATH_SEPARATOR + "d" + i + PATH_SEPARATOR + "s" + j, iterator.currentTime());
                    if (i == 0 && ((450 <= iterator.currentTime() && iterator.currentTime() < 550) || (550 <= iterator.currentTime() && iterator.currentTime() < 650))) {
                        assertEquals(iterator.currentTime() + 20000, iterator.currentValue());
                    } else if ((i < 3 && j < 4) && ((20 <= iterator.currentTime() && iterator.currentTime() < 220) || (250 <= iterator.currentTime() && iterator.currentTime() < 450) || (480 <= iterator.currentTime() && iterator.currentTime() < 680))) {
                        assertEquals(iterator.currentTime() + 10000, iterator.currentValue());
                    } else {
                        assertEquals(iterator.currentTime(), iterator.currentValue());
                    }
                    count++;
                    iterator.next();
                }
            }
            tsBlockReader.close();
            if (i < 1) {
                if (j < 4) {
                    assertEquals(630, count);
                } else {
                    assertEquals(200, count);
                }
            } else if (i < 3) {
                if (j < 4) {
                    assertEquals(600, count);
                } else {
                    assertEquals(0, count);
                }
            } else {
                assertEquals(600, count);
            }
        }
    }
}

