                    }
                    measurementMaxTime.put(COMPACTION_TEST_SG + PATH_SEPARATOR + "d" + i + PATH_SEPARATOR + "s" + j, iterator.currentTime());
                    count++;
                    iterator.next();
                }
            }
            tsBlockReader.close();
            if (i < 2 && j < 7) {
                assertEquals(300, count);
            } else if (i == 3 && j < 5) {
                assertEquals(600, count);
            } else {
                assertEquals(0, count);
            }
        }
    }
