            IDataBlockReader tsBlockReader = new SeriesDataBlockReader(path, FragmentInstanceContext.createFragmentInstanceContextForCompaction(EnvironmentUtils.TEST_QUERY_CONTEXT.getQueryId()), tsFileManager.getTsFileList(true), tsFileManager.getTsFileList(false), true);
            int count = 0;
            while (tsBlockReader.hasNextBatch()) {
                TsBlock block = tsBlockReader.nextBatch();
                IBatchDataIterator iterator = block.getTsBlockAlignedRowIterator();
                while (iterator.hasNext()) {
                    if (iterator.currentTime() < 200 || (iterator.currentTime() < 550 && iterator.currentTime() >= 500)) {
                        assertEquals(iterator.currentTime(), ((TsPrimitiveType[]) (iterator.currentValue()))[0].getValue());
                    } else if (iterator.currentTime() < 850) {
                        assertEquals(iterator.currentTime() + 100, ((TsPrimitiveType[]) (iterator.currentValue()))[0].getValue());
                    } else {
                        assertEquals(iterator.currentTime() + 200, ((TsPrimitiveType[]) (iterator.currentValue()))[0].getValue());
                    }
                    count++;
                    iterator.next();
                }
            }
            tsBlockReader.close();
            if (i == TsFileGeneratorUtils.getAlignDeviceOffset()) {
                assertEquals(0, count);
            } else if (i < TsFileGeneratorUtils.getAlignDeviceOffset() + 2 && j < 3) {
                assertEquals(1450, count);
            } else if (i < TsFileGeneratorUtils.getAlignDeviceOffset() + 3 && j < 5) {
                assertEquals(1200, count);
            } else {
                assertEquals(600, count);
            }
        }
    }
}

