/**
 * Generate files that each chunk is greater than target size, so it can be read into memory and
 * directly flush to target files.
 *
 * @throws Exception
 */
@Test
public void testDirectlyFlushChunk() throws Exception {
    long originTargetChunkSize = IoTDBDescriptor.getInstance().getConfig().getTargetChunkSize();
    long originTargetChunkPointNum = IoTDBDescriptor.getInstance().getConfig().getTargetChunkPointNum();
    IoTDBDescriptor.getInstance().getConfig().setTargetChunkSize(100);
    IoTDBDescriptor.getInstance().getConfig().setTargetChunkPointNum(100);
    try {
        List<TsFileResource> sourceFiles = new ArrayList();
        int fileNum = 6;
        long pointStep = 200L;
        for (int i = 0; i < fileNum; ++i) {
            List<List<Long>> chunkPagePointsNum = new ArrayList<>();
            List<Long> pagePointsNum = new ArrayList<>();
            pagePointsNum.add((i + 1L) * pointStep);
            chunkPagePointsNum.add(pagePointsNum);
            TsFileResource resource = new TsFileResource(new File(SEQ_DIRS, String.format("%d-%d-0-0.tsfile", i + 1, i + 1)));
            sourceFiles.add(resource);
            CompactionFileGeneratorUtils.writeTsFile(fullPathSet, chunkPagePointsNum, i * 1500L, resource);
        }
        Map<PartialPath, List<TimeValuePair>> originData = CompactionCheckerUtils.getDataByQuery(paths, schemaList, sourceFiles, new ArrayList<>());
        TsFileNameGenerator.TsFileName tsFileName = TsFileNameGenerator.getTsFileName(sourceFiles.get(0).getTsFile().getName());
        TsFileResource targetResource = TsFileNameGenerator.getInnerCompactionTargetFileResource(sourceFiles, true);
        performer.setSourceFiles(sourceFiles);
        performer.setTargetFiles(Collections.singletonList(targetResource));
        performer.setSummary(new FastCompactionTaskSummary());
        performer.perform();
        CompactionUtils.moveTargetFile(Collections.singletonList(targetResource), CompactionTaskType.INNER_SEQ, storageGroup);
        Map<String, List<List<Long>>> chunkPagePointsNumMerged = new HashMap<>();
        long[] points = new long[fileNum];
        for (int i = 1; i <= fileNum; i++) {
            points[i - 1] = i * pointStep;
        }
        for (String path : fullPathSet) {
            CompactionCheckerUtils.putOnePageChunks(chunkPagePointsNumMerged, path, points);
        }
        Map<PartialPath, List<TimeValuePair>> compactedData = CompactionCheckerUtils.getDataByQuery(paths, schemaList, Collections.singletonList(targetResource), new ArrayList<>());
        CompactionCheckerUtils.validDataByValueList(originData, compactedData);
    } finally {
        IoTDBDescriptor.getInstance().getConfig().setTargetChunkSize(originTargetChunkSize);
        IoTDBDescriptor.getInstance().getConfig().setTargetChunkPointNum(originTargetChunkPointNum);
    }
}

/**
 * Generate some middle chunk that should be merged and cached in memory, and a large chunk that
 * is larger than target size. The latter should be merged with previously cached chunk and
 * flushed.
 *
 * @throws Exception
 */
@Test
public void testLargeChunkMergeWithCacheChunkAndFlush() throws Exception {
    long testTargetChunkPointNum = 2000L;
    long testChunkSizeLowerBound = 1024L;
    long testChunkPointNumLowerBound = 100L;
    long originTargetChunkSize = IoTDBDescriptor.getInstance().getConfig().getTargetChunkSize();
    long originTargetChunkPointNum = IoTDBDescriptor.getInstance().getConfig().getTargetChunkPointNum();
    IoTDBDescriptor.getInstance().getConfig().setTargetChunkSize(1024 * 1024);
    IoTDBDescriptor.getInstance().getConfig().setTargetChunkPointNum(testTargetChunkPointNum);
    long originChunkSizeLowerBound = IoTDBDescriptor.getInstance().getConfig().getChunkSizeLowerBoundInCompaction();
    IoTDBDescriptor.getInstance().getConfig().setChunkSizeLowerBoundInCompaction(testChunkSizeLowerBound);
    long originChunkPointNumLowerBound = IoTDBDescriptor.getInstance().getConfig().getChunkPointNumLowerBoundInCompaction();
    IoTDBDescriptor.getInstance().getConfig().setChunkPointNumLowerBoundInCompaction(testChunkPointNumLowerBound);
    try {
        List<TsFileResource> sourceFiles = new ArrayList();
        int fileNum = 6;
        long pointStep = 100L;
        long[] points = new long[fileNum];
        for (int i = 0; i < fileNum - 1; ++i) {
            List<List<Long>> chunkPagePointsNum = new ArrayList<>();
            List<Long> pagePointsNum = new ArrayList<>();
            pagePointsNum.add((i + 1) * pointStep);
