@Test
public void testCompactionWithDeletionsDuringCompactions() throws MetadataException, IOException, DataRegionException, InterruptedException {
    // create source seq files
    List<TsFileResource> sourceResources = new ArrayList<>();
    List<List<Long>> chunkPagePointsNum = new ArrayList<>();
    List<Long> pagePointsNum = new ArrayList<>();
    pagePointsNum.add(100L);
    chunkPagePointsNum.add(pagePointsNum);
    pagePointsNum = new ArrayList<>();
    pagePointsNum.add(200L);
    chunkPagePointsNum.add(pagePointsNum);
    pagePointsNum = new ArrayList<>();
    pagePointsNum.add(300L);
    chunkPagePointsNum.add(pagePointsNum);
    Set<String> paths = new HashSet<>();
    for (int i = 0; i < fullPaths.length; i++) {
        paths.add(fullPaths[i]);
    }
    for (int i = 0; i < 5; i++) {
        TsFileResource tsFileResource = CompactionFileGeneratorUtils.generateTsFileResource(true, i + 1);
        CompactionFileGeneratorUtils.writeTsFile(paths, chunkPagePointsNum, i * 600L, tsFileResource);
        sourceResources.add(tsFileResource);
    }
    DataRegion vsgp = new DataRegion(TestConstant.BASE_OUTPUT_PATH, "0", new TsFileFlushPolicy.DirectFlushPolicy(), COMPACTION_TEST_SG);
    vsgp.getTsFileResourceManager().addAll(sourceResources, true);
    // delete data before compaction
    vsgp.deleteByDevice(new PartialPath(fullPaths[0]), 0, 1000, 0);
    InnerSpaceCompactionTask task = new InnerSpaceCompactionTask(0, vsgp.getTsFileResourceManager(), sourceResources, true, new ReadChunkCompactionPerformer(), 0);
    task.setSourceFilesToCompactionCandidate();
    sourceResources.forEach(f -> f.setStatus(TsFileResourceStatus.COMPACTING));
    // delete data during compaction
    vsgp.deleteByDevice(new PartialPath(fullPaths[0]), 0, 1200, 0);
    vsgp.deleteByDevice(new PartialPath(fullPaths[0]), 0, 1800, 0);
    for (int i = 0; i < sourceResources.size() - 1; i++) {
        TsFileResource resource = sourceResources.get(i);
        resource.resetModFile();
        Assert.assertTrue(resource.getCompactionModFile().exists());
        Assert.assertTrue(resource.getModFile().exists());
        if (i < 2) {
            Assert.assertEquals(3, resource.getModFile().getModifications().size());
            Assert.assertEquals(2, resource.getCompactionModFile().getModifications().size());
        } else if (i < 3) {
            Assert.assertEquals(2, resource.getModFile().getModifications().size());
            Assert.assertEquals(2, resource.getCompactionModFile().getModifications().size());
        } else {
            Assert.assertEquals(1, resource.getModFile().getModifications().size());
            Assert.assertEquals(1, resource.getCompactionModFile().getModifications().size());
        }
    }
    task.start();
    for (TsFileResource resource : sourceResources) {
        Assert.assertFalse(resource.getTsFile().exists());
        Assert.assertFalse(resource.getModFile().exists());
        Assert.assertFalse(resource.getCompactionModFile().exists());
    }
    TsFileResource resource = TsFileNameGenerator.increaseInnerCompactionCnt(sourceResources.get(0));
    resource.resetModFile();
    Assert.assertTrue(resource.getModFile().exists());
    Assert.assertEquals(2, resource.getModFile().getModifications().size());
    Assert.assertFalse(resource.getCompactionModFile().exists());
}

@Test
public void testManyAlignedDeviceTsFile() throws IOException, InterruptedException {
    List<String> deviceNames = new ArrayList<>();
    for (int i = 0; i < 100000; i++) {
        deviceNames.add("d" + i);
    }
    TsFileResource resource = createEmptyFileAndResource(true);
    try (CompactionTestFileWriter writer = new CompactionTestFileWriter(resource)) {
        for (String device : deviceNames) {
            writer.startChunkGroup(device);
            writer.generateSimpleAlignedSeriesToCurrentDevice(Collections.singletonList("s0"), new TimeRange[] { new TimeRange(1, 2) }, TSEncoding.PLAIN, CompressionType.LZ4);
            writer.endChunkGroup();
        }
        writer.endFile();
    }
    seqResources.add(resource);
    tsFileManager.add(resource, true);
    long tsFileSize = resource.getTsFileSize();
    Thread thread = new Thread(() -> {
        InnerSpaceCompactionTask task = new InnerSpaceCompactionTask(tsFileManager, 0, seqResources, true, new ReadChunkCompactionPerformer(), 0);
        task.start();
    });
    thread.start();
    thread.join(TimeUnit.SECONDS.toMillis(30 + tsFileSize / IoTDBConstant.MB));
