    tsFileManager.addAll(unseqResources, false);
    AtomicBoolean fail = new AtomicBoolean(false);
    CountDownLatch cd = new CountDownLatch(1);
    Thread thread1 = new Thread(() -> {
        try {
            // the file is deleted before selection
            cd.await();
            SizeTieredCompactionSelector selector = new SizeTieredCompactionSelector("", "", 0, true, tsFileManager);
            List<TsFileResource> resources = tsFileManager.getOrCreateSequenceListByTimePartition(0);
            List<InnerSpaceCompactionTask> innerSpaceCompactionTasks = selector.selectInnerSpaceTask(resources);
            if (innerSpaceCompactionTasks.size() != 2) {
