            if (innerSpaceCompactionTasks.get(0).getSelectedTsFileResourceList().size() != 2 || innerSpaceCompactionTasks.get(1).getSelectedTsFileResourceList().size() != 2) {
                throw new RuntimeException("selected file num is not 2");
            }
        } catch (Exception e) {
            fail.set(true);
            e.printStackTrace();
            Assert.fail(e.getMessage());
        }
    });
    // delete seq files
