@Test
public void testSimpleCompactionByFlushChunk() throws IOException, StorageEngineException, InterruptedException, MetadataException, PageException {
    TsFileResource seqResource1 = generateSingleAlignedSeriesFile("d0", Arrays.asList("s0", "s1", "s2"), new TimeRange[] { new TimeRange(100000, 200000), new TimeRange(300000, 500000) }, TSEncoding.PLAIN, CompressionType.LZ4, Arrays.asList(false, false, false), true);
    seqResources.add(seqResource1);
    TsFileResource seqResource2 = generateSingleAlignedSeriesFile("d0", Arrays.asList("s0", "s1", "s2"), new TimeRange[] { new TimeRange(600000, 700000), new TimeRange(800000, 900000) }, TSEncoding.PLAIN, CompressionType.LZ4, Arrays.asList(false, false, false), true);
    seqResources.add(seqResource2);
    tsFileManager.addAll(seqResources, true);
    TsFileResource targetResource = TsFileNameGenerator.getInnerCompactionTargetFileResource(seqResources, true);
    ReadChunkCompactionPerformer performer = new ReadChunkCompactionPerformer();
    CompactionTaskSummary summary = new CompactionTaskSummary();
    performer.setSummary(summary);
    performer.setSourceFiles(seqResources);
    performer.setTargetFiles(Collections.singletonList(targetResource));
    performer.perform();
    CompactionUtils.moveTargetFile(Collections.singletonList(targetResource), CompactionTaskType.INNER_SEQ, COMPACTION_TEST_SG);
    Assert.assertEquals(16, summary.getDirectlyFlushChunkNum());
    Assert.assertEquals(0, summary.getDeserializeChunkCount());
    TsFileResourceUtils.validateTsFileDataCorrectness(targetResource);
    Assert.assertEquals(CompactionCheckerUtils.readFiles(seqResources), CompactionCheckerUtils.readFiles(Collections.singletonList(targetResource)));
}

