    for (int device = 0; device < deviceNum; device++) {
        for (int measurement = 0; measurement < measurementNum; measurement++) {
            Map<String, Pair<Long, Long>> deleteMap = new HashMap<>();
            deleteMap.put(COMPACTION_TEST_SG + PATH_SEPARATOR + "device" + device + PATH_SEPARATOR + "sensor" + measurement, new Pair(Long.MIN_VALUE, Long.MAX_VALUE));
