    for (TsFileResource resource : seqResources) {
        Assert.assertTrue(resource.getTsFile().exists());
        Assert.assertTrue(new File(resource.getTsFilePath() + TsFileResource.RESOURCE_SUFFIX).exists());
        Assert.assertTrue(resource.getModFile().exists());
        Assert.assertFalse(resource.getCompactionModFile().exists());
    }
    // tmp target file, target file and target resource file should be deleted after compaction
    for (TsFileResource resource : targetResources) {
        if (resource == null) {
            continue;
        }
        Assert.assertFalse(resource.getTsFile().exists());
        Assert.assertFalse(new File(resource.getTsFilePath().replace(IoTDBConstant.INNER_COMPACTION_TMP_FILE_SUFFIX, TsFileConstant.TSFILE_SUFFIX)).exists());
        Assert.assertFalse(new File(resource.getTsFilePath().replace(IoTDBConstant.INNER_COMPACTION_TMP_FILE_SUFFIX, TsFileConstant.TSFILE_SUFFIX) + TsFileResource.RESOURCE_SUFFIX).exists());
    }
}

