  Total 6 seq files, each file has different nonAligned timeseries.
  First and Second file: d0 ~ d1 and s0 ~ s2, time range is 0 ~ 99 and 150 ~ 249, value range is  0 ~ 99 and 150 ~ 249.
  Third and Forth file: d0 ~ d2 and s0 ~ s4, time range is 250 ~ 299 and 350 ~ 399, value range is 250 ~ 299 and 350 ~ 399.
  Fifth and Sixth file: d0 ~ d4 and s0 ~ s5, time range is 600 ~ 649 and 700 ~ 749, value range is 800 ~ 849 and 900 ~ 949.
  Timeseries d[0-4].s5 are deleted before compaction.
  */
@Test
public void testSeqInnerSpaceCompactionWithDifferentTimeseries() throws Exception {
    registerTimeseriesInMManger(5, 5, false);
    createFiles(2, 2, 3, 100, 0, 0, 50, 50, false, true);
    createFiles(2, 3, 5, 50, 250, 250, 50, 50, false, true);
    createFiles(2, 5, 6, 50, 600, 800, 50, 50, false, true);
    for (int i = 0; i < 5; i++) {
        for (int j = 0; j < 5; j++) {
            PartialPath path = new MeasurementPath(COMPACTION_TEST_SG + PATH_SEPARATOR + "d" + i, "s" + j, new MeasurementSchema("s" + j, TSDataType.INT64));
            IDataBlockReader tsBlockReader = new SeriesDataBlockReader(path, FragmentInstanceContext.createFragmentInstanceContextForCompaction(EnvironmentUtils.TEST_QUERY_CONTEXT.getQueryId()), seqResources, unseqResources, true);
            int count = 0;
            while (tsBlockReader.hasNextBatch()) {
                TsBlock block = tsBlockReader.nextBatch();
                IBatchDataIterator iterator = block.getTsBlockSingleColumnIterator();
                while (iterator.hasNext()) {
                    if (iterator.currentTime() >= 600) {
                        assertEquals(iterator.currentTime() + 200, iterator.currentValue());
                    } else {
                        assertEquals(iterator.currentTime(), iterator.currentValue());
                    }
                    count++;
                    iterator.next();
                }
            }
            tsBlockReader.close();
            if (i < 2 && j < 3) {
                assertEquals(400, count);
            } else if (i < 3) {
                assertEquals(200, count);
            } else {
                assertEquals(100, count);
            }
        }
    }
    List<TsFileResource> targetResources = CompactionFileGeneratorUtils.getInnerCompactionTargetTsFileResources(seqResources, true);
    performer.setTargetFiles(targetResources);
    performer.setSourceFiles(seqResources, unseqResources);
    performer.setSummary(new CompactionTaskSummary());
    performer.perform();
    Assert.assertEquals(0, FileReaderManager.getInstance().getClosedFileReaderMap().size());
    Assert.assertEquals(0, FileReaderManager.getInstance().getUnclosedFileReaderMap().size());
    CompactionUtils.moveTargetFile(targetResources, CompactionTaskType.INNER_SEQ, COMPACTION_TEST_SG);
    assertEquals(0, targetResources.get(0).getStartTime(new PlainDeviceID(COMPACTION_TEST_SG + PATH_SEPARATOR + "d0")));
    assertEquals(0, targetResources.get(0).getStartTime(new PlainDeviceID(COMPACTION_TEST_SG + PATH_SEPARATOR + "d1")));
    assertEquals(250, targetResources.get(0).getStartTime(new PlainDeviceID(COMPACTION_TEST_SG + PATH_SEPARATOR + "d2")));
    assertEquals(600, targetResources.get(0).getStartTime(new PlainDeviceID(COMPACTION_TEST_SG + PATH_SEPARATOR + "d3")));
    assertEquals(600, targetResources.get(0).getStartTime(new PlainDeviceID(COMPACTION_TEST_SG + PATH_SEPARATOR + "d4")));
    for (int i = 0; i < 5; i++) {
        assertEquals(749, targetResources.get(0).getEndTime(new PlainDeviceID(COMPACTION_TEST_SG + PATH_SEPARATOR + "d" + i)));
    }
    for (int i = 0; i < 5; i++) {
        for (int j = 0; j < 5; j++) {
            List<IMeasurementSchema> schemas = new ArrayList<>();
            schemas.add(new MeasurementSchema("s" + j, TSDataType.INT64));
            PartialPath path = new MeasurementPath(COMPACTION_TEST_SG + PATH_SEPARATOR + "d" + i, "s" + j, new MeasurementSchema("s" + j, TSDataType.INT64));
            IDataBlockReader tsBlockReader = new SeriesDataBlockReader(path, FragmentInstanceContext.createFragmentInstanceContextForCompaction(EnvironmentUtils.TEST_QUERY_CONTEXT.getQueryId()), targetResources, new ArrayList<>(), true);
            int count = 0;
            while (tsBlockReader.hasNextBatch()) {
                TsBlock block = tsBlockReader.nextBatch();
                IBatchDataIterator iterator = block.getTsBlockSingleColumnIterator();
                while (iterator.hasNext()) {
                    if (iterator.currentTime() >= 600) {
                        assertEquals(iterator.currentTime() + 200, iterator.currentValue());
                    } else {
                        assertEquals(iterator.currentTime(), iterator.currentValue());
                    }
                    count++;
                    iterator.next();
                }
            }
            tsBlockReader.close();
            if (i < 2 && j < 3) {
                assertEquals(400, count);
            } else if (i < 3 && j < 5) {
                assertEquals(200, count);
            } else if (i < 5 && j < 5) {
                assertEquals(100, count);
            }
        }
    }
}

