                TsBlock block = tsBlockReader.nextBatch();
                IBatchDataIterator iterator = block.getTsBlockAlignedRowIterator();
                while (iterator.hasNext()) {
                    if (i == TsFileGeneratorUtils.getAlignDeviceOffset() && ((450 <= iterator.currentTime() && iterator.currentTime() < 550) || (550 <= iterator.currentTime() && iterator.currentTime() < 650))) {
                        assertEquals(iterator.currentTime() + 20000, ((TsPrimitiveType[]) (iterator.currentValue()))[0].getValue());
                    } else if ((i < TsFileGeneratorUtils.getAlignDeviceOffset() + 3 && j < 4) && ((20 <= iterator.currentTime() && iterator.currentTime() < 220) || (250 <= iterator.currentTime() && iterator.currentTime() < 450) || (480 <= iterator.currentTime() && iterator.currentTime() < 680))) {
