            tsDataTypes.addAll(dataTypes);
        }
        tsFileIOWriter.endFile();
    }
    resource.serialize();
    unseqResources.add(resource);
    // start compacting
    tsFileManager.addAll(seqResources, true);
    tsFileManager.addAll(unseqResources, false);
    Map<PartialPath, List<TimeValuePair>> sourceDatas = readSourceFiles(createTimeseries(maxDeviceNum, maxMeasurementNum, false), tsDataTypes);
    CrossSpaceCompactionTask task = new CrossSpaceCompactionTask(0, tsFileManager, seqResources, unseqResources, new ReadPointCompactionPerformer(), 0, 0);
    Assert.assertTrue(task.start());
    validateSeqFiles(true);
    validateTargetDatas(sourceDatas, tsDataTypes);
    InnerSpaceCompactionTask innerTask = new InnerSpaceCompactionTask(0, tsFileManager, tsFileManager.getTsFileList(true), true, new ReadPointCompactionPerformer(), 0);
    Assert.assertTrue(innerTask.start());
    validateSeqFiles(true);
    validateTargetDatas(sourceDatas, tsDataTypes);
}

