@Test
public void testMarkFileAndRepairWithInnerSeqSpaceCompactionTask() throws IOException, InterruptedException {
    TsFileResource seqResource1 = createEmptyFileAndResource(true);
    try (CompactionTestFileWriter writer = new CompactionTestFileWriter(seqResource1)) {
        writer.startChunkGroup("d1");
        writer.generateSimpleAlignedSeriesToCurrentDevice(Arrays.asList("s1", "s2"), new TimeRange[][][] { new TimeRange[][] { new TimeRange[] { new TimeRange(10, 20), new TimeRange(29, 30), new TimeRange(21, 25) } } }, TSEncoding.PLAIN, CompressionType.LZ4);
        writer.endChunkGroup();
        writer.endFile();
    }
    TsFileResource seqResource2 = createEmptyFileAndResource(true);
    try (CompactionTestFileWriter writer = new CompactionTestFileWriter(seqResource2)) {
        writer.startChunkGroup("d1");
        writer.generateSimpleAlignedSeriesToCurrentDevice(Arrays.asList("s1", "s2"), new TimeRange[][] { new TimeRange[] { new TimeRange(10, 20), new TimeRange(5, 30) } }, TSEncoding.PLAIN, CompressionType.LZ4);
        writer.endChunkGroup();
        writer.endFile();
    }
    InnerSpaceCompactionTask task = new InnerSpaceCompactionTask(0, tsFileManager, Arrays.asList(seqResource1, seqResource2), true, new ReadChunkCompactionPerformer(), 0);
    Assert.assertFalse(task.start());
    for (TsFileResource resource : tsFileManager.getTsFileList(true)) {
        Assert.assertEquals(resource.getTsFileRepairStatus(), TsFileRepairStatus.NEED_TO_REPAIR);
    }
    long initialFinishedCompactionTaskNum = CompactionTaskManager.getInstance().getFinishedTaskNum();
    CompactionScheduleSummary summary = new CompactionScheduleSummary();
    CompactionScheduler.scheduleCompaction(tsFileManager, 0, summary);
    Assert.assertEquals(2, summary.getSubmitSeqInnerSpaceCompactionTaskNum());
    int waitSecond = 20;
    while (CompactionTaskManager.getInstance().getFinishedTaskNum() - initialFinishedCompactionTaskNum < 2) {
        if (waitSecond == 0) {
            Assert.fail("Exceed the max time to wait repair compaction");
        }
        try {
            Thread.sleep(TimeUnit.SECONDS.toMillis(1));
            waitSecond--;
        } catch (InterruptedException e) {
            throw new RuntimeException(e);
        }
    }
    Assert.assertEquals(0, tsFileManager.getTsFileList(true).size());
    Assert.assertEquals(2, tsFileManager.getTsFileList(false).size());
    for (TsFileResource resource : tsFileManager.getTsFileList(false)) {
        TsFileResourceUtils.validateTsFileDataCorrectness(resource);
    }
    Assert.assertTrue(TsFileResourceUtils.validateTsFileResourcesHasNoOverlap(tsFileManager.getOrCreateSequenceListByTimePartition(0)));
}

