            Assert.assertTrue(testFile.getParentFile().mkdirs());
        }
        if (testFile.exists()) {
            Assert.assertTrue(testFile.delete());
        }
        Assert.assertNull(info.getFileFromDataDirs());
        Assert.assertTrue(testFile.createNewFile());
