            MultiTsFileDeviceIterator.MultiTsFileNonAlignedMeasurementMetadataListIterator measurementIterator = multiTsFileDeviceIterator.iterateNotAlignedSeriesAndChunkMetadataListOfCurrentDevice();
            while (measurementIterator.hasNextSeries()) {
                String series = measurementIterator.nextSeries();
                LinkedList<Pair<TsFileSequenceReader, List<ChunkMetadata>>> readerAndChunkMetadataList = measurementIterator.getMetadataListForCurrentSeries();
                measurementSet.add(series);
            }
