            timeseriesPaths.add(new AlignedPath(COMPACTION_TEST_SG + PATH_SEPARATOR + "d" + i, Collections.singletonList("s" + j), Collections.singletonList(new MeasurementSchema("s" + j, TSDataType.INT64))));
        }
    }
    sourceData = readSourceFiles(timeseriesPaths, Collections.emptyList());
    // sort the deviceId in lexicographical order from small to large
    deviceIds = new ArrayList<>();
    for (int i = 0; i < 30; i++) {
        deviceIds.add(new PlainDeviceID("root.testsg.d" + (i + TsFileGeneratorUtils.getAlignDeviceOffset())));
    }
    deviceIds.sort(IDeviceID::compareTo);
    deviceNum = 0;
    try (MultiTsFileDeviceIterator multiTsFileDeviceIterator = new MultiTsFileDeviceIterator(tsFileManager.getTsFileList(true))) {
        while (multiTsFileDeviceIterator.hasNextDevice()) {
            Pair<IDeviceID, Boolean> deviceInfo = multiTsFileDeviceIterator.nextDevice();
            Assert.assertEquals(deviceIds.get(deviceNum), deviceInfo.left);
            Assert.assertTrue(deviceInfo.right);
            deviceNum++;
        }
    }
    Assert.assertEquals(30, deviceNum);
    TsFileGeneratorUtils.alignDeviceOffset = oldAlignedDeviceOffset;
    List<TsFileResource> targetResources = CompactionFileGeneratorUtils.getInnerCompactionTargetTsFileResources(tsFileManager.getTsFileList(true), true);
    FastCompactionPerformer performer = new FastCompactionPerformer(tsFileManager.getTsFileList(true), Collections.emptyList(), targetResources);
    performer.setSummary(new FastCompactionTaskSummary());
    performer.perform();
    CompactionUtils.moveTargetFile(targetResources, CompactionTaskType.INNER_SEQ, COMPACTION_TEST_SG);
    tsFileManager.replace(tsFileManager.getTsFileList(true), Collections.emptyList(), targetResources, 0);
    tsFileManager.getTsFileList(true).get(0).setStatusForTest(TsFileResourceStatus.NORMAL);
    validateSeqFiles(true);
    validateTargetDatas(sourceData, Collections.emptyList());
}

