@Test
public void test2S() throws IOException {
    // 2 series
    test(new long[] { 1, 2, 3, 4, 5, 6 }, new long[] { 2, 2, 2, 1, 2, 2 }, new long[] { 1, 2, 3, 4, 5 }, new long[] { 1, 2, 3, 5, 6 });
    test(new long[] { 1, 2, 3, 4, 5 }, new long[] { 1, 1, 1, 1, 1 }, new long[] { 1, 2, 3, 4, 5 }, new long[] {});
    test(new long[] { 1, 2, 3, 4, 5 }, new long[] { 2, 2, 2, 2, 2 }, new long[] {}, new long[] { 1, 2, 3, 4, 5 });
    test(new long[] { 1, 2, 3, 4, 5, 6, 7, 8 }, new long[] { 1, 1, 1, 1, 1, 2, 2, 2 }, new long[] { 1, 2, 3, 4, 5 }, new long[] { 6, 7, 8 });
    // 3 series
    test(new long[] { 1, 2, 3, 4, 5, 6, 7 }, new long[] { 3, 3, 3, 1, 3, 2, 3 }, new long[] { 1, 2, 3, 4, 5 }, new long[] { 1, 2, 3, 5, 6 }, new long[] { 1, 2, 3, 5, 7 });
    test(new long[] { 1, 2, 3, 4, 5, 6 }, new long[] { 1, 1, 2, 3, 2, 3 }, new long[] { 1, 2 }, new long[] { 3, 5 }, new long[] { 4, 6 });
}

@Test
public void test() throws IOException {
    FakedSeriesReader reader1 = new FakedSeriesReader(100, 80, 5, 11);
    FakedSeriesReader reader2 = new FakedSeriesReader(150, 60, 6, 19);
    FakedSeriesReader reader3 = new FakedSeriesReader(180, 50, 7, 31);
    PriorityMergeReader priorityMergeReader = new PriorityMergeReader();
    priorityMergeReader.addReader(reader1, 3);
    priorityMergeReader.addReader(reader2, 2);
    priorityMergeReader.addReader(reader3, 1);
    int cnt = 0;
    while (priorityMergeReader.hasNextTimeValuePair()) {
        TimeValuePair timeValuePair = priorityMergeReader.nextTimeValuePair();
        long time = timeValuePair.getTimestamp();
        long value = (long) timeValuePair.getValue().getValue();
        // System.out.println(time + "," + value);
        if (time <= 500 && (time - 100) % 5 == 0) {
            Assert.assertEquals(time % 11, value);
        } else if (time <= 510 && (time - 150) % 6 == 0) {
            Assert.assertEquals(time % 19, value);
        } else {
            Assert.assertEquals(time % 31, value);
        }
        cnt++;
    }
    Assert.assertEquals(162, cnt);
}

@Test
public void testSkipFile() throws IllegalPathException, IOException {
    AlignedSeriesScanUtil seriesScanUtil = getAlignedSeriesScanUtil(5, 10);
    Assert.assertTrue(seriesScanUtil.hasNextFile());
    Assert.assertTrue(seriesScanUtil.hasNextChunk());
    Assert.assertTrue(seriesScanUtil.hasNextPage());
    TsBlock tsBlock = seriesScanUtil.nextPage();
    Assert.assertEquals(5, tsBlock.getPositionCount());
    long expectedTime = 10;
    for (int i = 0, size = tsBlock.getPositionCount(); i < size; i++) {
        Assert.assertEquals(expectedTime++, tsBlock.getTimeByIndex(i));
    }
    Assert.assertFalse(seriesScanUtil.hasNextPage());
    Assert.assertFalse(seriesScanUtil.hasNextChunk());
    Assert.assertFalse(seriesScanUtil.hasNextFile());
}

