    IntStream.range(0, hybridProgressIndexNum).forEach(i -> progressIndexList.add(new HybridProgressIndex(MinimumProgressIndex.INSTANCE)));
    Collections.shuffle(progressIndexList);
    progressIndexList.sort(ProgressIndex::topologicalCompareTo);
    int size = progressIndexList.size();
    for (int i = 0; i < size - 1; i++) {
        int finalI = i;
        for (int j = i; j < size; j++) {
