@Test
public void testProgressIndexTopologicalSort() {
    Random random = new Random();
    List<ProgressIndex> progressIndexList = new ArrayList<>();
    int ioTProgressIndexNum = 10000, peerIdRange = 3, searchIndexRange = 100000;
    IntStream.range(0, ioTProgressIndexNum).forEach(i -> progressIndexList.add(new IoTProgressIndex(random.nextInt(peerIdRange), (long) random.nextInt(searchIndexRange))));
    int simpleProgressIndexNum = 10000, rebootTimesRange = 3, memtableFlushOrderIdRange = 100000;
    IntStream.range(0, simpleProgressIndexNum).forEach(i -> progressIndexList.add(new SimpleProgressIndex(random.nextInt(rebootTimesRange), random.nextInt(memtableFlushOrderIdRange))));
    int recoverProgressIndexNum = 10000, dataNodeIdRange = 3;
    IntStream.range(0, recoverProgressIndexNum).forEach(i -> progressIndexList.add(new RecoverProgressIndex(random.nextInt(dataNodeIdRange), new SimpleProgressIndex(random.nextInt(rebootTimesRange), random.nextInt(memtableFlushOrderIdRange)))));
    int minimumProgressIndexNum = 10000;
    IntStream.range(0, minimumProgressIndexNum).forEach(i -> progressIndexList.add(MinimumProgressIndex.INSTANCE));
    int hybridProgressIndexNum = 10000;
    IntStream.range(0, hybridProgressIndexNum).forEach(i -> {
        HybridProgressIndex hybridProgressIndex = new HybridProgressIndex(new IoTProgressIndex(random.nextInt(peerIdRange), (long) random.nextInt(searchIndexRange)));
        if (random.nextInt(2) == 1) {
            hybridProgressIndex.updateToMinimumEqualOrIsAfterProgressIndex(new SimpleProgressIndex(random.nextInt(rebootTimesRange), random.nextInt(memtableFlushOrderIdRange)));
        }
        if (random.nextInt(2) == 1) {
            hybridProgressIndex.updateToMinimumEqualOrIsAfterProgressIndex(new RecoverProgressIndex(random.nextInt(dataNodeIdRange), new SimpleProgressIndex(random.nextInt(rebootTimesRange), random.nextInt(memtableFlushOrderIdRange))));
        }
        progressIndexList.add(hybridProgressIndex);
    });
    Collections.shuffle(progressIndexList);
    final long startTime = System.currentTimeMillis();
    progressIndexList.sort(ProgressIndex::topologicalCompareTo);
    final long costTime = System.currentTimeMillis() - startTime;
    System.out.println("ProgressIndex List Size = " + progressIndexList.size());
    System.out.println("sort time = " + costTime + "ms");
    System.out.println(("Sort speed = " + (double) (costTime) / ((double) (progressIndexList.size())) + "ms/s"));
    int size = progressIndexList.size();
    for (int i = 0; i < size - 1; i++) {
        int finalI = i;
        for (int j = i; j < size; j++) {
            if (progressIndexList.get(i).isAfter(progressIndexList.get(j))) {
                System.out.println("progressIndexList.get(i) = " + progressIndexList.get(i));
                System.out.println("i = " + i);
                System.out.println("progressIndexList.get(i).getTotalOrderSumTuple() = " + progressIndexList.get(i).getTotalOrderSumTuple());
                System.out.println("progressIndexList.get(j) = " + progressIndexList.get(j));
                System.out.println("j = " + j);
                System.out.println("progressIndexList.get(j).getTotalOrderSumTuple() = " + progressIndexList.get(j).getTotalOrderSumTuple());
                System.out.println(System.lineSeparator());
            }
        }
        Assert.assertTrue(IntStream.range(i, size).noneMatch(j -> progressIndexList.get(finalI).isAfter(progressIndexList.get(j))));
    }
}

