@Test
public void testTTLRead() throws IOException, WriteProcessException, QueryProcessException, MetadataException {
    prepareData();
    // files before ttl
    QueryDataSource dataSource = dataRegion.query(Collections.singletonList(mockMeasurementPath()), sg1, EnvironmentUtils.TEST_QUERY_CONTEXT, null, null);
    List<TsFileResource> seqResource = dataSource.getSeqResources();
    List<TsFileResource> unseqResource = dataSource.getUnseqResources();
    assertEquals(4, seqResource.size());
    assertEquals(4, unseqResource.size());
    DataNodeTTLCache.getInstance().setTTL(sg1, 500);
    // files after ttl
    dataSource = dataRegion.query(Collections.singletonList(mockMeasurementPath()), sg1, EnvironmentUtils.TEST_QUERY_CONTEXT, null, null);
    seqResource = dataSource.getSeqResources();
    unseqResource = dataSource.getUnseqResources();
    assertEquals(4, seqResource.size());
    assertEquals(4, unseqResource.size());
    MeasurementPath path = mockMeasurementPath();
    IDataBlockReader reader = new SeriesDataBlockReader(path, FragmentInstanceContext.createFragmentInstanceContextForCompaction(TEST_QUERY_JOB_ID), seqResource, unseqResource, true);
    int cnt = 0;
    while (reader.hasNextBatch()) {
        TsBlock tsblock = reader.nextBatch();
        cnt += tsblock.getPositionCount();
    }
    reader.close();
    // we cannot offer the exact number since when exactly ttl will be checked is unknown
    assertTrue(cnt <= 1000);
    DataNodeTTLCache.getInstance().setTTL(sg1, 1);
    dataSource = dataRegion.query(Collections.singletonList(mockMeasurementPath()), sg1, EnvironmentUtils.TEST_QUERY_CONTEXT, null, null);
    seqResource = dataSource.getSeqResources();
    unseqResource = dataSource.getUnseqResources();
    assertEquals(4, seqResource.size());
    assertEquals(4, unseqResource.size());
    reader = new SeriesDataBlockReader(path, FragmentInstanceContext.createFragmentInstanceContextForCompaction(TEST_QUERY_JOB_ID), seqResource, unseqResource, true);
    cnt = 0;
    while (reader.hasNextBatch()) {
        TsBlock tsblock = reader.nextBatch();
        cnt += tsblock.getPositionCount();
    }
    reader.close();
    // we cannot offer the exact number since when exactly ttl will be checked is unknown
    assertTrue(cnt == 0);
}

@Test
public void testTTLRemoval() throws StorageEngineException, WriteProcessException, IllegalPathException, InterruptedException {
    boolean isEnableCrossCompaction = IoTDBDescriptor.getInstance().getConfig().isEnableCrossSpaceCompaction();
    IoTDBDescriptor.getInstance().getConfig().setEnableCrossSpaceCompaction(false);
    prepareData();
    dataRegion.syncCloseAllWorkingTsFileProcessors();
    // files before ttl
    File seqDir = new File(TierManager.getInstance().getNextFolderForTsFile(0, true), sg1);
    File unseqDir = new File(TierManager.getInstance().getNextFolderForTsFile(0, false), sg1);
    List<File> seqFiles = new ArrayList<>();
    for (File directory : seqDir.listFiles()) {
        if (directory.isDirectory()) {
            for (File file : directory.listFiles()) {
                if (file.isDirectory()) {
                    for (File tsfile : file.listFiles()) {
                        if (tsfile.getPath().endsWith(TsFileConstant.TSFILE_SUFFIX)) {
                            seqFiles.add(file);
                        }
                    }
                }
            }
        }
    }
    List<File> unseqFiles = new ArrayList<>();
    for (File directory : unseqDir.listFiles()) {
        if (directory.isDirectory()) {
            for (File file : directory.listFiles()) {
                if (file.isDirectory()) {
                    for (File tsfile : file.listFiles()) {
                        if (tsfile.getPath().endsWith(TsFileConstant.TSFILE_SUFFIX)) {
                            unseqFiles.add(file);
                        }
                    }
                }
            }
        }
    }
    assertEquals(4, seqFiles.size());
    assertEquals(4, unseqFiles.size());
    try {
        sleep(500);
    } catch (InterruptedException e) {
        e.printStackTrace();
    }
    DataNodeTTLCache.getInstance().setTTL(sg1, 500);
    for (long timePartition : dataRegion.getTimePartitions()) {
        CompactionScheduler.tryToSubmitSettleCompactionTask(dataRegion.getTsFileManager(), timePartition, new CompactionScheduleSummary(), true);
    }
    long totalWaitingTime = 0;
    while (dataRegion.getTsFileManager().getTsFileList(true).size() + dataRegion.getTsFileManager().getTsFileList(false).size() != 0) {
        sleep(200);
        totalWaitingTime += 200;
        if (totalWaitingTime >= 5000) {
            fail();
        }
    }
    // files after ttl
    seqFiles = new ArrayList<>();
    for (File directory : seqDir.listFiles()) {
        if (directory.isDirectory()) {
            for (File file : directory.listFiles()) {
                if (file.isDirectory()) {
                    for (File tsfile : file.listFiles()) {
                        if (tsfile.getPath().endsWith(TsFileConstant.TSFILE_SUFFIX)) {
                            seqFiles.add(file);
                        }
                    }
                }
            }
        }
    }
    unseqFiles = new ArrayList<>();
    for (File directory : unseqDir.listFiles()) {
        if (directory.isDirectory()) {
            for (File file : directory.listFiles()) {
                if (file.isDirectory()) {
                    for (File tsfile : file.listFiles()) {
                        if (tsfile.getPath().endsWith(TsFileConstant.TSFILE_SUFFIX)) {
                            unseqFiles.add(file);
                        }
                    }
                }
            }
        }
    }
    assertTrue(seqFiles.size() <= 2);
    assertEquals(0, unseqFiles.size());
    IoTDBDescriptor.getInstance().getConfig().setEnableCrossSpaceCompaction(isEnableCrossCompaction);
}

