@Test
public void testUncompressedWALStructure() throws QueryProcessException, IllegalPathException, IOException {
    PublicBAOS baos = new PublicBAOS();
    DataOutputStream dataOutputStream = new DataOutputStream(baos);
    List<InsertRowNode> insertRowNodes = new ArrayList<>();
    for (int i = 0; i < 100; ++i) {
        InsertRowNode node = WALTestUtils.getInsertRowNode(devicePath, i);
        insertRowNodes.add(node);
        node.serialize(dataOutputStream);
    }
    dataOutputStream.close();
    ByteBuffer buf = ByteBuffer.wrap(baos.toByteArray());
    // Do not compress it
    IoTDBDescriptor.getInstance().getConfig().setWALCompressionAlgorithm(CompressionType.UNCOMPRESSED);
    try (WALWriter writer = new WALWriter(walFile)) {
        buf.position(buf.limit());
        writer.write(buf);
    }
    try (DataInputStream dataInputStream = new DataInputStream(new BufferedInputStream(Files.newInputStream(walFile.toPath())))) {
        byte[] magicStringBytes = new byte[WALFileVersion.V2.getVersionBytes().length];
        // head magic string
        dataInputStream.readFully(magicStringBytes);
        Assert.assertEquals(WALFileVersion.V2.getVersionString(), new String(magicStringBytes));
        Assert.assertEquals(CompressionType.UNCOMPRESSED, CompressionType.deserialize(dataInputStream.readByte()));
        Assert.assertEquals(buf.array().length, dataInputStream.readInt());
        ByteBuffer dataBuf = ByteBuffer.allocate(buf.array().length);
