    walNode.onMemTableCreated(memTable, tsFilePath);
    while (time < 20000) {
        ++time;
        InsertTabletNode insertTabletNode = getInsertTabletNode(devicePath + memTableId, new long[] { time });
        WALFlushListener walFlushListener = walNode.log(memTableId, insertTabletNode, 0, insertTabletNode.getRowCount());
        walFlushListeners.add(walFlushListener);
    }
    walNode.onMemTableFlushed(memTable);
    walNode.onMemTableCreated(new PrimitiveMemTable(databasePath, dataRegionId), tsFilePath);
    Awaitility.await().until(() -> walNode.isAllWALEntriesConsumed());
    // check existence of _0-0-0.wal file and _1-0-1.wal file
    assertTrue(new File(logDirectory + File.separator + WALFileUtils.getLogFileName(0, 0, WALFileStatus.CONTAINS_NONE_SEARCH_INDEX)).exists());
    assertTrue(new File(logDirectory + File.separator + WALFileUtils.getLogFileName(1, 0, WALFileStatus.CONTAINS_SEARCH_INDEX)).exists());
    walNode.deleteOutdatedFiles();
    assertFalse(new File(logDirectory + File.separator + WALFileUtils.getLogFileName(0, 0, WALFileStatus.CONTAINS_NONE_SEARCH_INDEX)).exists());
    assertTrue(new File(logDirectory + File.separator + WALFileUtils.getLogFileName(1, 0, WALFileStatus.CONTAINS_SEARCH_INDEX)).exists());
    // check flush listeners
    try {
        for (WALFlushListener walFlushListener : walFlushListeners) {
            assertNotEquals(WALFlushListener.Status.FAILURE, walFlushListener.waitForResult());
        }
    } catch (NullPointerException e) {
        // ignore
    }
}

