    BitMap[] bitMaps = new BitMap[dataTypes.size()];
    for (int i = 0; i < dataTypes.size(); i++) {
        if (bitMaps[i] == null) {
            bitMaps[i] = new BitMap(times.length);
        }
        // mark value of time=9 as null
        bitMaps[i].mark(3);
    }
    MeasurementSchema[] schemas = new MeasurementSchema[] { null, new MeasurementSchema("s2", TSDataType.INT64), new MeasurementSchema("s3", TSDataType.BOOLEAN), new MeasurementSchema("s4", TSDataType.FLOAT), null };
    InsertTabletNode insertTabletNode = new InsertTabletNode(new PlanNodeId(""), new PartialPath(DEVICE3_NAME), true, new String[] { null, "s2", "s3", "s4", null }, new TSDataType[] { TSDataType.INT32, TSDataType.INT64, TSDataType.BOOLEAN, TSDataType.FLOAT, TSDataType.TEXT }, schemas, times, bitMaps, columns, times.length);
    // redo InsertTabletPlan, data region is used to test IdTable, don't test IdTable here
    TsFilePlanRedoer planRedoer = new TsFilePlanRedoer(tsFileResource);
    insertTabletNode.setMeasurementSchemas(schemas);
    planRedoer.redoInsert(insertTabletNode);
    // generate InsertRowPlan
    int time = 9;
    TSDataType[] dataTypes2 = new TSDataType[] { TSDataType.INT32, TSDataType.INT64, TSDataType.BOOLEAN, TSDataType.FLOAT, TSDataType.TEXT };
    Object[] columns2 = new Object[] { 400, 400L, true, 400.0f, new Binary("400", TSFileConfig.STRING_CHARSET) };
    // redo InsertTabletPlan, data region is used to test IdTable, don't test IdTable here
    InsertRowNode insertRowNode = new InsertRowNode(new PlanNodeId(""), new PartialPath(DEVICE3_NAME), true, new String[] { null, "s2", "s3", "s4", null }, dataTypes2, time, columns2, false);
    insertRowNode.setMeasurementSchemas(schemas);
    planRedoer.redoInsert(insertRowNode);
    // check data in memTable
    IMemTable recoveryMemTable = planRedoer.getRecoveryMemTable();
    // check d3
    AlignedPath fullPath = new AlignedPath(((PlainDeviceID) DEVICE3_NAME).toStringID(), Arrays.asList("s1", "s2", "s3", "s4", "s5"), Arrays.asList(new MeasurementSchema("s1", TSDataType.INT32, TSEncoding.RLE), new MeasurementSchema("s2", TSDataType.INT64, TSEncoding.RLE), new MeasurementSchema("s3", TSDataType.BOOLEAN, TSEncoding.RLE), new MeasurementSchema("s4", TSDataType.FLOAT, TSEncoding.RLE), new MeasurementSchema("s5", TSDataType.TEXT, TSEncoding.PLAIN)));
    ReadOnlyMemChunk memChunk = recoveryMemTable.query(new QueryContext(), fullPath, Long.MIN_VALUE, null);
    IPointReader iterator = memChunk.getPointReader();
    time = 6;
    while (iterator.hasNextTimeValuePair()) {
        TimeValuePair timeValuePair = iterator.nextTimeValuePair();
        assertEquals(time, timeValuePair.getTimestamp());
        assertEquals(null, timeValuePair.getValue().getVector()[0]);
        assertEquals((time - 5) * 100L, timeValuePair.getValue().getVector()[1].getLong());
        assertEquals(true, timeValuePair.getValue().getVector()[2].getBoolean());
        assertEquals((time - 5) * 100, timeValuePair.getValue().getVector()[3].getFloat(), 0.00001);
        assertEquals(null, timeValuePair.getValue().getVector()[4]);
        time++;
    }
    assertEquals(10, time);
}

