@Test
public void testPutAndOrder() throws InterruptedException {
    Integer[] integers = new Integer[] { 0, -5, 11, 233, 45, 69, -249, 33, 787, -556, 762, 380, 747, 777, 22, 77, 666, 321, 456, 575 };
    for (int integer : integers) {
        queue.put(integer);
    }
    Assert.assertEquals(10, queue.size());
    int prev = queue.take();
    List<Integer> integerList = new ArrayList<>();
    integerList.add(prev);
    for (int i = 0; i < 9; ++i) {
        int curr = queue.take();
        Assert.assertTrue(prev <= curr);
        integerList.add(curr);
        prev = curr;
    }
    Arrays.sort(integers);
    List<Integer> expectedList = Arrays.asList(integers).subList(0, 10);
    Assert.assertArrayEquals(expectedList.toArray(new Integer[0]), integerList.toArray(new Integer[0]));
}

