@Test
public void testSimpleTranslateSnapshot() throws Exception {
    if (testParams.testModeName.equals("PBTree")) {
        return;
    }
    ISchemaRegion schemaRegion = getSchemaRegion("root.sg", 0);
    PartialPath databasePath = new PartialPath("root.sg");
    // Tree in memtree:
    // root->sg->s1->g1->temp
    //          |     |->status
    //          |->s2->g2->t2->temp
    //              |->g4->status
    //              |->g5->level
    HashMap<String, ICreateTimeSeriesPlan> planMap = new HashMap<>();
    planMap.put("root.sg.s1.g1.temp", SchemaRegionWritePlanFactory.getCreateTimeSeriesPlan(new PartialPath("root.sg.s1.g1.temp"), TSDataType.FLOAT, TSEncoding.RLE, CompressionType.SNAPPY, null, null, null, null));
    planMap.put("root.sg.s1.g1.status", SchemaRegionWritePlanFactory.getCreateTimeSeriesPlan(new PartialPath("root.sg.s1.g1.status"), TSDataType.INT64, TSEncoding.TS_2DIFF, CompressionType.LZ4, null, null, null, null));
    planMap.put("root.sg.s2.g2.t2.temp", SchemaRegionWritePlanFactory.getCreateTimeSeriesPlan(new PartialPath("root.sg.s2.g2.t2.temp"), TSDataType.DOUBLE, TSEncoding.RLE, CompressionType.GZIP, null, null, null, null));
    planMap.put("root.sg.s2.g4.status", SchemaRegionWritePlanFactory.getCreateTimeSeriesPlan(new PartialPath("root.sg.s2.g4.status"), TSDataType.INT64, TSEncoding.RLE, CompressionType.ZSTD, null, null, null, null));
    planMap.put("root.sg.s2.g5.level", SchemaRegionWritePlanFactory.getCreateTimeSeriesPlan(new PartialPath("root.sg.s2.g5.level"), TSDataType.INT32, TSEncoding.GORILLA, CompressionType.LZMA2, null, null, null, null));
    for (ICreateTimeSeriesPlan plan : planMap.values()) {
        schemaRegion.createTimeSeries(plan, -1);
    }
    File snapshotDir = new File(config.getSchemaDir() + File.separator + "snapshot");
    snapshotDir.mkdir();
    schemaRegion.createSnapshot(snapshotDir);
    SRStatementGenerator statements = SchemaRegionSnapshotParser.translate2Statements(Paths.get(config.getSchemaDir() + File.separator + "snapshot" + File.separator + snapshotFileName), null, databasePath);
    assert statements != null;
    for (Statement stmt : statements) {
        CreateTimeSeriesStatement createTimeSeriesStatement = (CreateTimeSeriesStatement) stmt;
        ICreateTimeSeriesPlan plan = planMap.get(createTimeSeriesStatement.getPaths().get(0).toString());
        Assert.assertEquals(plan.getEncoding(), createTimeSeriesStatement.getEncoding());
        Assert.assertEquals(plan.getCompressor(), createTimeSeriesStatement.getCompressor());
        Assert.assertEquals(plan.getDataType(), createTimeSeriesStatement.getDataType());
        Assert.assertEquals(plan.getAlias(), createTimeSeriesStatement.getAlias());
        Assert.assertEquals(plan.getProps(), createTimeSeriesStatement.getProps());
        Assert.assertEquals(plan.getAttributes(), createTimeSeriesStatement.getAttributes());
        Assert.assertEquals(plan.getTags(), createTimeSeriesStatement.getTags());
    }
    statements.checkException();
}

