    Assert.assertEquals(Collections.nCopies(measurementTypes.size(), TSDataType.INT64), SchemaUtils.getAggregatedDataTypes(measurementTypes, SqlConstant.COUNT));
    Assert.assertEquals(Collections.nCopies(measurementTypes.size(), TSDataType.DOUBLE), SchemaUtils.getAggregatedDataTypes(measurementTypes, SqlConstant.SUM));
